const n=[{id:"vb13-1",s:"",gt:"Quan điểm của Chương trình: cải cách hành chính xuất phát từ lợi ích của người dân, doanh nghiệp, lấy người dân, doanh nghiệp làm trung tâm và lấy sự hài lòng của họ làm thước đo chất lượng phục vụ. Các phương án còn lại đối chủ thể thụ hưởng hoặc đối tiêu chí đo lường.",mn:'"Dân là trung tâm, hài lòng là thước đo”: giống như quán ăn muốn biết món có ngon không thì phải hội thực khách chứ không hồi người trong bếp.',t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, khi xác định cách đánh giá chất lượng phục vụ của cơ quan hành chính nhà nước các cấp, Chương trình đặt ra quan điểm cải cách hành chính phải xuất phát từ lợi ích của đối tượng nào và lấy tiêu chí nào làm thước đo?",o:["Xuất phát từ lợi ích của cơ quan hành chính; lấy sự hài lòng của cán bộ, công chức làm thước đo chất lượng phục vụ","Xuất phát từ lợi ích của người dân, doanh nghiệp; lấy sự hài lòng của người dân, doanh nghiệp làm thước đo chất lượng phục vụ","Xuất phát từ lợi ích của người dân, doanh nghiệp; lấy số lượng thủ tục được cắt giảm làm thước đo chất lượng phục vụ","Xuất phát từ lợi ích của doanh nghiệp nhà nước; lấy đánh giá của các cơ quan cấp trên làm thước đo chất lượng phục vụ"],c:1},{id:"vb13-2",s:"",cc:"Mục (Í Chương trình ban hành kèm theo liều Í Nghị quyết số 2ö NQ- ch.",gt:'Mục tiêu chung nêu nền hành chính có năng lực kiến tạo phát triển, dung sau cụm "hiệu lực, hiệu quả” và trước "liêm chính, phục vụ nhân dân”. Các cụm còn lại không có trong chuối đặc trưng này.',mn:'"Hiệu lực, hiệu quả rồi mới kiến tạo”: nhà nước không chỉ quản lý mà còn kiến tạo môi trường cho dân và doanh nghiệp phát triển, như người làm vườn chuẩn bị đất trước khi gieo.',t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, mục tiêu chung là tiếp tục xây dựng nền hành chính dân chủ, chuyên nghiệp, hiện đại, tinh gọn, hiệu lực, hiệu quả, có năng lực. ], liêm chính, phục vụ nhân dân, trên cơ sở quan điểm, chủ trương, đường lối của Đảng về đẩy mạnh toàn diện, đồng bộ công cuộc đổi mới.",o:["điều hành tập trung","hội nhập quốc tế","quản lý toàn diện","kiến tạo phát triển"],c:3},{id:"vb13-3",s:"",cc:"Mục JlÏ Chương trình ban hành kèm theo Điều 1 Nghị quyết số 70/NQ- CP.",gt:'Sáu nội dung gồm: cải cách thể chế; cải cách thủ tục hành chính; cải cách tổ chức bộ máy hành chính nhà nước; cải cách chế độ công vụ; cải cách tài chính công; xây dựng, phát triển Chính phủ điện tử, Chính phủ số. Cải cách tư pháp chỉ được nhắc ở phần quan điểm (gắn đồng bộ với cải cách hành chính), không phải một trong 6 nội dung. $® Miẹo nhớ: "Sáu nội dung, không có tư pháp”: nhớ thể chế - thủ tục - bộ máy - công vụ - tài chính - Chính phủ số; tư pháp chỉ là việc "đi cùng” chứ không năm trong danh sách.',t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, cải cách hành chính nhà nước giai đoạn 2021 - 2030 được xác định tập trung vào một số nội dung cải cách cụ thể, được liệt kê tài phán nội dung, mục tiêu, nhiệm vụ của Chương trình. Xét các nội dung dưới đây, nội dung nào KHÔNG thuộc 6 nội dung cải cách mà Chương trình tập trung thực hiện?",o:["Cải cách tư pháp","Cải cách tài chính công","Cải cách chế độ công vụ","Cải cách thủ tục hành chính"],c:0},{id:"vb13-4",s:"",cc:"Mục III Chương trình ban hành kèm theo Điều 1 Nghị quyết số 76/NQ- cP.",gt:'Ba trọng tâm: cải cách thể chế; xây dựng đội ngũ cán bộ, công chức, viên chức chuyên nghiệp (chú trọng cải cách chính sách tiền lương); xây dựng, phát triển Chính phủ điện tử, Chính phủ số. Cải cách tổ chức bộ máy là một trong 6 nội dung nhưng không năm trong 3 trọng tâm. ® Miẹo nhớ: "Ba trọng tâm: thể chế - con người - số": thể chế là luật chơi, đội ngũ là người chơi, Chính phủ số là công cụ chơi; bộ máy không năm trong ba mũi nhọn này.',t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, Chương trình xác định trọng tâm cải cách hành chính 10 năm tới, trong đó có việc xây dựng, hoàn thiện hệ thống thể chế của nền hành chính và nâng cao hiệu lực, hiệu quả tổ chức thi hành pháp luật. Nội dung nào sau đây KHÔNG thuộc trọng tâm cải cách hành chính 10 năm tới?",o:["Cải cách thể chế","Xây dựng và phát triển Chính phủ điện tử, Chính phủ số","Cải cách tổ chức bộ máy hành chính nhà nước","Xây dựng đội ngũ cán bộ, công chức, viên chức chuyên nghiệp"],c:2},{id:"vb13-5",s:"",cc:"Mục III (khoản 2) Chương trình ban hành kèm theo Điều Ì Nghị quyết số 76/NQ-CP.",gt:"Đến năm 2025, cắt giảm, đơn giản hóa tối thiểu 20% số quy định và cắt giảm tối thiểu 20% chi phí tuân thủ quy định liên quan đến hoạt động kinh doanh (mốc văn bản: hết ngày 31/5/2020).",mn:'"Hai số 20 song song”: 20% quy định, 20% chi phí -— như tia cành và giám chi phí chăm cây cùng một mức.',t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030: đến năm 2025, cắt giảm, đơn giản hóa tối thiểu [.........] số quy định và cắt giảm tối thiểu [......... ] chi phí tuân thủ quy định liên quan đến hoạt động kinh doanh tại các văn bản đang có hiệu lực thi hành tính đến hết ngày 31 tháng 5 năm 2020.",o:["10%... 10%","20%... 20%","20%... 10%","30%... 20%"],c:1},{id:"vb13-6",s:"",cc:"Mục II (khoản 2) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 70/NQ-CP.",gt:"Đến năm 2025, tối thiểu 80% hồ sơ giải quyết thủ tục hành chính được luân chuyển nội bộ giữa các cơ quan bằng phương thức điện tử. Mốc 90% là tỷ lệ thủ tục hành chính nội bộ được công bố, công khai.",mn:'"Hồ sơ di điện tử tắm phần mười": 80% hồ sơ chạy giữa các cơ quan bằng mạng thay vi người cam giấy chạy qua chạy lại.',t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, trong nhóm mục tiêu cải cách thủ tục hành chính đến năm 2025, hồ sơ giải quyết thủ tục hành chính được luân chuyển trong nội bộ giữa các cơ quan có thẩm quyền giải quyết hoặc các cơ quan có liên quan bằng phương thức điện tử phải đạt tỷ lệ tối thiểu là bao nhiêu?",o:["Tối thiểu 80% số hồ sơ được luân chuyển nội bộ giữa các cơ quan bằng phương thức điện tử","Tối thiểu 90% số hồ sơ được luân chuyển nội bộ giữa các cơ quan bằng phương thức điện tử","Tối thiểu 50% số hồ sơ được luân chuyển nội bộ giữa các cơ quan bằng phương thức điện tử","Tối thiểu 100% số hồ sơ được luân chuyển nội bộ giữa các cơ quan bằng phương thức điện tử"],c:0},{id:"vb13-7",s:"",cc:"Mục H!Ị (khoản 2) Chương trình ban hành kèm theo Điều Ì Nghị quyết võ 76/VQ-CP.",gt:"Đến năm 2025: tối thiểu 80% thủ tục có nghĩa vụ tài chính được thanh toán trực tuyến, tỷ lệ giao dịch đạt từ 30% trở lên. Mốc 100% và 50% là mục tiêu đến năm 2030.",mn:'"2025: tạm — ba; 2030: mười - nam”: 80% — 30% trước, 100% — 50% Sau,',t:"m",q:"Công ty X dự định nộp phí, lễ phí trực tuyến khi thực hiện thủ tục hành chính có yêu cầu nghĩa vụ tài chính. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, đến năm 2025, tỷ lệ tối thiểu thủ tục hành chính có yêu cầu nghĩa vụ tài chính được triển khai thanh toán trực tuyến và tỷ lệ giao dịch thanh toán trực tuyến trong số đó lần lượt là bao nhiêu?",o:["Tối thiểu 90% thủ tục được thanh toán trực tuyến, trong đó tỷ lệ giao dịch trực tuyến đạt từ 50% trở lên","Tối thiểu 100% thủ tục được thanh toán trực tuyến, trong đó tỷ lệ giao dịch trực tuyến đạt từ 50% trở lên","Tối thiểu 70% thủ tục được thanh toán trực tuyến, trong đó tỷ lệ giao dịch trực tuyến đạt từ 20% trở lên","Tối thiểu 80% thủ tục được thanh toán trực tuyến, trong đó tỷ lệ giao dịch trực tuyến đạt từ 30% trở lên"],c:3},{id:"vb13-8",s:"",gt:"Năm 2021, tỷ lệ số hóa tối thiểu tương ứng là 40% (trung ương), 30% (tỉnh), 15% (xã); cấp càng gần cơ sở thì tỷ lệ khởi điểm càng thấp. Các phương án khác đáo thứ tự giữa các cấp.",mn:'"Trên cao - dưới thấp”: 40 — 30 — 15, giảm dân từ trung ương xuống xã như bậc tháng.',t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030: năm 2021, số hóa kết quả giải quyết thủ tục hành chính đang còn hiệu lực và có giá trị sử dụng thuộc thẩm quyền giải quyết của cấp trung ương, cấp tỉnh và cấp xã đạt tỷ lệ tối thiểu tương ứng là [......... ]; giai đoạn 2022 - 2025, mỗi năm tăng tối thiểu 20% đối với mỗi cấp hành chính cho đến khi đạt 100%.",o:["30%, 40%, 15%","40%, 15%, 30%","40%, 30%, 15%","15%, 30%, 40%"],c:2},{id:"vb13-9",s:"",cc:"Mục III (khoản 2) Chương trình ban hành kèm theo Điều Ì Nghị quyết số 76/NQ-C.P.",gt:'Đến năm 2025: mức độ hài lòng chung tối thiểu 90%, riêng đất đai, xây dựng, đầu tư tối thiểu 85%. Móc 95% và 90% thuộc năm 2030. ® Miẹo nhớ: "Lĩnh vực nông thấp hơn 5 điểm": chung 90%, đất đai - xây dựng - đầu tư 85%.',t:"m",q:"Trong báo cáo kết quả cải cách hành chính của một tính, mức độ hài lòng của người dân, doanh nghiệp về giải quyết thủ tục hành chính được đo riêng và có thêm chỉ tiêu cho lĩnh vực đất đai, xây dựng, đầu tư. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, đến năm 2025, hai chỉ tiêu tối thiểu này lần lượt là bao nhiêu?",o:["Hài lòng chung tối thiểu 95%; lĩnh vực đất đai, xây dựng, đầu tư tối thiểu 90%","Hài lòng chung tối thiểu 90%; lĩnh vực đất đai, xây dựng, đầu tư tối thiểu 85%","Hài lòng chung tối thiểu 90%; lĩnh vực đất đai, xây dựng, đầu tư tối thiểu 90%","Hài lòng chung tối thiểu 85%; lĩnh vực đất đai, xây dựng, đầu tư tối thiểu 85%"],c:1},{id:"vb13-10",s:"",cc:"Mục JII (khoản 2) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 76/NQ-CP.",gt:"Đến năm 2025 tỷ lệ hồ sơ giải quyết trực tuyến mức độ 3 và 4 trên tổng số hồ sơ đạt tối thiểu 50%; đến năm 2030 là 80%. Hai mốc 80% ở đề bài là tỷ lệ thủ tục được cung cấp trực tuyến và tỷ lệ tích hợp trên Công.",mn:'"Hồ sơ trực tuyến: 50 rồi 80": 2025 là 50%, 2030 lên 80%.',t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, đến năm 2025, tối thiểu 80% thủ tục hành chính của các bộ, ngành, địa phương có đủ điều kiện được cung cấp trực tuyến mức độ 3 và 4, trong số đó ít nhất 80% được tích hợp, cung cấp trên Cổng Dịch vụ công quốc gia. Tỷ lệ hồ sơ giải quyết trực tuyến mức độ 3 và 4 trên tổng số hồ sơ đạt tối thiểu bao nhiêu?",o:["80% tổng số hồ sơ, bảng với tỷ lệ thủ tục hành chính có đủ điều kiện của các bộ, ngành, địa phương được cung cấp trực tuyến mức độ 3 và 4","90%","70%","50%"],c:3},{id:"vb13-11",s:"",cc:"Mục III (khoản 2) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 76/NQ-CP.",gt:"Đến năm 2030, môi trường kinh doanh của Việt Nam được xếp vào nhóm 30 quốc gia hàng đầu. Các còn số 50 và 70 là nhóm nước dẫn đầu về Chính phủ điện tử (EGDI) ở các mốc 2030 và 2025.",mn:'"Kinh doanh 30, Chính phủ điện tử 50”: môi trường kinh doanh top 30, còn EGDI top 50 vào năm 2030.',t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030: đến năm 2030, môi trường kinh doanh của Việt Nam được xếp vào nhóm |......... ] hàng đầu, đồng thời mức độ hài lòng của người dân, doanh nghiệp về giải quyết thủ tục hành chính đạt tối thiểu 95%.",o:["30 quốc gia","50 quốc gia","70 quốc gia","20 quốc gia"],c:0},{id:"vb13-12",s:"",cc:"Mục!II (khoản 2) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 70NQ-C.P.",gt:"Nhiệm vụ đẩy mạnh phân cấp: cấp nào sát cơ sở, sát nhân dân nhất thì giao cho cấp đó giải quyết, bảo đảm nguyên tắc quản lý ngành, lãnh thổ, không để nhiều tầng nấc, kéo dài thời gian và gây nhũng nhiễu, tiêu cực, phiền hà.",mn:'"Gần dân giải quyết trước”: như việc nhỏ trong nhà thì người trong nhà xử lý, không phải đi lên nhiều tầng.',t:"m",q:"Ông D là cán bộ của một tỉnh, qua rà soát nhận thấy việc giải quyết một số thủ tục hành chính còn qua nhiều tầng nấc, kéo dài thời gian và gây phiền hà cho người dân. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, hướng đẩy mạnh phân cấp giải quyết thủ tục hành chính phù hợp trong trường hợp này là gì?",o:["Giao cho cấp có thẩm quyền cao nhất tại Trung ương trực tiếp giải quyết toàn bộ các thủ tục, bảo đảm nguyên tắc quản lý ngành, lãnh thổ, tập trung đầu mối để thống nhất cách giải quyết trên phạm vi cả nước","Giao cho cấp trung gian giải quyết","Giao cho cấp sát cơ sở, sát nhân dân nhất giải quyết","Giao cho cấp có nhiều hồ sơ nhất"],c:2},{id:"vb13-13",s:"",cc:"Vục HÍ (khoản 1) Chương trình ban hành kèm theo Điều 1 Nghị quyết số NQO-CP.",gt:"Mục tiêu cải cách thể chế đến năm 2025: cơ bản hoàn thiện hệ thống thể chế của nền hành chính nhà nước, trọng tâm là thể chế về tổ chức bộ máy và quản lý cán bộ, công chức, viên chức.",mn:"“Thể chế 2025 lo bộ máy và con người”: bộ máy + cán bộ là phân cần hoàn thiện trước.",t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030: đến năm 2025, cơ bản hoàn thiện hệ thống thể chế của nền hành chính nhà nước, trọng tâm là thể chế về [......... cao hiệu lực, hiệu quả quản lý nhà nước và năng lực kiến tạo phát triển.",o:["tổ chức bộ máy và quản lý cán bộ, công chức, viên chức","tài chính công và quản lý ngân sách nhà nước","đất đai, tài nguyên và bảo vệ môi trường","chuyển đổi số và dịch vụ công trực tuyến"],c:0},{id:"vb13-14",s:"",gt:"Đến năm 2025, 90% thủ tục hành chính nội bộ giữa các cơ quan hành chính nhà nước được công bố, công khai và cập nhật kịp thời. Mốc 80% là tỷ lệ người dân, doanh nghiệp không phải cung cấp lại giấy tờ đã có.",mn:'"Nội bộ cùng phải công khai 90”: thủ tục nội bộ được công bố 90%, thấp hơn mức "trọn ven” 100%.',t:"m",q:"Bà E là công chức phụ trách kiểm soát thủ tục hành chính của một bộ, đang rà soát, thống kê các thủ tục hành chính nội bộ giữa các cơ quan hành chính nhà nước để công bố. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, đến năm 2025, mục tiêu về công bố, công khai thủ tục hành chính nội bộ được xác định như thế nào?",o:["Đạt 80% thủ tục hành chính nội bộ được công bố, công khai và cập nhật kịp thời","Đạt 100% thủ tục hành chính nội bộ được công bố, công khai và cập nhật kịp thời","Đạt 70% thủ tục hành chính nội bộ được công bố, công khai và cập nhật kịp thời","Đạt 90% thủ tục hành chính nội bộ được công bố, công khai và cập nhật kịp thời"],c:3},{id:"vb13-15",s:"",cc:"Mục JÍ (khoản 2) Chương trình ban hành kèm theo Điều 1 NVabị quyết SỐ 70NQ-CP.",gt:"Đến năm 2025. 80% người dân, doanh nghiệp không phải cung cấp lại thông tin, giấy tờ, tài liệu đã được chấp nhận trước đó mà cơ quan nhà nước đang quản lý hoặc đã kết nối, chia sẻ.",mn:'"Một lần nộp, tạm phần dùng lại”: 80% người dân không phải khai lại, giống như đã khai ở bệnh viện thì lần sau không phải khai lại từ đầu.',t:"m",q:"Bà C vừa hoàn thành thành công một thủ tục hành chính, sau đó thực hiện thủ tục khác mà cơ quan có thẩm quyền đăng quản lý hoặc đã kết nối, chia sẻ các giấy tờ Bà đã nộp trước đó. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, đến năm 2025, tối thiểu bao nhiêu phần trăm người dân, doanh nghiệp không phải cung cấp lại các giấy tờ này?",o:["90% người dân, doanh nghiệp, áp dụng đối với thông tin, giấy tờ mà chính cơ quan đang giải quyết hồ sơ đã trực tiếp thu thập trong cùng một lần nộp trước đó","80%","100%","70%"],c:1},{id:"vb13-16",s:"",cc:"Mục II (khoản 2) Chương trình ban hành kèm theo Điều Ì Nghị quyết số 76 NQ-CP.",gt:"Đến năm 2030, 90% số lượng người dân. doanh nghiệp tham gia hệ thống Chính phủ điện tử được xác thực định danh điện tử thông suốt và hợp nhất; mốc 100% thuộc năm 2025 nhưng áp dụng cho người sử dụng dịch vụ công trực tuyến.",mn:'"2025 phủ 100% người đứng, 2030 phủ 90% người tham gia”: đối tượng khác nhau nên còn số khác nhau.',t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, ở nhóm mục tiêu năm 2025, 100% người dân, doanh nghiệp sử dụng dịch vụ công trực tuyến được cấp định danh và xác thực điện tử. Đến năm 2030, tỷ lệ người dân, doanh nghiệp tham gia hệ thống Chính phủ điện tử được xác thực định danh điện tử thông suốt và hợp nhất là bao nhiêu?",o:["100% số người dân, doanh nghiệp tham gia hệ thống Chính phủ điện tử được xác thực định danh điện tử thông suốt và hợp nhất","80% số người dân, doanh nghiệp tham gia hệ thống Chính phủ điện tử được xác thực định danh điện tử thông suốt và hợp nhất","90% số người dân, doanh nghiệp tham gia hệ thống Chính phủ điện tử được xác thực định danh điện tử thông suốt và hợp nhất","70% số người dân, doanh nghiệp tham gia hệ thống Chính phủ điện tử được xác thực định danh điện tử thông suốt và hợp nhất"],c:2},{id:"vb13-17",s:"",cc:"Mục 1Ï (khoản 1) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 7b, NQ-CP.",gt:"Nhiệm vụ: đổi mới, hoàn thiện quy trình lập pháp, lập quy theo hướng chặt chẽ, khoa học, hiện đại, chuyên nghiệp; tăng cường tham vấn hiệp hội, chuyên gia, nhà khoa học và người dân, tổ chức để bảo đảm tính minh bạch, nhất quán, ổn định, dự đoán được của pháp luật.",mn:'"Soạn luật phải hỏi dân và chuyên gia”: như nấu ăn cho nhiều người thì nếm thu và hội ý kiến trước khi đơn.',t:"m",q:"Khi xây dựng, ban hành văn bản quy phạm pháp luật, một cơ quan soạn thảo muốn bảo đảm pháp luật minh bạch, nhất quán, ổn định và dự đoán được. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, nhiệm vụ nâng cao chất lượng công tác xây dựng pháp luật theo hướng nào là phù hợp?",o:["Đổi mới quy trình lập pháp, lập quy theo hướng rút ngắn tối đa thời gian soạn thảo, hạn chế lấy ý kiến rộng rãi để ban hành nhanh các văn bản có liên quan trực tiếp đến người dân, doanh nghiệp và các tổ chức xã hội","Giữ ổn định quy trình hiện hành; tăng cường tham vấn cơ quan cấp trên","Đổi mới quy trình; chỉ lấy ý kiến cơ quan nhà nước","Đổi mới quy trình lập pháp, lập quy; tăng cường tham vấn chuyên gia, nhà khoa học và người dân"],c:3},{id:"vb13-18",s:"",cc:"Mục II (khoản 2) Chương trình ban hành kèm theo Điều Ì Nghị quyết số 76/NQ-CP.",gt:"Mục tiêu của cải cách thủ tục hành chính: đẩy mạnh thực hiện trên môi trường điện tử để người dân, doanh nghiệp thực hiện dịch vụ mọi lúc, mọi nơi, trên các phương tiện khác nhau.",mn:'"Mọi lúc - mọi nơi - mọi thiết bị”: dịch vụ công như cửa hàng mở 24/7 trong điện thoại.',t:"m",q:"Công ty X muốn thực hiện thủ tục hành chính vào buối tối, ngay tại văn phòng của mình, bằng nhiều thiết bị khác nhau mà không phải đến trực tiếp cơ quan nhà nước. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, việc đẩy mạnh thực hiện thủ tục hành chính trên môi trường điện tử nhằm mục đích gì?",o:["Để người dân, doanh nghiệp thực hiện dịch vụ mọi lúc, mọi nơi, trên các phương tiện khác nhau","Để người dân, doanh nghiệp thực hiện dịch vụ theo địa giới hành chính, trên các phương tiện do cơ quan quy định","Để người dân, doanh nghiệp thực hiện dịch vụ mọi lúc, mọi nơi nhưng phải qua mấy tính của cơ quan","Để cơ quan giảm số thủ tục, còn người dân thực hiện tại bộ phận một cửa vào giờ hành chính"],c:0},{id:"vb13-19",s:"",cc:"Mục Í Chương trình ban hành kèm theo Điều 1 Nghị quyết số 76/NQ-CP.",gt:"Các quan điểm gồm: coi cải cách hành chính là đột phá và gắn đồng bộ với cải cách lập pháp, tư pháp; lấy người dân, doanh nghiệp làm trung tâm; tiến hành đồng bộ, thống nhất, có trọng tâm, trọng điểm; gắn với chuyên đổi số; kế thừa và tiếp thu kinh nghiệm quốc tế. Không có quan điểm cải cách Trung ương trước, địa phương sau.",mn:'"Đồng bộ, không chia trước sau”: cải cách làm cùng nhịp các cấp, không đối Trung ương xong mới đến địa phương. Phạm vi: nội dung 3 (cải cách tổ chức bộ máy hành chính nhà nước), nội dung 4 (cải cách chế độ công vụ) và nội dung 5 (cải cách tài chính công) với mục tiêu, chỉ tiêu đến năm 2025 và 2030 cùng các nhiệm vụ trọng tôm.',t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, Chương trình nêu các quan điểm chỉ đạo việc cải cách hành chính giai đoạn 2021 - 2030, gồm cả yêu cầu gắn với cải cách lập pháp, cải cách tư pháp và việc kế thừa thành tựu đã đạt được. Phương án nào sau đây KHÔNG phải là quan điểm được nêu trong Chương trình?",o:["Gắn cải cách hành chính đồng bộ với cải cách lập pháp, cải cách tư pháp","Tiến hành các nội dung cải cách đồng bộ, thống nhất, có trọng tâm, trọng điểm","Ưu tiên cải cách ở Trung ương trước, các địa phương chỉ thực hiện sau khi có kết quả thí điểm","Kế thừa thành tựu đã đạt được và tiếp thu kinh nghiệm thành công của các nước"],c:2},{id:"vb13-20",s:"PHẦN 2 - CẢI CÁCH TỔ CHỨC BỘ MÁY, CẢI CÁCH CHẾ ĐỘ CÔNG VỤ VÀ CẢI CÁCH TÀI CHÍNH CÔNG",cc:"Mục III (khoản 3) Chương trình ban hành kèm theo Điều Ì Nghị quyết số 76NQ-CP.",gt:"Đến năm 2025, giảm tối thiểu bình quân cả nước 10% số lượng đơn vị sự nghiệp công lập và 10% biên chế sự nghiệp hưởng lương từ ngân sách nhà nước so với nam 2021.",mn:'"Đơn vị và biên chế cùng giảm một phần mười”: 10% - 10%.',t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030: đến năm 2025, giảm tối thiểu bình quân cả nước [........ ] số lượng đơn vị sự nghiệp công lập và |[........ ] biên chế sự nghiệp hưởng lương từ ngân sách nhà nước so với năm 2021.",o:["15%... 15%","10%... 10%","5%... 10%","10%... 15%"],c:1},{id:"vb13-21",s:"PHẦN 2 - CẢI CÁCH TỔ CHỨC BỘ MÁY, CẢI CÁCH CHẾ ĐỘ CÔNG VỤ VÀ CẢI CÁCH TÀI CHÍNH CÔNG",cc:"Mục II (khoản 3) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 76/NQ-CP.",gt:"Đến năm 2030, tiếp tục giảm bình quân 10% biên chế sự nghiệp hưởng lương từ ngân sách nhà nước so với năm 2025. Mộc 15% là mức giảm chi trực tiếp từ ngân sách cho đơn vị sự nghiệp công lập.",mn:'"Mỗi chặng giảm thêm một phần mười”: 2025 giảm 10% so với 2021, 2030 giám 10% so với 2025.',t:"m",q:"Ông G là cán bộ phụ trách tổ chức, biên chế của tỉnh Ý; tính đã hoàn thành mục tiêu giảm biên chế sự nghiệp hưởng lương từ ngân sách nhà nước đến năm 2025. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, mục tiêu tiếp theo đến năm 2030 về biên chế sự nghiệp được xác định như thế nào?",o:["Tiếp tục giảm bình quân 10% biên chế sự nghiệp so với năm 2021","Tiếp tục giảm bình quân 15% biên chế sự nghiệp so với năm 2025","Tiếp tục giảm bình quân 5% biên chế sự nghiệp so với năm 2025","Tiếp tục giảm bình quân 10% biên chế sự nghiệp so với năm 2025"],c:3},{id:"vb13-22",s:"PHẦN 2 - CẢI CÁCH TỔ CHỨC BỘ MÁY, CẢI CÁCH CHẾ ĐỘ CÔNG VỤ VÀ CẢI CÁCH TÀI CHÍNH CÔNG",cc:"Mục II (khoản 3) Chương trình ban hành kèm theo Điều Ì Nghị quyết số",gt:"Đến năm 2025: hài lòng với sự phục vụ của cơ quan hành chính nhà nước tối thiểu 90%; hài lòng về dịch vụ y tế, giáo dục công lập tối thiểu 85%. Mốc 95% và 90% là của năm 2030.",mn:'"Dịch vụ v tế, giáo dục thấp hơn 5 điểm”: 90% chung, 85% y tế — giáo dục (2025).',t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, đề đó chất lượng phục vụ của bộ máy hành chính, Chương trình đặt mục tiêu đến năm 2025 về mức độ hài lòng của người dân, tổ chức đối với sự phục vụ của cơ quan hành chính nhà nước và đối với dịch vụ y tế, giáo dục công lập. Hai chỉ tiêu tối thiểu này lần lượt là bao nhiêu?",o:["Hài lòng với sự phục vụ của cơ quan hành chính tối thiểu 90%; với dịch vụ y tế, giáo dục công lập tối thiểu 85%","Hài lòng với sự phục vụ của cơ quan hành chính tối thiểu 95%; với dịch vụ y tế, giáo dục công lập tối thiểu 90%","Hài lòng với sự phục vụ của cơ quan hành chính tối thiểu 85%; với dịch vụ y tế, giáo dục công lập tối thiểu 80%","Hài lòng với sự phục vụ của cơ quan hành chính tối thiểu 90%; với dịch vụ y tế, giáo dục công lập tối thiểu 90%"],c:0},{id:"vb13-23",s:"PHẦN 2 - CẢI CÁCH TỔ CHỨC BỘ MÁY, CẢI CÁCH CHẾ ĐỘ CÔNG VỤ VÀ CẢI CÁCH TÀI CHÍNH CÔNG",cc:'Mục HH (khoản 3) Chương trình ban hành kèm theo Điều 1 Nghị quyết số "06NQ-CP.',gt:"Đến năm 2030: tiếp tục sắp xếp, kiện toàn cơ cấu tổ chức Chính phủ theo hướng giảm hợp lý đầu mối các bộ, cơ quan ngang bộ, giảm tương ứng số cơ AQ.ở XQg-C.PCCIHUC 021-2030 rang t2 quan chuyên môn thuộc Ủy ban nhân dân cấp tỉnh và giảm mạnh đầu mối các tổ chức trung gian.",mn:'"Bỏ giảm hợp lý, trung gian giảm mạnh”: phân trung gian là phân bị cắt mạnh nhất.',t:"m",q:"Một hội thảo bàn về hướng sắp xếp cơ cấu tổ chức Chính phủ đến năm 2030. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, mục tiêu cải cách tổ chức bộ máy đến năm 2030 về cơ cấu tổ chức Chính phủ được xác định là gì?",o:["Giữ ổn định số đầu mối các bộ, cơ quan ngang bộ; giảm mạnh đầu mối các tổ chức trung gian của địa phương","Giảm hợp lý đầu mối các bộ, cơ quan ngang bộ; giảm mạnh đầu mối các tổ chức trung gian","Giảm mạnh đầu mối các bộ, cơ quan ngang bộ để thay thế bằng việc tăng số tổ chức trung gian có chức năng tư vấn, hỗ trợ thực hiện các nhiệm vụ quản lý nhà nước của các bộ và các địa phương trong cả nước","Giảm hợp lý đầu mối các bộ, cơ quan ngang bộ; tăng tương ứng số cơ quan chuyên môn thuộc Ủy ban nhân dân cấp tỉnh"],c:1},{id:"vb13-24",s:"PHẦN 2 - CẢI CÁCH TỔ CHỨC BỘ MÁY, CẢI CÁCH CHẾ ĐỘ CÔNG VỤ VÀ CẢI CÁCH TÀI CHÍNH CÔNG",cc:"Mục II (khoản 3) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 76/NQ-(P.",gt:"Nguyên tắc: một tổ chức có thể đảm nhiệm nhiều việc, nhưng một việc chỉ do một tổ chức chủ trì và chịu trách nhiệm chính. Các phương án khác đáo quan hệ giữa số việc và số tổ chức chủ trì.",mn:'"Nhiều việc một đầu mối, một việc một chủ”: mỗi việc có một người cam trịch thì không đùn đẩy.',t:"m",q:"Trường hợp qua rà soát, một bộ và một số phát hiện hai tổ chức cùng chủ trì thực hiện một nhiệm vụ nên xảy ra chồng chéo, trùng lắp chức năng. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, nguyên tắc sắp xếp tổ chức bộ máy nào sau đây là dùng đề khác phục tình trạng này?",o:["Một tổ chức chỉ đảm nhiệm một việc, nhưng một việc có thể do nhiều tổ chức cùng chủ trì và chịu trách nhiệm chính","Một tổ chức có thế đảm nhiệm nhiều việc, và một việc có thể do nhiều tổ chức cùng chủ trì và chịu trách nhiệm chính","Một tổ chức có thế đảm nhiệm nhiều việc, nhưng một việc chỉ do một tổ chức chủ trì và chịu trách nhiệm chính","Một tổ chức chỉ đảm nhiệm một việc, và một việc chỉ do một tổ chức chủ trì và chịu trách nhiệm chính"],c:2},{id:"vb13-25",s:"PHẦN 2 - CẢI CÁCH TỔ CHỨC BỘ MÁY, CẢI CÁCH CHẾ ĐỘ CÔNG VỤ VÀ CẢI CÁCH TÀI CHÍNH CÔNG",cc:"Mục JII (khoản 4) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 76/NQ-CP.",gt:"Mục tiêu cải cách chế độ công vụ: xây dựng nên công vụ chuyên nghiệp, trách nhiệm, năng động và thực tài. Các phương án khác là đặc trưng của nền VQ 7b'NO-CP CCHC 2021-2030 Irang 1ì hành chính (mục tiêu chung), mục tiêu về đội ngũ năm 2030 hoặc nhiệm vụ cơ cấu lại đội ngũ.",mn:'"Thực tài” là điểm nhân của công vụ: chuyên nghiệp - trách nhiệm — năng động - thực tài, như tuyến người giới thật chứ không chỉ có bảng.',t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, mục tiêu cải cách chế độ công vụ là xây dựng nền công vụ có những đặc điểm nào sau đây, đồng thời thực hiện cơ chế cạnh tranh lành mạnh, dân chủ, công khai, minh bạch trong bổ nhiệm, đề bạt cán bộ và tuyển dụng công chức, viên chức?",o:["Dân chủ, chuyên nghiệp, hiện đại, tinh gọn","Chuyên nghiệp, có chất lượng cao, cơ cấu hợp lý","Đúng người, đúng việc, nâng cao chất lượng","Chuyên nghiệp, trách nhiệm, năng động và thực tài"],c:3},{id:"vb13-26",s:"PHẦN 2 - CẢI CÁCH TỔ CHỨC BỘ MÁY, CẢI CÁCH CHẾ ĐỘ CÔNG VỤ VÀ CẢI CÁCH TÀI CHÍNH CÔNG",cc:"Mục III (khoản 4) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 70NQ-CP.",gt:"Đến năm 2030, 100% cán bộ, công chức cấp xã có trình độ cao đẳng, đại học và được chuẩn hóa về lý luận chính trị, chuyên môn, nghiệp vụ, kỹ năng làm việc.",mn:'"Cấp xã phải đủ 100": công chức cấp xã đạt chuẩn trọn vẹn, vì đây là nơi trực tiếp tiếp xúc với dân.',t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030: đến năm 2030, [......... ] cán bộ, công chức cấp xã có trình độ cao đẳng, đại học và được chuẩn hóa về lý luận chính trị, chuyên môn, nghiệp vụ, kỹ năng làm việc.",o:["80%","100%","90%","70%"],c:1},{id:"vb13-27",s:"PHẦN 2 - CẢI CÁCH TỔ CHỨC BỘ MÁY, CẢI CÁCH CHẾ ĐỘ CÔNG VỤ VÀ CẢI CÁCH TÀI CHÍNH CÔNG",cc:"Mục 1HI (khoản 4) Chương trình ban hành kèm theo Điều ÌI Nghị quyết số 76/NQ-(.P.",gt:"Đến năm 2030: 50% - 60% số lãnh đạo, quản lý cấp phòng, vụ, cục, tổng cục và tương đương ở Trung ương. Móc 25% - 35% là cấp sở, ngành; 80% là lãnh đạo, quản lý doanh nghiệp nhà nước.",mn:'"Cảng lên cao càng cần ngoại ngữ”: Trung ương 50 — 60%, cấp sở 25 — 35%.',t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, Chương trình đặt mục tiêu đến năm 2030 về tỷ lệ lãnh đạo, quản lý có đủ khả năng làm việc trong môi trường quốc tế. Tỷ lệ này đối với lãnh đạo, quản lý cấp phòng, vụ, cục, tổng cục và tương đương ở Trung ương là bao nhiêu?",o:["Từ 50% đến 60% số lãnh đạo, quản lý cấp phòng, vụ, cục, tổng cục và tương đương ở Trung ương","Từ 25% đến 35% số lãnh đạo, quản lý cấp phòng, vụ, cục, tổng cục và tương đương ở Trung ương","Trên 30% số lãnh đạo, quản lý cấp phòng, vụ, cục, tổng cục và tương đương ở Trung ương","Từ 80% số lãnh đạo, quản lý cấp phòng, vụ, cục, tổng cục và tương đương ở Trung ương"],c:0},{id:"vb13-28",s:"PHẦN 2 - CẢI CÁCH TỔ CHỨC BỘ MÁY, CẢI CÁCH CHẾ ĐỘ CÔNG VỤ VÀ CẢI CÁCH TÀI CHÍNH CÔNG",cc:"Mục 1Ï (khoản 4) Chương trình ban hành kèm theo Điều Ì Nghị quyết số 7b/NQ-C.P.",gt:"Đến năm 2030: 25% - 35% số lãnh đạo, quản lý cấp sở, ngành và tương đương. Móc 50% - 60% là cấp ở Trung ương: trên 30% là cấp phòng trực thuộc sở, ngành.",mn:'"Sở thấp hơn Trung ương”: cấp sở 25 - 35%, còn cấp phòng thuộc sở là trên 30%.',t:"m",q:"Một số đang đánh giá khả năng làm việc trong môi trường quốc tế của đội ngũ lãnh đạo, quản lý. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, đến năm 2030, tỷ lệ lãnh đạo, quản lý cấp sở, ngành và tương đương có đủ khả năng này được xác định ở mức nào?",o:["Từ 50% đến 60% số lãnh đạo, quản lý cấp sở, ngành và tương đương","Trên 30% số lãnh đạo, quản lý cấp sở, ngành và tương đương","Từ 25% đến 35% số lãnh đạo, quản lý cấp sở, ngành và tương đương","Từ 80% số lãnh đạo, quản lý cấp sở, ngành và tương đương"],c:2},{id:"vb13-29",s:"PHẦN 2 - CẢI CÁCH TỔ CHỨC BỘ MÁY, CẢI CÁCH CHẾ ĐỘ CÔNG VỤ VÀ CẢI CÁCH TÀI CHÍNH CÔNG",cc:"Mục JII (khoản 4) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 7ở.NQ-C.P.",gt:"Nhiệm vụ: xây dựng, ban hành quy định thực hiện thống nhất việc kiểm định chất lượng đầu vào công chức, làm cơ sở cho các bộ, ngành, địa phương lựa chọn, tuyển dụng theo yêu cầu, nhiệm vụ; đồng thời tăng cường phân cấp kiểm định theo lĩnh vực đặc thù và vùng, khu vực.",mn:"“Một thước đo đầu vào”: như thí chứng chỉ chung để các nơi cùng dụng một thước khi chọn người.",t:"m",q:"Bộ A và Ủy ban nhân dân tỉnh B cùng tổ chức tuyển dụng công chức nhưng mọi nơi tự áp dụng cách đánh giá chất lượng đầu vào khác nhau, gây khó so sánh. Trường hợp này, theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, nhiệm vụ nào sau đây phù hợp đề khắc phục tình trạng đó?",o:["Giao một cơ quan trung ương trực tiếp tổ chức tuyển dụng toàn bộ công chức thay cho các bộ, ngành, địa phương","Đề mới bộ, ngành, địa phương tự quyết định cách kiểm định chất lượng đầu vào theo nhu cầu riêng","Bãi bỏ việc kiểm định chất lượng đầu vào và chuyển sang xét tuyển theo hồ sơ đề nghị của cơ quan sử dụng","Ban hành quy định thực hiện thống nhất việc kiểm định chất lượng đầu vào công chức, làm cơ sở cho các bộ, ngành, địa phương lựa chọn, tuyển dụng"],c:3},{id:"vb13-30",s:"PHẦN 2 - CẢI CÁCH TỔ CHỨC BỘ MÁY, CẢI CÁCH CHẾ ĐỘ CÔNG VỤ VÀ CẢI CÁCH TÀI CHÍNH CÔNG",cc:"Vục II (khoản 4) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 7U NQ-CP.",gt:"Chương trình nêu nhiệm vụ xây dựng và triển khai Chiến lược quốc gia về thu hút và trọng dụng nhân tài giai đoạn 2021 - 2030. Các phương án còn lại là tôn gọi không được nêu trong nhiệm vụ này.",mn:'"Thu hút rôi mới trọng dụng": thu hút — trọng dụng nhân tài di liên, như mới được khách còn phải biết giữ khách.',t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030: để thu hút và trọng dụng nhân tài trong quản lý, quản trị nhà nước, khoa học, công nghệ và đối mới sáng tạo, Chương trình đề ra nhiệm vụ xây dựng và triển khai có hiệu quả [........ ] giai đoạn 2021 - 2030.",o:["Chiến lược quốc gia về thu hút và trọng dụng nhân tài","Chiến lược quốc gia về phát triển nguồn nhân lực chất lượng cao","Đề án quốc gia về cải cách chính sách tiền lương công chức","Chương trình quốc gia về đào tạo, bồi dưỡng nhân tài trẻ"],c:0},{id:"vb13-31",s:"PHẦN 2 - CẢI CÁCH TỔ CHỨC BỘ MÁY, CẢI CÁCH CHẾ ĐỘ CÔNG VỤ VÀ CẢI CÁCH TÀI CHÍNH CÔNG",cc:"VMục JJI (khoon 3) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 7U NQ-CP.",gt:"Nhiệm vụ: kịp thời phát hiện và xử lý nghiêm những người có sai phạm, kể cả khi đã chuyển công tác hoặc nghỉ hưu. Các phương án khác thu hẹp đối tượng hoặc hạ mức xử lý.",mn:'"Nghỉ hưu không xóa trách nhiệm”: sai phạm đi theo người, dự chuyển công tác hay nghỉ hưu vẫn bị xử lý nghiêm.',t:"m",q:"Ông B nguyên là Giám đốc một số, đã nghỉ hưu; sau khi nghỉ hưu mới phát hiện thời gian đương chức Ông B có sai phạm trong công tác cán bộ. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, theo nhiệm vụ hoàn thiện kỷ luật, kỷ cương hành chính, cách xử lý phù hợp là gì?",o:["Kịp thời phát hiện và xử lý nghiêm người có sai phạm, nhưng chỉ áp dụng khi người đó còn giữ chức vụ tại cơ quan","Kịp thời phát hiện và xử lý nghiêm người có sai phạm, kể cả khi đã chuyển công tác hoặc nghỉ hưu","Kịp thời phát hiện và nhắc nhở người có sai phạm, kể cả khi đã chuyển công tác hoặc nghỉ hưu","Kịp thời phát hiện và xử lý nghiêm người có sai phạm, nhưng chỉ áp dụng khi người đó chuyển sang cơ quan khác"],c:1},{id:"vb13-32",s:"PHẦN 2 - CẢI CÁCH TỔ CHỨC BỘ MÁY, CẢI CÁCH CHẾ ĐỘ CÔNG VỤ VÀ CẢI CÁCH TÀI CHÍNH CÔNG",cc:"Mục III (khoản 5) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 76/NQ-C.P.",gt:"Đến năm 2025, tối thiểu 20% đơn vị sự nghiệp công lập tự bảo đảm chi thường xuyên. Không nhâm với mục tiêu 100% đơn vị sự nghiệp kinh tế và sự nghiệp khác có đủ điều kiện.",mn:'"Hai mươi phần trăm tự lo chi thường xuyên”: 20% đơn vị tự trang trải việc chỉ đều đặn hằng năm.',t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030: đến năm 2025, có tối thiểu [.........] đơn vị sự nghiệp công lập tự bảo đảm chi thường xuyên; 100% đơn vị sự nghiệp kinh tế và sự nghiệp khác có đủ điều kiện hoàn thành việc chuyển đổi thành công ty cũ phần hoặc chuyển sang tự bảo đảm chi thường xuyên và chỉ đầu tư.",o:["10%","30%","20%","50%"],c:2},{id:"vb13-33",s:"PHẦN 2 - CẢI CÁCH TỔ CHỨC BỘ MÁY, CẢI CÁCH CHẾ ĐỘ CÔNG VỤ VÀ CẢI CÁCH TÀI CHÍNH CÔNG",cc:"Mục!II (khoản 5) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 70NQ-C.P.",gt:"Đến năm 2030, giảm bình quân 15% chi trực tiếp từ ngân sách nhà nước cho đơn vị sự nghiệp công lập so với giai đoạn 2021 - 2025. Mức 10% là mức giảm biên chế sự nghiệp.",mn:'"Chi giảm 15, biên chế giám 10”: 15% là tiền ngân sách, 10% là biên chế.',t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, về cải cách tài chính công, đến năm 2030 Chương trình đặt mục tiêu giảm bình quân một tỷ lệ chi trực tiếp từ ngân sách nhà nước cho đơn vị sự nghiệp công lập, so với giai đoạn 2021 - 2025. Tỷ lệ giảm bình quân đó là bao nhiêu?",o:["15%","10% chi trực tiếp từ ngân sách nhà nước cho đơn vị sự nghiệp công lập so với năm 2021, đồng thời giảm 15% số lượng đơn vị sự nghiệp công lập","20%","5%"],c:0},{id:"vb13-34",s:"PHẦN 2 - CẢI CÁCH TỔ CHỨC BỘ MÁY, CẢI CÁCH CHẾ ĐỘ CÔNG VỤ VÀ CẢI CÁCH TÀI CHÍNH CÔNG",cc:"Mục Í (khoản 5) Chương trình ban hành kèm theo Pieu 1 Xobi quyết vụ 7G'NQ-CP.",gt:"Mục tiêu: đổi mới mạnh mẽ cơ chế phân bố, sử dụng ngân sách nhà nước cho cơ quan hành chính, đơn vị sự nghiệp công lập gắn với nhiệm vụ được giao và sản phẩm đầu ra, nâng cao tính tự chủ, tự chịu trách nhiệm.",mn:'"Tiền theo việc, không theo đầu người”: làm việc gì, ra sản phẩm gì thì được phân bổ theo đó.',t:"m",q:"Khi xây dựng dự toán cho một đơn vị sự nghiệp công lập, cơ quan tài chính cân nhắc việc phân bổ ngân sách theo nhiệm vụ được giao thay vì chia bình quân. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, mục tiêu của cải cách tài chính công về cơ chế phân b6, sử dụng ngân sách nhà nước là gì? VXQ 7op'NQO-CP CCHC 2021-2030 rang 17",o:["Chia ngân sách đều cho các đơn vị cùng loại để bảo đảm công bằng giữa các đơn vị trong cùng một hệ thống","Duy trì mức phân bố theo biên chế hiện có","Tăng mức phân bố theo số thủ của đơn vị","Đổi mới mạnh mẽ cơ chế phân bổ gắn với nhiệm vụ được giao và sản phẩm đầu ra"],c:3},{id:"vb13-35",s:"PHẦN 2 - CẢI CÁCH TỔ CHỨC BỘ MÁY, CẢI CÁCH CHẾ ĐỘ CÔNG VỤ VÀ CẢI CÁCH TÀI CHÍNH CÔNG",cc:"Mục ]lÍ (khoản 5) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 76 NQ-CP,",gt:"Nhiệm vụ: chuyển từ hỗ trợ theo cơ chế cấp phát bình quân sang cơ chế Nhà nước đặt hàng, giao nhiệm vụ cung cấp dịch vụ sự nghiệp công căn cứ vào chất lượng đầu ra hoặc đấu thầu cung cấp dịch vụ.",mn:'"Đặt hàng theo chất lượng”: như thuê dịch vụ thì tra tiên theo kết quả nhận được, không chia đều.',t:"m",q:"Bệnh viện công lập X hiện được ngân sách nhà nước hỗ trợ theo cơ chế cấp phát bình quân. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, nhiệm vụ về cơ chế tài chính đối với dịch vụ sự nghiệp công đòi hỏi chuyển sang cơ chế nào?",o:["Chuyển sang cấp phát theo số giường bệnh và số nhân sự hiện có","Nhà nước đặt hàng, giao nhiệm vụ hoặc đấu thầu cung cấp dịch vụ căn cứ chất lượng đầu ra","Chuyển sang cơ chế Nhà nước đặt hàng, giao nhiệm vụ căn cứ vào quy mô đơn vị và số lượng biên chế được giao hằng năm cho đơn vị cung cấp dịch vụ","Chuyển sang tự thu, tự chỉ hoàn toàn"],c:1},{id:"vb13-36",s:"PHẦN 2 - CẢI CÁCH TỔ CHỨC BỘ MÁY, CẢI CÁCH CHẾ ĐỘ CÔNG VỤ VÀ CẢI CÁCH TÀI CHÍNH CÔNG",cc:"Mục III (khoản 3) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 70/NQ-CP.",gt:'Mốc so sánh của giai đoạn 2030 là năm 2025, không phải năm 2021. Do đó nhận định "giảm thêm 10% so với năm 2021” là sai; ba nhận định còn lại dụng.',mn:'"Mốc nào so với mốc độ": 2025 so với 2021, 2030 so với 2025.',t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, về giảm biên chế sự nghiệp hưởng lương từ ngân sách nhà nước và số lượng đơn vị sự nghiệp công lập quá hai mốc 2025 và 2030, nhận định nào sau đây SAT?",o:["Đến năm 2025 giảm tối thiểu bình quân cả nước 10% số lượng đơn vị sự nghiệp công lập so với năm 2021","Đến năm 2025 giảm tối thiểu bình quân cả nước 10% biên chế sự nghiệp hưởng lương từ ngân sách so với năm 2021 AQ.ở XQg-C.PCCIHUC 021-2030 rang ¡8","Đến năm 2030 giảm bình quân thêm 10% biên chế sự nghiệp so với năm 2021","Đến năm 2030 tiếp tục giảm bình quân 10% biên chế sự nghiệp hưởng lương từ ngân sách so với năm 2025"],c:2},{id:"vb13-37",s:"PHẦN 2 - CẢI CÁCH TỔ CHỨC BỘ MÁY, CẢI CÁCH CHẾ ĐỘ CÔNG VỤ VÀ CẢI CÁCH TÀI CHÍNH CÔNG",cc:"Mục II (khoản 3) Chương trình ban hành kèm theo Điều Ì Nghị quyết số 76:NQ-CP.",gt:"Nhiệm vụ gồm: rà soát quy định về phân cấp; ban hành cơ chế kiểm soát quyền lực, đề cao trách nhiệm giải trình; theo dõi, kiểm tra, giám sát việc thực hiện nhiệm vụ đã phân cấp. Thu hồi nhiệm vụ đã phân cấp về Trung ương không thuộc nhiệm vụ này.",mn:'"Phân cấp đi kèm kiểm soát”: giao việc xuống thì phải giao quyền, giao trách nhiệm và theo dõi, không rút lại. Phạm vi: nội dung 6 (Xây dựng và phát triển Chính phủ điện tử, Chính phủ số) với các chi tiêu đến năm 2025 và 2030; các giải pháp thực hiện: kinh phí; tổ chức thực hiện (vai trò của Bộ Nội vụ, Bộ Tư pháp và các cơ quan).',t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, nhiệm vụ tăng cường phân cấp, phân quyền mạnh mẽ, hợp lý giữa Trung ương và địa phương, giữa cấp trên và cấp dưới phải gắn với quyền hạn và trách nhiệm. Nội dung nào sau đây KHÔNG thuộc nhiệm vụ này?",o:["Rà soát, sửa đổi, bổ sung các quy định về phân cấp quản lý giữa Trung ương và địa phương","Ban hành cơ chế, chính sách kiểm soát quyền lực chặt chẽ, đề cao trách nhiệm giải trình","Theo dõi, kiểm tra, giám sát hiệu quả việc thực hiện các nhiệm vụ đã phân cấp","Chuyến toàn bộ nhiệm vụ đã phân cấp về Trung ương để thống nhất quản lý"],c:3},{id:"vb13-38",s:"PHẦN 3 - CHÍNH PHỦ ĐIỆN TỬ, CHÍNH PHỦ SỐ; GIẢI PHÁP, KINH PHÍ VÀ TỔ CHỨC THỰC HIỆN",cc:"Mục HÏ (khoản 0) Chương trình ban hành kèm theo Điều Í Nghị quyết số 7® NÓ-CP.",gt:"Đến năm 2025: 90% hồ sơ công việc tại cấp bộ, cấp tỉnh và 60% tại cấp xã được xử lý trên môi trường mạng. Mốc 100% và 70% thuộc năm 2030.",mn:'"Cấp xã luôn thấp hơn cấp tỉnh 30 điểm”: 2025 là 90 — 60, 2030 là 100 -— 70.',t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030: đến năm 2025, I........ ] hồ sơ công việc tại cấp bộ, cấp tỉnh và [........ ] hồ sơ công việc tại cấp xã được xử lý trên môi trường mạng (trừ hồ sơ công việc thuộc phạm vi bí mật nhà nước).",o:["90%... 60%","100%... 70%","80%... 60%","90%... 70%"],c:0},{id:"vb13-39",s:"PHẦN 3 - CHÍNH PHỦ ĐIỆN TỬ, CHÍNH PHỦ SỐ; GIẢI PHÁP, KINH PHÍ VÀ TỔ CHỨC THỰC HIỆN",cc:'Mục (II (khoản 6) Chương trình ban hành kèm theo Điều Ì Nghị quyết số "ÔNQ-CP.',gt:"Việt Nam thuộc nhóm 70 nước dẫn đầu về Chính phủ điện tử (EGDI.) vào năm 2025 và nhóm 50 nước dẫn đầu vào năm 2030.",mn:'“Bảy mươi rồi năm mươi": thử hạng càng nhỏ càng tốt, 70 > 50.',t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, Việt Nam đặt mục tiêu thuộc nhóm các nước dẫn đầu về Chính phủ điện tử (EGDI). Số lượng nước trong nhóm dẫn đầu mà Việt Nam hướng tới ở mốc năm 2025 và năm 2030 lần lượt là bao nhiêu?",o:["Năm 2025 thuộc nhóm 50 nước dẫn đầu; năm 2030 thuộc nhóm 30 nước dẫn đầu","Năm 2025 thuộc nhóm 70 nước dẫn đầu; năm 2030 thuộc nhóm 50 nước dẫn đầu","Năm 2025 thuộc nhóm 100 nước dẫn đầu; năm 2030 thuộc nhóm 70 nước dẫn đầu","Năm 2025 thuộc nhóm 70 nước dẫn đầu; năm 2030 thuộc nhóm 30 nước dẫn đầu"],c:1},{id:"vb13-40",s:"PHẦN 3 - CHÍNH PHỦ ĐIỆN TỬ, CHÍNH PHỦ SỐ; GIẢI PHÁP, KINH PHÍ VÀ TỔ CHỨC THỰC HIỆN",cc:"Mục III (khoản 6) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 76/NQ-CP.",gt:"Đến năm 2025, 100% cơ sở dữ liệu quốc gia tạo nền tảng phát triển Chính phủ điện tử được hoàn thành và kết nối, chia sẻ trên toàn quốc. Mốc 80% là tỷ lệ hệ thống thông tin của bộ, ngành, địa phương được kết nối liên thông.",mn:'"Cơ sở dữ liệu quốc gia phải đủ 100": nền móng dữ liệu hoàn tất 100% mới chia sẻ được.',t:"m",q:"Trong quá trình xây dựng nền tảng Chính phủ điện tử, một bộ rà soát tiến độ các cơ sở dữ liệu quốc gia. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, đến năm 2025, tỷ lệ cơ AQ.ở XQg-C.PCCIHUC 021-2030 Trang >0 sở dữ liệu quốc gia tạo nền tảng phát triển Chính phủ điện tử được hoàn thành và kết nối, chia sẻ trên toàn quốc là bao nhiêu?",o:["80%, bằng tỷ lệ hệ thống thông tin của bộ, ngành, địa phương có liên quan đến người dân, doanh nghiệp được kết nối, liên thông qua Trục liên thông văn bản quốc gia","90%","70%","100%"],c:3},{id:"vb13-41",s:"PHẦN 3 - CHÍNH PHỦ ĐIỆN TỬ, CHÍNH PHỦ SỐ; GIẢI PHÁP, KINH PHÍ VÀ TỔ CHỨC THỰC HIỆN",cc:"Mục JI (khoản 6) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 7/0/NQ-C.P.",gt:'Hoạt động kiểm tra thực hiện qua môi trường số: 50% vào năm 2025 và 70% vào năm 2030. ® Miẹo nhớ: "Kiểm tra số: nam mươi rồi báy mươi”: 50... 70.',t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, về hoạt động kiểm tra của cơ quan quản lý nhà nước được thực hiện thông qua môi trường sốõ và hệ thống thông tin của cơ quan quản lý, tỷ lệ cần đặt ở mốc năm 2025 và năm 2030 lần lượt là bao nhiêu?",o:["Năm 2025 đạt 30%; năm 2030 đạt 50% hoạt động kiểm tra thực hiện qua môi trường số","Năm 2025 đạt 70%; năm 2030 đạt 90% hoạt động kiểm tra thực hiện qua môi trường số","Năm 2025 đạt 50%; năm 2030 đạt 70% hoạt động kiểm tra thực hiện qua môi trường số","Năm 2025 đạt 60%; năm 2030 đạt 80% hoạt động kiểm tra thực hiện qua môi trường số"],c:2},{id:"vb13-42",s:"PHẦN 3 - CHÍNH PHỦ ĐIỆN TỬ, CHÍNH PHỦ SỐ; GIẢI PHÁP, KINH PHÍ VÀ TỔ CHỨC THỰC HIỆN",cc:"Mục III (khoản 6) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 70 NQ-CP.",gt:"Đến năm 2030, 100% dịch vụ công trực tuyến mức độ 4 được cung cấp trên nhiều phương tiện truy cập khác nhau, bao gồm cả thiết bị di động.",mn:'"Mức độ 4 phải phù 100, kể cả điện thoại”: dịch vụ toàn trình thì mỗi thiết bị đều đúng được.',t:"m",q:"Cổng dịch vụ công của tỉnh Z đang được nâng cấp để người dân sử dụng được cả trên điện thoại di động. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, đến năm 2030, tỷ lệ dịch vụ công trực tuyến mức độ 4 được cung cấp trên nhiều phương tiện truy cập khác nhau, bao gồm cả thiết bị di động, là bao nhiêu?",o:["100%","90% dịch vụ công trực tuyến mức độ 4, ưu tiên cung cấp trên máy tỉnh và cổng thông tin điện tử của cơ quan, thiết bị di động triển khai theo nhu cầu từng địa phương","80%","70%"],c:0},{id:"vb13-43",s:"PHẦN 3 - CHÍNH PHỦ ĐIỆN TỬ, CHÍNH PHỦ SỐ; GIẢI PHÁP, KINH PHÍ VÀ TỔ CHỨC THỰC HIỆN",cc:"Mục III (khoản 6) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 76:NQ-CP.",gt:"Đến năm 2030, tối thiểu 80% người trưởng thành có tài khoản giao dịch tại ngân hàng.",mn:'"Tạm trên mười người lớn có tài khoản”: 80% người trưởng thành.',t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030: đến năm 2030, tối thiểu [......... ] người trưởng thành có tài khoản giao dịch tại ngân hàng, góp phần phổ cập thanh toán điện tử.",o:["70%","80%","90%","60%"],c:1},{id:"vb13-44",s:"PHẦN 3 - CHÍNH PHỦ ĐIỆN TỬ, CHÍNH PHỦ SỐ; GIẢI PHÁP, KINH PHÍ VÀ TỔ CHỨC THỰC HIỆN",cc:"Mục JÍ (khoản 6) Chương trình ban hành kèm theo Điều 1 NVabị quyết SỐ 76NQ-CD,",gt:"Nhiệm vụ: rà soát, xây dựng khung pháp lý: nghiên cứu, xây dựng Luật Chính phủ số và văn bản hướng dẫn; ban hành quy định về định danh và xác thực điện tử, hoàn thiện hành lang pháp lý để phổ cập danh tính số; xây dựng chính sách thuế, phí khuyến khích dụng dịch vụ số.",mn:'"Luật Chính phủ số + danh tính số": hai việc đi cùng nhau, thuế phí thì đề khuyến khích, không để cản trở.',t:"m",q:"Một cơ quan nghiên cứu đề xuất các nội dung hoàn thiện môi trường pháp lý cho Chính phủ số. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, nhiệm vụ hoàn thiện môi trường pháp lý được nêu như thế nào?",o:["Nghiên cứu, xây dựng Luật Chính quyền điện tử; ban hành quy định về định danh và xác thực điện tử để phổ cập danh tính số","Nghiên cứu, xây dựng Luật Chính phủ số; giữ nguyên hành lang pháp lý hiện hành về định danh và xác thực điện tử","Nghiên cứu, xây dựng Luật Chính phủ số; ban hành quy định thuế, phí nhằm hạn chế việc sử dụng dịch vụ số","Nghiên cứu, xây dựng Luật Chính phủ số; ban hành quy định về định danh và xác thực điện tử để phổ cập danh tính số"],c:3},{id:"vb13-45",s:"PHẦN 3 - CHÍNH PHỦ ĐIỆN TỬ, CHÍNH PHỦ SỐ; GIẢI PHÁP, KINH PHÍ VÀ TỔ CHỨC THỰC HIỆN",cc:"Mục J]Í (khoản 6) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 6 NQ-CP.",gt:"Các công nghệ được nêu: điện toán đám mây, dữ liệu lớn, di động, Internet vạn vật (IoT), trí tuệ nhân tạo (AI), chuỗi khối (Blockchain), mạng xã hội và các công nghệ số mới. Công nghệ in 3 chiêu không được liệt kê.",mn:'"Mây — dữ liệu — di động — vạn vật — AI — chuỗi khối — mạng xã hội”: đọc thành một dãy báy môn, không có "in".',t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, Chương trình nhân mạnh việc ứng dụng mạnh mẽ, hiệu quả các công nghệ số mới trong xây dựng, triển khai các ứng dụng, dịch vụ Chính phủ điện tử tại bộ, ngành, địa phương. Công nghệ nào sau đây KHÔNG được liệt kê trong số các công nghệ số mới đó?",o:["Điện toán đám mây","Dữ liệu lớn","Công nghệ in 3 chiều","Chuỗi khối (Blockchain)"],c:2},{id:"vb13-46",s:"PHẦN 3 - CHÍNH PHỦ ĐIỆN TỬ, CHÍNH PHỦ SỐ; GIẢI PHÁP, KINH PHÍ VÀ TỔ CHỨC THỰC HIỆN",cc:"Mục IV Chương 0ình ban hành kèm theo Điều 1 Nghị quyết số 7b. NQ- cP.",gt:'Phân giải pháp thực hiện nêu 6 giải pháp (chỉ đạo, điều hành; thông tin, tuyên truyền; nguồn lực tài chính, nhân lực; kỷ luật, kỷ cương; theo dõi, đánh giá, đo lường hài lòng; ứng dụng khoa học và công nghệ). VOQ "6b YXQe-C.P CCHUC “021-2ỤU)0 Trang —.i',mn:'"Sáu nội dung, sáu giải pháp”: hai danh sách cùng có 6 mức nhưng không trùng nội dung.',t:"m",q:"Chương trình có 6 nội dung cải cách cụ thể ở phần nội dung, mục tiêu, nhiệm vụ. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, phần giải pháp thực hiện Chương trình nêu bao nhiêu giải pháp?",o:["6 giải pháp","5 giải pháp","7 giải pháp","4 giải pháp"],c:0},{id:"vb13-47",s:"PHẦN 3 - CHÍNH PHỦ ĐIỆN TỬ, CHÍNH PHỦ SỐ; GIẢI PHÁP, KINH PHÍ VÀ TỔ CHỨC THỰC HIỆN",cc:"Mục IV (khoản 5) Chương trình bun hành kèm theo Điều 1 Nghị quyết số 7/oNäNQ-C.P.",gt:"Giải pháp: đổi mới phương pháp theo dõi, đánh giá định kỳ kết quả cải cách hành chính và thường xuyên đo lường sự hài lòng của người dân, tổ chức đối với sự phục vụ của cơ quan hành chính nhà nước các cấp.",mn:'"Đo băng sự hài lòng của dân”: người được phục vụ chấm điểm, không phải cơ quan tư chẩm.',t:"m",q:"Bà H là lãnh đạo một số, muốn đổi mới cách đánh giá kết quả thực hiện nhiệm vụ cải cách hành chính của các phòng, đơn vị trực thuộc. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, giải pháp về theo dõi, đánh giá và đo lường chất lượng phục vụ được nêu như thế nào?",o:["Duy trì phương pháp theo dõi, đánh giá hiện hành bằng báo cáo nội bộ; thường xuyên đo lường sự hài lòng của cán bộ, công chức","Đổi mới phương pháp theo dõi, đánh giá định kỳ kết quả thực hiện nhiệm vụ cải cách hành chính; thường xuyên đo lường sự hài lòng của người dân, tổ chức","Đổi mới phương pháp theo dõi, đánh giá định kỷ kết quả thực hiện nhiệm vụ cải cách hành chính; chỉ khảo sát sự hài lòng của người dân khi có khiếu nại","Đổi mới phương pháp theo dõi, đánh giá định kỳ kết quả thực hiện nhiệm vụ cải cách hành chính; thường xuyên đo lường sự hài lòng của các cơ quan cấp trên"],c:1},{id:"vb13-48",s:"PHẦN 3 - CHÍNH PHỦ ĐIỆN TỬ, CHÍNH PHỦ SỐ; GIẢI PHÁP, KINH PHÍ VÀ TỔ CHỨC THỰC HIỆN",cc:"Mục V Chương trình ban hành kèm theo Điều 1 Nghị quyết số 76/NQ-CP.",gt:"Kinh phí thực hiện Chương trình được bố trí từ ngân sách nhà nước theo phân cấp ngân sách nhà nước hiện hành; khuyến khích huy động theo quy định của pháp luật các nguồn kinh phí ngoài ngân sách trung ương.",mn:'"Ngân sách là chính, ngoài ngân sách là thêm”: tiền nhà nước lo trước, nguồn khác khuyến khích chứ không thay thế.',t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, kinh phí thực hiện Chương trình được bố trí chủ yếu từ nguồn nào, đồng thời Chương trình khuyến khích huy động thêm các nguồn kinh phí nào theo quy định của pháp luật?",o:["Nguồn tài trợ của các tổ chức quốc tế là chủ yếu, ngân sách nhà nước chỉ bố trí cho những nhiệm vụ do bộ, ngành ở Trung ương chủ trì, địa phương tự cần đổi theo khả năng từ nguồn thù của mình, không phân cấp theo quy định hiện hành","Nguồn thu phí, lễ phí của cơ quan hành chính","Nguồn đóng góp của người dân, doanh nghiệp","Ngân sách nhà nước theo phân cấp hiện hành; huy động thêm nguồn ngoài ngân sách trung ương"],c:3},{id:"vb13-49",s:"PHẦN 3 - CHÍNH PHỦ ĐIỆN TỬ, CHÍNH PHỦ SỐ; GIẢI PHÁP, KINH PHÍ VÀ TỔ CHỨC THỰC HIỆN",cc:"tiệm a khoản 3 Điều 2 Nghị quyết số 76/NQ-CP.",gt:"Bộ Nội vụ là cơ quan thường trực tổ chức triển khai thực hiện Chương trình. Văn phòng Chính phủ chủ trì cải cách thủ tục hành chính; Bộ Tư pháp theo dõi cải cách thể chế; Bộ Tài chính bố trí kinh phí.",mn:'"Thường trực là Nội vụ”: cải cách hành chính gắn với bộ máy và công vụ, nền Bộ Nội vụ giữ vai trò thường trực.',t:"m",q:"Ông K là công chức của một Ủy ban nhân dân tỉnh, cần gửi báo cáo định kỳ về tình hình thực hiện Chương trình để tổng hợp, báo cáo Chính phủ, Thủ tướng Chính phủ. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, cơ quan nào là cơ quan thường trực tổ chức triển khai thực hiện Chương trình?",o:["Văn phòng Chính phủ","Bộ Tư pháp","Bộ Nội vụ","Bộ Tài chính"],c:2},{id:"vb13-50",s:"PHẦN 3 - CHÍNH PHỦ ĐIỆN TỬ, CHÍNH PHỦ SỐ; GIẢI PHÁP, KINH PHÍ VÀ TỔ CHỨC THỰC HIỆN",cc:"Điểm a khoản 4 Điều 2 Nghị quyết số 70zNQ-C.P.",gt:"Bộ Tư pháp theo dõi, tổng hợp việc triển khai nội dung cải cách thể chế và chủ trì đổi mới, nâng cao chất lượng xây dựng, ban hành văn bản quy phạm pháp luật, tổ chức thi hành pháp luật.",mn:'"Thể chế thuộc Tư pháp”: làm luật, thi hành luật là việc của Bộ Tư pháp.',t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, các cơ quan được phân công chủ trì hoặc theo dõi từng nội dung khác nhau: Văn phòng Chính phủ chủ trì cải cách thủ tục hành chính, Bộ Nội vụ là cơ quan thường trực. Cơ quan nào có nhiệm vụ theo dõi, tổng hợp việc triển khai nội dung cải cách thể chế?",o:["Bộ Tư pháp","Bộ Nội vụ","Văn phòng Chính phủ","Bộ Tài chính"],c:0},{id:"vb13-51",s:"PHẦN 3 - CHÍNH PHỦ ĐIỆN TỬ, CHÍNH PHỦ SỐ; GIẢI PHÁP, KINH PHÍ VÀ TỔ CHỨC THỰC HIỆN",cc:"Điểm m khoản 3 Điều 2 Nghị quyết số 76:NQ-CP.",gt:"Bộ Nội vụ sơ kết vào năm 2025 và tổng kết, đánh giá vào năm 2029, trước khi kết thúc giai đoạn 2021 - 2030 một năm.",mn:'"Tổng kết trước một năm”: Chương trình kết thúc 2030 nhưng tổng kết ở 2029.',t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030: Bộ Nội vụ đến năm 2025 tiến hành sơ kết, đến năm [......... ] tiến hành tổng kết, đánh giá kết quả thực hiện Chương trình tổng thể.",o:["2030","2028","2027","2029"],c:3},{id:"vb13-52",s:"PHẦN 3 - CHÍNH PHỦ ĐIỆN TỬ, CHÍNH PHỦ SỐ; GIẢI PHÁP, KINH PHÍ VÀ TỔ CHỨC THỰC HIỆN",cc:"Điểm c khoản 1 Điều 2 Nghị quyết số 7O NQ-CP,",gt:"Báo cáo định kỳ hàng quý, 6 tháng, hàng năm hoặc đột xuất theo hướng dẫn của Bộ Nội vụ. Không có kỳ báo cáo hằng tháng.",mn:'"Quý -— nửa nam - nam - đột xuất": bổn kỳ, không có hằng tháng.',t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, các bộ, cơ quan ngang bộ, cơ quan thuộc Chính phủ, Ủy ban nhân dân tỉnh, thành phố trực thuộc Trung ương có trách nhiệm báo cáo Bộ Nội vụ tình hình thực hiện Chương trình đề tổng hợp, báo cáo Chính phủ, Thủ tướng Chính phủ theo kỳ hạn nào?",o:["Hằng tháng, hàng quý và hàng năm","Hàng quý, 6 tháng, hàng năm hoặc đột xuất","Chỉ 6 tháng và hàng năm","Chỉ hàng năm hoặc khi kết thúc giai đoạn"],c:1},{id:"vb13-53",s:"PHẦN 3 - CHÍNH PHỦ ĐIỆN TỬ, CHÍNH PHỦ SỐ; GIẢI PHÁP, KINH PHÍ VÀ TỔ CHỨC THỰC HIỆN",cc:"Khoản 3 và khoản #8 Điều ở Nghị quyết số 7U NQ-CP.",gt:"Bộ Nội vụ chủ trì phương pháp xác định Chỉ số cải cách hành chính, phương pháp đo lường sự hài lòng của người dân và hướng dẫn kế hoạch cải cách hành chính. Nội dung phát triển Chính phủ điện tử, Chính phủ số do Bộ Thông tin và Truyền thông chủ trì.",mn:'"Chính phủ số không phải của Nội vụ”: Nội vụ lo bộ máy - công vụ - chỉ số, phân số hóa do cơ quan thông tin truyền thông chủ trì. VOQ "6b YXQe-C.P CCHUC “021-2ỤU)0 Trang —6',t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, Bộ Nội vụ được giao nhiều nhiệm vụ trong tổ chức thực hiện Chương trình, như chủ trì cải cách tổ chức bộ máy, cải cách chế độ công vụ và cải cách chính sách tiền lương. Nhiệm vụ nào sau đây KHÔNG thuộc Bộ Nội vụ?",o:["Chủ trì xây dựng phương pháp xác định Chỉ số cải cách hành chính hằng năm","Chủ trì xây dựng phương pháp đo lường sự hài lòng của người dân","Chủ trì triển khai nội dung phát triển Chính phủ điện tử, Chính phủ số","Hướng dẫn xây dựng kế hoạch cải cách hành chính hàng năm"],c:2},{id:"vb13-54",s:"PHẦN 3 - CHÍNH PHỦ ĐIỆN TỬ, CHÍNH PHỦ SỐ; GIẢI PHÁP, KINH PHÍ VÀ TỔ CHỨC THỰC HIỆN",cc:"Mục II (điểm a khoản 6) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 76/NQ-CP.",gt:"Cấp xã: 60% vào năm 2025 và 70% vào năm 2030. Mức 90% (2025) và 100% (2030) là của cấp bộ, cấp tỉnh.",mn:'"Xã súu mươi rồi bảy mươi”: 60... 70, còn bộ, tính 90 -, 100.',t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, hồ sơ công việc tại cấp xã (trừ hồ sơ thuộc phạm vi bí mật nhà nước) được xử lý trên môi trường mạng với tỷ lệ tối thiểu ở các mốc năm 2025 và năm 2030 được xác định như thế nào?",o:["60% năm 2025 và 70% năm 2030","90% năm 2025 và 100% năm 2030","80% năm 2025 và 90% năm 2030","60% năm 2025 và 100% năm 2030"],c:0},{id:"vb13-55",s:"PHẦN 3 - CHÍNH PHỦ ĐIỆN TỬ, CHÍNH PHỦ SỐ; GIẢI PHÁP, KINH PHÍ VÀ TỔ CHỨC THỰC HIỆN",cc:"Mục I và I1 Chương trình ban hành kèm theo Điều 1 Nghị quyết số 76/NQ-CP.",gt:"Chương trình lấy người dân, doanh nghiệp làm trung tâm và hướng tới nền hành chính dân chủ, chuyên nghiệp, hiện đại, tinh gọn, hiệu lực, hiệu quả, có năng lực kiến tạo phát triển, liêm chính, phục vụ nhân dân.",mn:'"Dân ở giữa, phục vụ là đích”: mọi cải cách quy về phục vụ nhân dân. Phân bổ sung cho nội dung 1 (cải cách thể chế) và nội dung 2 (cải cách thủ tục hành chính): tăng cường dạng điền khuyết so liệu, phân biệt các mốc đến năm 2025 và năm 2030, tình huống vận dụng thực tế.',t:"m",q:"Một tài liệu tuyên truyền giới thiệu khái quát quan điểm và mục tiêu chung của Chương trình. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, phát biểu nào sau đây phản ánh dựng quan điểm và mục tiêu chung của Chương trình?",o:["Lấy cơ quan hành chính làm trung tâm; ưu tiên hoàn thiện bộ máy nội bộ, mở rộng đầu mối tổ chức trung gian, sau đó mới đánh giá mức độ hài lòng của người dân và doanh nghiệp đối với dịch vụ công do các cấp cung cấp","Lấy người dân, doanh nghiệp làm trung tâm; hướng tới nền hành chính phục vụ nhân dân","Lấy ngân sách nhà nước làm trung tâm; hướng tới tăng thu","Lấy chuyển đổi số làm trung tâm; hướng tới giam cán bộ"],c:1},{id:"vb13-56",s:"PHẦN 4 - BỔ SUNG: CẢI CÁCH THỂ CHẾ VÀ CẢI CÁCH THỦ TỤC HÀNH CHÍNH (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Mục III (khoản 2) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 706/NQ-CP.",gt:"Đến năm 2030, tối thiểu 90% thủ tục hành chính có đủ điều kiện được cung cấp trực tuyến mức độ 3 và 4 và hoàn thành tích hợp trên Cổng Dịch vụ công quốc gia. Mốc 80% là của năm 2025.",mn:'"2025 là 80, 2030 là 90": thủ tục trực tuyến tăng thêm 10 điểm sau 5 năm.',t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030: đến năm 2030, tối thiểu |......... ] thủ tục hành chính của các bộ, ngành, địa phương có đủ điều kiện được cung cấp trực tuyến mức độ 3 và 4, đồng thời hoàn thành việc tích hợp, cung cấp trên Cổng Dịch vụ công quốc gia.",o:["80%","100%","70%","90%"],c:3},{id:"vb13-57",s:"PHẦN 4 - BỔ SUNG: CẢI CÁCH THỂ CHẾ VÀ CẢI CÁCH THỦ TỤC HÀNH CHÍNH (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Mục II (khoản 2) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 76NQ-CP.",gt:"Tỷ lệ hồ sơ giải quyết trực tuyến mức độ 3 và 4 trên tổng số hồ sơ đạt tối thiểu 50%, (2025) và 80% (2030).",mn:'“Hồ sơ trực tuyến: 50 lên 80": tăng 30 điểm trong 5 năm.',t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, đến năm 2030, trong tổng số hồ sơ giải quyết thủ tục hành chính, tỷ lệ hồ sơ giải quyết trực tuyến mức độ 3 và 4 phải đạt tối thiểu bao nhiêu, cao hơn mốc 50% đã đạt ra cho năm 2025?",o:["Đạt tối thiểu 70% tổng số hồ sơ giải quyết thủ tục hành chính","Đạt tối thiểu 90% tổng số hồ sơ giải quyết thủ tục hành chính","Đạt tối thiểu 80% tổng số hồ sơ giải quyết thủ tục hành chính","Đạt tối thiểu 60% tổng số hồ sơ giải quyết thủ tục hành chính"],c:2},{id:"vb13-58",s:"PHẦN 4 - BỔ SUNG: CẢI CÁCH THỂ CHẾ VÀ CẢI CÁCH THỦ TỤC HÀNH CHÍNH (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Mục II (khoản 2) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 76NQ-CP.",gt:"Lĩnh vực đất đai, xây dựng, đầu tư đạt tối thiểu 85% (2025) và 90% (2030), không phải 95%. Mức hài lòng chung là 90% (2025) và 95% (2030).",mn:'"Lĩnh vực nông luôn thấp hơn chung 5 điểm”: chung 90/95, đất đai - xây dựng — đầu tư 85/90.',t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, Chương trình đặt các mục tiêu về mức độ hài lòng của người dân, doanh nghiệp đối với việc giải quyết thủ tục hành chính ử hai mốc 2025 và 2030. Nhận định nào sau đây SAI?",o:["Đến năm 2030, mức độ hài lòng ở lĩnh vực đất đai, xây dựng, đầu tư đạt tối thiểu 95%","Đến năm 2025, mức độ hài lòng chung đạt tối thiểu 90%","Đến năm 2030, mức độ hài lòng chung đạt tối thiểu 95%","Đến năm 2025, mức độ hài lòng ở lĩnh vực đất đai, xây dựng, đầu tư đạt tối thiểu 85%"],c:0},{id:"vb13-59",s:"PHẦN 4 - BỔ SUNG: CẢI CÁCH THỂ CHẾ VÀ CẢI CÁCH THỦ TỤC HÀNH CHÍNH (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Mục HH (khoản 2) Chương trình bụn hành kèm theo Điều 1] NXobi quyết số 6. NO-CP.",gt:"Đến năm 2025, ít nhất 80% thủ tục hành chính được cung cấp trực tuyến mức độ 3, 4 được tích hợp, cung cấp trên Cổng Dịch vụ công quốc gia; mộc 50% là tỷ lệ hồ sơ trực tuyến trên tổng số hồ sơ.",mn:'"Tích hợp tạm phần mười”: 80% thủ tục trực tuyến được đưa lên Công quốc gia.',t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030: đến năm 2025, ít nhất I........ ] thủ tục hành chính được cung cấp trực tuyến mức độ 3, 4 được tích hợp, cung cấp trên Cổng Dịch vụ công quốc gia; tỷ lệ hồ sơ giải quyết trực tuyến mức độ 3 và 4 đạt tối thiểu 50% tổng số hồ sơ.",o:["90%","100%","50%","80%"],c:3},{id:"vb13-60",s:"PHẦN 4 - BỔ SUNG: CẢI CÁCH THỂ CHẾ VÀ CẢI CÁCH THỦ TỤC HÀNH CHÍNH (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Mục II (khoản 2) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 76NQ-CP.",gt:"Nhiệm vụ: tăng cường kết nối, chia sẻ thông tin giữa các cơ quan quản lý nhà nước; ứng dụng tối đa công nghệ thông tin để đơn giản hóa, hiện đại hóa thủ tục kiểm tra; áp dụng phương pháp quản lý rủi ro phù hợp thông lệ quốc tế.",mn:'"Kết nối - công nghệ - rủi ro”: kiểm tra thông minh, chỉ soi kỹ lô hàng có rủi ro.',t:"m",q:"Công ty X thường xuyên nhập khẩu hàng hóa và phải làm thủ tục kiểm tra chuyên ngành tại nhiều cơ quan quản lý khác nhau. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, nhiệm vụ cải cách hoạt động kiểm tra chuyên ngành đối với hàng hóa xuất khẩu, nhập khẩu theo hướng nào?",o:["Giao toàn bộ việc kiểm tra cho một cơ quan duy nhất, duy trì kiểm tra thủ công trên từng lô hàng của từng doanh nghiệp để bảo đảm chặt chẽ, thống nhất trong phạm vi cả nước và tại tất cả cửa khẩu AQ.ở XQg-C.PCCIHUC 021-2030 rang —s","Tăng cường kết nối, chia sẻ thông tin; ứng dụng công nghệ thông tin; áp dụng phương pháp quản lý rủi ro","Bổ sung các lần kiểm tra theo từng cơ quan","Tăng kiểm tra trực tiếp tại doanh nghiệp"],c:1},{id:"vb13-61",s:"PHẦN 4 - BỔ SUNG: CẢI CÁCH THỂ CHẾ VÀ CẢI CÁCH THỦ TỤC HÀNH CHÍNH (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Mục IIÏ (khoản 2) Chương trình ban hành k;em theo Điều 1 Nghị quyết số 76NQ-CP.",gt:"Mục tiêu: đến năm 2025 tối thiểu 80% thủ tục có nghĩa vụ tài chính thanh toán trực tuyến (giao dịch từ 30%); đến năm 2030 là 100% (giao dịch từ 50%).",mn:'"Thủ tục tạm — mười, giao dịch ba - nam”: thủ tục 80 — 100, giao dịch 30 ¬ 50.',t:"m",q:"Một số ở địa phương muốn giảm phiền hà cho người dân khi nộp hồ sơ thủ tục hành chính có nghĩa vụ tài chính. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, giải pháp phù hợp với mục tiêu thanh toán trực tuyến của Chương trình là gì?",o:["Triển khai thanh toán trực tuyến: năm 2025 tối thiểu 90% thủ tục (giao dịch từ 30%), năm 2030 đạt 100% (giao dịch từ 50%)","Triển khai thanh toán trực tuyến: năm 2025 tối thiểu 80% thủ tục (giao dịch từ 50%), năm 2030 đạt 100% (giao dịch từ 30%)","Triển khai thanh toán trực tuyến: năm 2025 tối thiểu 80% thủ tục (giao dịch từ 30%), năm 2030 đạt 100% (giao dịch từ 50%)","Triển khai thanh toán trực tuyến: năm 2025 tối thiểu 80% thủ tục (giao dịch từ 30%), năm 2030 đạt 90% (giao dịch từ 50%)"],c:2},{id:"vb13-62",s:"PHẦN 4 - BỔ SUNG: CẢI CÁCH THỂ CHẾ VÀ CẢI CÁCH THỦ TỤC HÀNH CHÍNH (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Mục 1II (khoản 2) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 7/uNäNQ-C.P.",gt:"Các lĩnh vực trọng tâm: đất đai, xây dựng, đầu tư, bảo hiểm, thuế, hải quan, công an và các lĩnh vực khác có số lượng, tần suất giao dịch lớn. Giáo dục và đào tạo không được nêu riêng.",mn:'"Đất - xây - dâu - báo - thuế - hải - công an”: bấy chữ đầu của các lĩnh vực giao dịch nhiều.',t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, nhiệm vụ kiểm soát việc ban hành các quy định thủ tục hành chính liên quan đến người dân, doanh nghiệp nêu rõ một số lĩnh vực trọng tâm cần bảo đảm thủ tục đơn giản, dễ hiểu, dễ thực hiện. Lĩnh vực nào sau đây KHÔNG được nêu là lĩnh vực trọng tâm?",o:["Giáo dục và đào tạo","Đất đai","Hải quan","Bảo hiểm"],c:0},{id:"vb13-63",s:"PHẦN 4 - BỔ SUNG: CẢI CÁCH THỂ CHẾ VÀ CẢI CÁCH THỦ TỤC HÀNH CHÍNH (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Mục JII (khoản 1) Chương trình ban hònh kèm theo Điều 1 Nghị quyết số 70, NQ-C.P.",gt:"Đến năm 2030: hoàn thiện toàn diện, đồng bộ và vận hành có hiệu quả thể chế của nền hành chính hiện đại, thể chế phát triển kinh tế thị trường định hướng xã hội chủ nghĩa. Ba phương án còn lại là các mục tiêu đến năm 2025.",mn:'"2025 cơ bản, 2030 toàn diện”: từ cơ bản hoàn thiện tiên lên hoàn thiện toàn diện, đồng bộ.',t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, mục tiêu cải cách thể chế đến năm 2030 được xác định khác với mục tiêu đến năm 2025. Phương án nào sau đây nêu đúng mục tiêu cải cách thể chế đến năm 2030?",o:["Cơ bản hoàn thiện hệ thống thể chế của nền hành chính nhà nước, trọng tâm là thể chế về tổ chức bộ máy và quản lý cán bộ, công chức, viên chức","Tiếp tục hoàn thiện thể chế phát triển nền kinh tế thị trường định hướng xã hội chủ nghĩa, giải quyết tốt hơn mối quan hệ giữa Nhà nước và thị trường","Hoàn thiện toàn diện, đồng bộ và vận hành có hiệu quả thể chế của nền hành chính hiện đại, thể chế phát triển kinh tế thị trường định hướng xã hội chủ nghĩa","Hoàn thiện thể chế và các khung khổ pháp lý để thúc đẩy chuyển đổi số, phục vụ xây dựng Chính phủ số, nền kinh tế số và xã hội số"],c:2},{id:"vb13-64",s:"PHẦN 4 - BỔ SUNG: CẢI CÁCH THỂ CHẾ VÀ CẢI CÁCH THỦ TỤC HÀNH CHÍNH (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Mộc JlÍ (khoản 1) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 7U NQ-CP.",gt:"Nhiệm vụ: sửa đổi, bổ sung, hoàn thiện pháp luật về đất đai, tài nguyên để huy động, phân bố, sử dụng hiệu quả, khác phục tranh chấp, khiếu kiện, tham nhũng, lãng phí; công khai, minh bạch việc quản lý, sử dụng đất công; tăng cường giám sát đất giao cho công động và doanh nghiệp nhà nước.",mn:'"Đất công phải minh bạch”: đất của chung thì công khai d6 dân giám sát.',t:"m",q:"Một bộ nghiên cứu đề xuất sửa đổi pháp luật đất đai, tài nguyên đề khác phục tranh chấp, khiếu kiện, tham nhũng, lãng phí. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, nhiệm vụ hoàn thiện thể chế kinh tế thị trường liên quan đến đất đai, tài nguyên được xác định như thế nào?",o:["Giữ nguyên pháp luật đất đai, tài nguyên hiện hành; tăng cường giao đất công cho doanh nghiệp để huy động nguồn lực, thu hẹp phạm vi công khai thông tin quản lý đất đai nhằm giảm áp lực khiếu kiện","Hoàn thiện pháp luật đất đai; hạn chế giám sát đất giao cho cộng đồng","Hoàn thiện pháp luật đất đai; chí công khai việc sử dụng đất tư","Hoàn thiện pháp luật đất đai, tài nguyên; công khai, minh bạch việc quản lý, sử dụng đất công"],c:3},{id:"vb13-65",s:"PHẦN 4 - BỔ SUNG: CẢI CÁCH THỂ CHẾ VÀ CẢI CÁCH THỦ TỤC HÀNH CHÍNH (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Mục HÍ (khoản 2) Chương trình ban hành kèm theo liều Í Nehị quyết số 76NQ-CP,",gt:"Mốc văn bản: đang có hiệu lực thi hành tính đến hết ngày 31 tháng 5 năm 2020. Ngày 15/7/2021 là ngày ban hành Nghị quyết.",mn:'"Mốc 31/5/2020": chốt danh sách quy định kinh doanh vào cuối tháng Năm năm 2020.',t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030: các văn bản đang có hiệu lực thi hành được làm mốc để tính cắt giảm, đơn giản hóa quy định liên quan đến hoạt động kinh doanh là các văn bản tính đến hết ngày [........ I",o:["31 tháng 12 năm 2020","31 tháng 5 năm 2020","15 tháng 7 năm 2021","30 tháng 6 năm 2020"],c:1},{id:"vb13-66",s:"PHẦN 4 - BỔ SUNG: CẢI CÁCH THỂ CHẾ VÀ CẢI CÁCH THỦ TỤC HÀNH CHÍNH (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:'Mục HlÍ (khoản 2) C hương trình ban hành kèm theo Điều Í Nghị quyết số 7e. NÓ-CP. VOQ "6b YXQe-C.P CCHUC “021-2ỤU)0 Trang.š2',gt:"Cơ chế một cửa, một cửa liên thông được đổi mới theo hướng nâng cao chất lượng phục vụ, không theo địa giới hành chính, tăng cường ứng dụng công nghệ thông tin, giảm thời gian đi lại, chi phí xã hội.",mn:'"Một cửa không giới hạn địa bàn”: nộp ở đâu củng được, như rút tiên ATM ở bất kỳ máy nào.',t:"m",q:"Bà C ở một tỉnh cần nộp hồ sơ thủ tục hành chính nhưng đang công tác xa nơi cư trú. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, việc đối mới thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính được thực hiện theo hướng nào?",o:["Nâng cao chất lượng phục vụ, không theo địa giới hành chính, tăng cường ứng dụng công nghệ thông tin","Nâng cao chất lượng phục vụ, giải quyết theo địa giới hành chính nơi cư trú, tăng cường ứng dụng công nghệ thông tin","Nâng cao chất lượng phục vụ, không theo địa giới hành chính, hạn chế ứng dụng công nghệ thông tin ở cấp cơ sở","Duy trì cách làm hiện hành, không theo địa giới hành chính, tăng số điểm tiếp nhận hồ sơ của từng cơ quan"],c:0},{id:"vb13-67",s:"PHẦN 4 - BỔ SUNG: CẢI CÁCH THỂ CHẾ VÀ CẢI CÁCH THỦ TỤC HÀNH CHÍNH (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Mục IIÏ (khoản 2) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 76/NQ-CP.",gt:"Nhiệm vụ: tích hợp, cắt giảm mạnh các mẫu đơn, tờ khai và giấy tờ không cần thiết hoặc có nội dung thông tin trùng lặp trên cơ sở ứng dụng công nghệ số và các cơ sở dữ liệu sẵn có.",mn:'"Dữ liệu có sản thì không hỏi lại”: cơ quan dùng dữ liệu đã có thay vị bắt dân khai lại.',t:"m",q:"Một bộ rà soát thấy nhiều mẫu đơn, tờ khai trong giải quyết thủ tục hành chính có nội dung thông tin trùng lặp, gây khó cho người dân. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, hướng xử lý phù hợp là gì?",o:["Tích hợp các mẫu đơn, tờ khai những yêu cầu người dân khai lại đầy đủ thông tin trong mỗi lần nộp để cơ quan tiến đối chiếu","Giữ nguyên các mẫu đơn, tờ khai và giấy tờ hiện hành, chỉ cắt giảm khi người dân có kiến nghị bằng văn bản","Cắt giảm mạnh các mẫu đơn, tờ khai nhưng bổ sung thêm giấy tờ chứng minh để cơ quan kiểm tra thông tin","Tích hợp, cắt giảm mạnh các mẫu đơn, tờ khai và giấy tờ không cần thiết hoặc trùng lặp thông tin trên cơ sở ứng dụng công nghệ số và cơ sở dữ liệu sẵn có"],c:3},{id:"vb13-68",s:"PHẦN 4 - BỔ SUNG: CẢI CÁCH THỂ CHẾ VÀ CẢI CÁCH THỦ TỤC HÀNH CHÍNH (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Mục III (khoản 1) Chương trình ban hành kèm theo Điều 1 Vghi quyết số 76:NQ-CP.",gt:"Nhiệm vụ: tăng cường năng lực phản ứng chính sách, kịp thời xử lý các vấn đề mới phát sinh trong tổ chức thi hành pháp luật, đặc biệt gắn kết với quá trình xây dựng, hoàn thiện pháp luật.",mn:'"Thi hành phát hiện gì, sửa luật ngay”: thi hành và xây dựng luật luôn nối với nhau.',t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, nhiệm vụ đối mới, nâng cao chất lượng, hiệu quả thực thi pháp luật có nội dung tăng cường năng lực phản ứng chính sách. Nội dung này được xác định như thế nào?",o:["Kịp thời xử lý các vấn đề mới phát sinh trong tổ chức thi hành pháp luật, tách riêng khỏi quá trình xây dựng, hoàn thiện pháp luật","Kịp thời xử lý các vấn đề mới phát sinh trong tổ chức thi hành pháp luật, gắn kết với quá trình xây dựng, hoàn thiện pháp luật","Định kỳ xem xét các vấn đề mới phát sinh trong tổ chức thi hành pháp luật, gắn kết với quá trình xây dựng, hoàn thiện pháp luật","Kịp thời xử lý các vấn đề mới phát sinh trong tổ chức thi hành pháp luật, giao riêng cho cơ quan địa phương thực hiện"],c:1},{id:"vb13-69",s:"PHẦN 4 - BỔ SUNG: CẢI CÁCH THỂ CHẾ VÀ CẢI CÁCH THỦ TỤC HÀNH CHÍNH (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Mục III (khoản 2) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 70/NQ-CP.",gt:"Đến năm 2030, tỷ lệ giao dịch thanh toán trực tuyến đạt từ 50% trở lên (móc 2025 là 30%).",mn:'"Giao dịch trực tuyến: 30 rồi 50": 2025 là 30%, 2030 là 50%.',t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030: đến năm 2030, 100% thủ tục hành chính có yêu cầu nghĩa vụ tài chính được triển khai thanh toán trực tuyến, trong số đó tỷ lệ giao dịch thanh toán trực tuyến đạt từ [......... ] trở lên.",o:["30%","70%","50%.","80%"],c:2},{id:"vb13-70",s:"PHẦN 4 - BỔ SUNG: CẢI CÁCH THỂ CHẾ VÀ CẢI CÁCH THỦ TỤC HÀNH CHÍNH (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Mục III (điểm b khoản 2) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 76/NQ-CP.",gt:"Chương trình nêu rõ việc tháo gỡ vướng mắc về cơ chế, chính sách, thủ tục hành chính thông qua đối thoại, lấy ý kiến người dân, doanh nghiệp và phát huy vai trò của Hội đồng tư vấn cải cách thủ tục hành chính của Thủ tướng Chính phủ. Cơ quan thường trực cải cách hành chính thuộc nhóm giải pháp chỉ đạo, điều hành.",mn:'Nhớ "vướng thủ tục thì hội Hội đồng tư vấn của Thủ tướng”: giống việc cần có văn chuyên môn thi gặp hội đồng tư vấn.',t:"m",q:"Trong nội dung cải cách thủ tục hành chính, để thảo gỡ các vướng mắc về cơ chế, chính sách, thủ tục hành chính, Chương trình yêu cầu đẩy mạnh đối thoại, lấy ý kiến người dân, doanh nghiệp và phát huy vai trò, hiệu quả hoạt động của tổ chức nào? Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, tổ chức đó là:",o:["Cổng Thông tin điện tử Chính phủ và các cơ quan báo chí","Hội đồng tư vấn cải cách thủ tục hành chính của Thủ tướng Chính phủ","Mặt trận Tổ quốc Việt Nam và các tổ chức chính trị - xã hội các cấp","Cơ quan thường trực cải cách hành chính của Chính phủ, được tăng cường vai trò, trách nhiệm, năng lực để phối hợp thống nhất các cơ quan chủ trì triển khai các nội dung cải cách hành chính trong Chương trình"],c:1},{id:"vb13-71",s:"PHẦN 4 - BỔ SUNG: CẢI CÁCH THỂ CHẾ VÀ CẢI CÁCH THỦ TỤC HÀNH CHÍNH (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Mục HI (điểm a khoản 2) Chương trình ban hành kèm theo Điều Ì Nghị quyết số 7b NO-CP.",gt:"Mốc năm 2025 là tối thiểu 80% thủ tục hành chính có nghĩa vụ tài chính được thanh toán trực tuyến; mốc 109% chi đặt ra cho năm 2030. Các phương án còn lại đúng với nội dung Chương trình.",mn:'Nhớ "80% năm 2025, 100% năm 2030”: như học bài, đến kỷ giữa mới 8056, cuối ký mới đủ 100%,',t:"m",q:"Nội dung cải cách thủ tục hành chính của Chương trình đặt ra nhiều chỉ tiêu cho các mốc năm 2025 và năm 2030, liên quan đến luân chuyển hồ sơ điện tử, thanh toán trực tuyến, mức độ hài lòng và môi trường kinh doanh. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, nhận định nào dưới đây là KHÔNG đúng?",o:["Đến năm 2025, mức độ hài lòng của người dân, doanh nghiệp về giải quyết thủ tục hành chính đạt tối thiểu 90%","Đến năm 2025, tối thiểu 80% hồ sơ giải quyết thủ tục hành chính được luân chuyển trong nội bộ giữa các cơ quan bằng phương thức điện tử","Đến năm 2025, 100% thủ tục hành chính có yêu cầu nghĩa vụ tài chính được triển khai thanh toán trực tuyến","Đến năm 2030, môi trường kinh doanh của Việt Nam được xếp vào nhóm 30 quốc gia hàng đầu"],c:2},{id:"vb13-72",s:"PHẦN 4 - BỔ SUNG: CẢI CÁCH THỂ CHẾ VÀ CẢI CÁCH THỦ TỤC HÀNH CHÍNH (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Mục II (điểm b khoản 1) Chương trình ban hành kèm theo Điều 1 Nghị quyết số ZO, NQ-C.BP.",gt:"Để thúc đẩy chuyển đổi số, kinh tế số và các mô hình kinh doanh mới, Chương trình đề ra xây dựng, hoàn thiện khung khổ pháp lý và thủ nghiệm cơ chế, chính sách đặc thù. Các phương án khác là nhiệm vụ cải cách thể chế nhưng không nhằm mục đích này. AQ.ở XQg-C.PCCIHUC 021-2030 Trang ca",mn:'Nhớ "khung pháp lý + thử nghiệm cho kinh tế số": muốn chạy xe mới phải có dưỡng và có bài chạy thư.',t:"m",q:"Một trong các nhiệm vụ cải cách thể chế của Chương trình nhằm thúc đẩy quá trình chuyển đổi số, kinh tế số, sản xuất thông minh, các mô hình sản xuất kinh doanh mới, kinh tế chia sẻ, thương mại điện tử và khởi nghiệp sáng tạo. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, nhiệm vụ đó là gì?",o:["Hoàn thiện khung khổ pháp lý, thử nghiệm cơ chế, chính sách đặc thù","Rà soát, kiểm tra văn bản quy phạm pháp luật chồng chéo, mâu thuẫn","Hoàn thiện pháp luật về đất đai, tài nguyên","Hoàn thiện thể chế về thu hút đầu tư, huy động, phân bố và sử dụng có hiệu quả các nguồn lực và thể chế về phân phối kết quả làm ra để giải phóng sức sản xuất, tạo động lực và nguồn lực cho tăng trưởng, phát triển"],c:0},{id:"vb13-73",s:"PHẦN 4 - BỔ SUNG: CẢI CÁCH THỂ CHẾ VÀ CẢI CÁCH THỦ TỤC HÀNH CHÍNH (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Mục J! (Cdiêm ù khoản 2) Chương trình ban hành kèm theo Điều 1 Nghị quyết SỐ Z5 NQ-C.P.",gt:"Mục tiêu đến năm 2925 là hoàn thành đổi mới cơ chế một cửa, một cửa liên thông theo hướng không theo địa giới hành chính, tăng cường ứng dụng công nghệ thông tin, giảm thời gian đi lại, chi phí xã hội. Phân cấp là nhiệm vụ khác, mốc 2030 không phải mốc của nội dung này.",mn:'Nhớ "một cửa không theo địa giới": làm thủ tục ở đâu cũng được, như rút tiền ở mọi cây ATM,',t:"m",q:"Ông A là chủ một doanh nghiệp, khi làm thủ tục hành chính phải đi lại nhiều lần giữa các cơ quan và thường bị yêu cầu thực hiện đúng tại địa bàn nơi đặt trụ sở. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, để giảm thời gian đi lại và chỉ phí xã hội, mục tiêu đến năm 2025 về cơ chế một cửa, một cửa liên thông là gì?",o:["Hoàn thành đổi mới cơ chế một cửa, một cửa liên thông theo hướng không theo địa giới hành chính, tăng cường ứng dụng công nghệ thông tin, đến năm 2030","Hoàn thành đổi mới cơ chế một cửa, một cửa liên thông theo hướng gắn với địa giới hành chính, tăng cường ứng dụng công nghệ thông tin, giảm thời gian đi lại","Hoàn thành đổi mới cơ chế một cửa, một cửa liên thông theo hướng không theo địa giới hành chính, tăng cường ứng dụng công nghệ thông tin, giảm thời gian đi lại","Đẩy mạnh phân cấp giải quyết thủ tục hành chính theo hướng cấp nào sát cơ sở, sát nhân dân nhất thì giao cho cấp đó giải quyết, giảm thời gian đi lại"],c:2},{id:"vb13-74",s:"PHẦN 4 - BỔ SUNG: CẢI CÁCH THỂ CHẾ VÀ CẢI CÁCH THỦ TỤC HÀNH CHÍNH (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Mục JIÍ (điểm ø khoản 2) Chương trình ban hành kèm theo Điều 1 Nghị quyết số Z0 NGQ-(.P.",gt:"Giai đoạn 2022 - 2025, mỗi năm tăng tối thiểu 20% đổi với mỗi cấp cho đến khi đạt tỷ lệ 100%. Các giá trị 3096, 15%, 80%, 90% không phải mức tăng hàng năm hoặc tỷ lệ dích. AQ.ở XQg-C.PCCIHUC 021-2030 Trang.số",mn:'Nhớ "mỗi năm +20% cho đến 100%": như đố đẩy bình nước, mỗi lần thêm một phần năm là đủ dây.',t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030: Năm 2021, số hóa kết quả giải quyết thủ tục hành chính đang còn hiệu lực và có giá trị sử dụng đạt tỷ lệ tối thiểu tương ứng ở từng cấp là 40%, 30%, 20%, 15%; giai đoạn 2022 - 2025, mỗi năm tăng tối........] đối với mỗi cấp hành chính cho đến khi đạt tỷ lệ [......... ] để bảo đảm kết nối, chia sẻ dữ liệu trên môi trường điện tử.",o:["20%... 80%","15%... 90%","30%... 100%","20%.... 100%"],c:3},{id:"vb13-75",s:"PHẦN 4 - BỔ SUNG: CẢI CÁCH THỂ CHẾ VÀ CẢI CÁCH THỦ TỤC HÀNH CHÍNH (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Mục!II (điểm a khoản 2) Chương trình ban hành kèm theo Điều 1 Nghị quyết SỐ 76/NQ-CDP.",gt:'Mục tiêu nêu cải cách thủ tục hành chính liên quan đến người dân, doanh nghiệp và thủ tục hành chính nội bộ giữa các cơ quan hành chính nhà nước. Các phương án khác thay đổi phạm vi (trong từng cơ quan, quốc phòng - an ninh, tố tụng). $® Miẹo nhớ: Nhớ "dân - doanh nghiệp + nội bộ giữa các cơ quan": thủ tục có hại chiều, đối ngoại với dân và đối nội giữa các cơ quan. Phũn bổ sung cho nội dung 3, 4. 5: tăng cường dạng điền khuyết số liệu, phân biệt các móc đến năm 2025 và năm 2030, các nhiệm vụ trọng tâm và tình huống vận dụng.',t:"m",q:"Cải cách thủ tục hành chính là một trong sáu nội dung của Chương trình. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, mục tiêu của nội dung này hướng tới việc cải cách quyết liệt, đồng bộ, hiệu quả quy định về những loại thủ tục hành chính nào?",o:["Thủ tục hành chính liên quan đến người dân, doanh nghiệp và thủ tục hành chính nội bộ giữa các cơ quan hành chính nhà nước","Thủ tục hành chính nội bộ giữa các cơ quan hành chính nhà nước và thủ tục tố tụng trong hoạt động tư pháp","Thủ tục hành chính liên quan đến người dân, doanh nghiệp và thủ tục hành chính trong lĩnh vực quốc phòng, an ninh nhân dân","Thủ tục hành chính liên quan đến người dân, doanh nghiệp và thủ tục hành chính nội bộ trong từng cơ quan hành chính nhà nước"],c:0},{id:"vb13-76",s:"5 - BỔ SUNG: CẢI CÁCH TỔ CHỨC BỘ MÁY, CHẾ ĐỘ CÔNG VỤ VÀ TÀI CHÍNH CÔNG (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Mục III (điểm a khoản 4) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 76NQ-C.P.",gt:'Mục tiêu năm 2030 nêu rõ trên 30% số lãnh đạo, quản lý cấp phòng trực thuộc sở, ngành và tương đương. Mức 25% - 35% là của cấp sở, ngành; 50% - 60% là của cấp phòng, vụ, cục, tổng cục ở Trung ương. ® Miẹo nhớ: Nhớ "phòng thuộc sở: trên 30%": càng cấp cao tỷ lệ càng cao, cấp phòng thuộc sở dụng ở mức hơn một phần ba.',t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030: Về xây dựng đội ngũ cán bộ các cấp đủ phẩm chất, năng lực và uy tín, ngang tầm nhiệm vụ, đến năm 2030 phải có trên. ] số lãnh đạo, quản lý cấp phòng trực thuộc sở, ngành và tương đương đáp ứng mục tiêu của Chương trình.",o:["35%","25%","50%","30%"],c:3},{id:"vb13-77",s:"5 - BỔ SUNG: CẢI CÁCH TỔ CHỨC BỘ MÁY, CHẾ ĐỘ CÔNG VỤ VÀ TÀI CHÍNH CÔNG (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Aƒfuc [II (điểm a khoản 4) C hương trình ban hành kèm theo Điều 1 Nghị quyết số 76/NQ-CCP.",gt:"Mục tiêu đến năm 2030 là 80% số lãnh đạo, quản lý doanh nghiệp nhà nước có đủ khả năng làm việc trong môi trường quốc tế. Các tỷ lệ 50% - 60% và trên 30% là của các cấp lãnh đạo, quản lý khác.",mn:'Nhớ "doanh nghiệp nhà nước: 80%": doanh nghiệp cần ra biến lớn nên chỉ tiêu cao nhất.',t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, trong mục tiêu xây dựng đội ngũ cán bộ chuyên nghiệp, chất lượng cao đến năm 2030, [......... ] số lãnh đạo, quản lý doanh nghiệp nhà nước có đủ khả năng làm việc trong môi trường quốc tế.",o:["50%","80%","30%","60%"],c:1},{id:"vb13-78",s:"5 - BỔ SUNG: CẢI CÁCH TỔ CHỨC BỘ MÁY, CHẾ ĐỘ CÔNG VỤ VÀ TÀI CHÍNH CÔNG (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",gt:"Đúng là Trung ương 50% - 60%, cấp sở, ngành 25% - 35%, cấp phòng thuộc sở, ngành trên 30%; mức 80% thuộc lãnh đạo, quản lý doanh nghiệp nhà nước. Các phương án khác hoán đối tỷ lệ giữa các nhóm.",mn:'Nhớ “50-60 / 25-35 / trên 30": đi từ Trung ương xuông sở rồi đến phòng, như bậc thang cao dân rồi thấp.',t:"m",q:"Mục tiêu cải cách chế độ công vụ đến năm 2030 nếu tỷ lệ riêng cho từng nhóm lãnh đạo, quản lý và lãnh đạo doanh nghiệp nhà nước. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, phương án nào dưới đây ghép ĐÚNG tỷ lệ với từng nhóm?",o:["Cấp phòng, vụ, cục, tổng cục ở Trung ương: 50% - 60%; cấp sở, ngành: 25% - 35%; cấp phòng thuộc sở, ngành: 80%","Cấp phòng, vụ, cục, tổng cục ở Trung ương: 25% - 35%; cấp sở, ngành: 50% - 60%; cấp phòng thuộc sở, ngành: trên 30%","Cấp phòng, vụ, cục, tổng cục ở Trung ương: 50% - 60%; cấp sở, ngành: 25% - 35%; cấp phòng thuộc sở, ngành: trên 30%","Cấp phòng, vụ, cục, tổng cục ở Trung ương: 50% - 60%; cấp sở, ngành: trên 30%; cấp phòng thuộc sở, ngành: 25% - 35%"],c:2},{id:"vb13-79",s:"5 - BỔ SUNG: CẢI CÁCH TỔ CHỨC BỘ MÁY, CHẾ ĐỘ CÔNG VỤ VÀ TÀI CHÍNH CÔNG (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Vuc J!Ï (điểm ù khoản 3) Chương trình ban hành kèm theo Điều 1 Nghị quyết SỐ Zt NQ-CP.",gt:"Mục tiêu đến năm 2025 là hoàn thành sắp xếp thu gọn các đơn vị hành chính cấp xã và thôn, tổ dân phố theo tiêu chuẩn quy định. Đơn vị hành chính cấp tỉnh chỉ thuộc diện nghiên cứu, thí điểm sắp xếp.",mn:'Nhớ "thu gọn từ gốc: xã - thôn - tổ dân phố”: đơn nhà bắt đầu từ các phòng nhỏ trước.',t:"m",q:"Cải cách tổ chức bộ máy hành chính nhà nước đặt ra các mục tiêu cụ thể đến năm 2025, trong đó có việc hoàn thành sắp xếp thu gọn các đơn vị hành chính theo tiêu chuẩn quy định. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, đối tượng được sắp xếp thu gọn là:",o:["Đơn vị hành chính cấp xã và thôn, tổ dân phố","Đơn vị hành chính cấp tỉnh và đơn vị sự nghiệp công lập","Đơn vị hành chính cấp tỉnh và thôn, tổ dân phố","Thôn, tổ dân phố và cơ quan chuyên môn cấp tỉnh"],c:0},{id:"vb13-80",s:"5 - BỔ SUNG: CẢI CÁCH TỔ CHỨC BỘ MÁY, CHẾ ĐỘ CÔNG VỤ VÀ TÀI CHÍNH CÔNG (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Mục III (điểm b khoản 3) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 76/NQ-CP.",gt:'Chương trình yêu cầu tăng cường chỉ đạo, điều hành, xử lý công việc trên môi trường số, tổ chức họp, hội nghị bằng hình thức trực tuyến, không giấy tờ. Phân cấp và giảm ban quản lý dự án là nhiệm vụ khác. $® Miẹo nhớ: Nhớ "làm việc số, hợp trực tuyến, bỏ giấy": hợp qua màn hình thay vì ôm cặp hồ sơ.',t:"m",q:"Nhằm nâng cao năng suất, hiệu quả hoạt động của cơ quan hành chính nhà nước các cấp trên cơ sở ứng dụng mạnh mẽ các tiến bộ khoa học và công nghệ, Chương trình đề ra nhiệm vụ nào về phương thức làm việc? Theo Nghị quyết AQ.ở XQg-C.PCCIHUC 021-2030 Trang.39 số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, nhiệm vụ đó là:",o:["Tăng cường phân cấp, phân quyền giữa Trung ương và địa phương","Duy trì hợp trực tiếp và xử lý hồ sơ bằng văn bản giấy ở các cấp để bảo đảm tính chặt chẽ, đồng thời chí ứng dụng công nghệ thông tin ở khâu lưu trữ văn bản sau khi công việc đã hoàn tất","Xử lý công việc trên môi trường số, hợp trực tuyến, không giấy tờ","Sắp xếp, giảm tối đa các ban quản lý dự án"],c:2},{id:"vb13-81",s:"5 - BỔ SUNG: CẢI CÁCH TỔ CHỨC BỘ MÁY, CHẾ ĐỘ CÔNG VỤ VÀ TÀI CHÍNH CÔNG (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Mục III (điểm b khoản 3) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 7Z0/NQ-CP.",gt:'Chương trình đề ra ban hành giải pháp khuyến khích sáp nhập, tăng quy mô các đơn vị hành chính ở nơi có đủ điều kiện để nâng cao năng lực quản lý, điều hành và tăng nguồn lực địa phương. Chia tách đi ngược định hướng này. ® Miẹo nhớ: Nhớ "sáp nhập đế mạnh lên": ghép nhiều nhóm nhỏ thành một đội lớn thì có thêm sức.',t:"m",q:"Trường hợp tình X muốn nâng cao năng lực quản lý, điều hành và tăng cường các nguồn lực của địa phương thông qua việc sắp xếp đơn vị hành chính ở những nơi có đủ điều kiện. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, giải pháp phù hợp với định hướng của Chương trình là gì?",o:["Khuyến khích chia tách các đơn vị hành chính có quy mô lớn thành nhiều đơn vị nhỏ hơn nhằm tăng cường sự gắn dân, đồng thời giảm bớt cấp trung gian trong bộ máy quản lý của địa phương","Khuyến khích sáp nhập, tăng quy mô đơn vị hành chính nội đủ điều kiện","Thí điểm mô hình chính quyền đô thị trực thuộc cấp tỉnh","Sáp nhập thôn, tổ dân phố theo yêu cầu quản lý"],c:1},{id:"vb13-82",s:"5 - BỔ SUNG: CẢI CÁCH TỔ CHỨC BỘ MÁY, CHẾ ĐỘ CÔNG VỤ VÀ TÀI CHÍNH CÔNG (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Mục III (điểm b khoản 3) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 76/NQ-CP.",gt:"Chương trình nêu nhiệm vụ chuyên đổi các đơn vị sự nghiệp công lập có đủ điều kiện sang công ty cổ phần. Điều kiện là yếu tố bắt buộc, không áp dụng cho toàn bộ đơn vị; thi tuyển, thuê giám đốc và quy hoạch mạng lưới là nhiệm vụ khác.",mn:'Nhớ "đủ điều kiện mới có phần hóa”: chỉ đơn vị dự chuẩn mới được lên sân khấu.',t:"m",q:"Trong nhóm nhiệm vụ đối mới hệ thống tổ chức, quản lý và nâng cao hiệu quả hoạt động của các đơn vị sự nghiệp công lập thuộc cải cách tổ chức bộ máy, nhiệm vụ nào liên quan đến việc thay đổi mô hình của các đơn vị có đủ điều kiện? Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, nhiệm vụ đó là: VQ 70/NO-CP CCHC 2021-2030 Irang 4U",o:["Thí điểm thi tuyển, thuê giám đốc điều hành","Chuyển đổi sang công ty cổ phần các đơn vị có đủ điều kiện","Quy hoạch mạng lưới các đơn vị sự nghiệp công lập","Chuyển đổi toàn bộ các đơn vị sự nghiệp công lập sang công ty cổ phần, không phân biệt điều kiện, đồng thời giải thể các đơn vị chưa bảo đảm khả năng tự chủ tài chính trong giai đoạn đầu của Chương trình"],c:1},{id:"vb13-83",s:"5 - BỔ SUNG: CẢI CÁCH TỔ CHỨC BỘ MÁY, CHẾ ĐỘ CÔNG VỤ VÀ TÀI CHÍNH CÔNG (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Mục JII (điểm b khoản 3) ( hương trình ban hành kèm theo tiêu 1 Nghị quyết số 76/NQ-CP.",gt:"Các lĩnh vực trọng tâm gồm y tế; giáo dục và đào tạo; lao động, thương binh và xã hội; khoa học và công nghệ; văn hóa, thể thao và du lịch; thông tin và truyền thông. Tài chính và ngân hàng không năm trong danh sách này.",mn:'Nhớ "sáu lĩnh vực sự nghiệp công, không có tài chính - ngân hàng": trường, viện, bệnh viện, nhà văn hóa thuộc sự nghiệp, còn ngân hàng thì không.',t:"m",q:"Rà soát, hoàn thiện tiêu chí phân loại, điều kiện thành lập, sáp nhập, hợp nhất, giải thể và quy hoạch mạng lưới đơn vị sự nghiệp công lập là nhiệm vụ của cải cách tổ chức bộ máy. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, lĩnh vực nào dưới đây KHÔNG thuộc nhóm lĩnh vực trọng tâm của việc quy hoạch mạng lưới này?",o:["Tài chính và ngân hàng","Giáo dục và đào tạo","Khoa học và công nghệ","Y tế"],c:0},{id:"vb13-84",s:"5 - BỔ SUNG: CẢI CÁCH TỔ CHỨC BỘ MÁY, CHẾ ĐỘ CÔNG VỤ VÀ TÀI CHÍNH CÔNG (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Mục II (điểm b khoản 4) Chương trình ban hành kum theo Điều 1 Nghị quyết số Z6 NQ-CP.",gt:"Chương trình yêu cầu đánh giá dân chủ, công khai, minh bạch, lượng hóa tiêu chí dựa trên kết quả thực hiện nhiệm vụ, gắn với vị trí việc làm, sản phẩm cụ thể. Đánh giá theo thâm niên không có trong định hướng.",mn:'Nhớ "đánh giá bằng kết quả, không bảng thâm niên”: chậm bài theo bài làm, không theo số nam đi học.',t:"m",q:"Trong nhiệm vụ cải cách chế độ công vụ, Chương trình định hướng đổi mới phương pháp, quy trình đánh giá, phân loại cán bộ, công chức, viên chức. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, nội dung nào dưới đây KHÔNG phù hợp với định hướng đó?",o:["Gắn đánh giá với vị trí việc làm, thông qua công việc, sản phẩm cụ thể của người được đánh giá","Lượng hóa các tiêu chí đánh giá dựa trên kết quả thực hiện nhiệm vụ của cán bộ, công chức, viên chức XVQ 7b.NQO-CP CCHC 2021-2030 Irang di","Đánh giá theo hướng dân chủ, công khai, minh bạch đối với cán bộ, công chức, viên chức","Đánh giá chủ yếu theo thâm niên công tác, không gắn với vị trí việc làm và sản phẩm công việc cụ thể"],c:3},{id:"vb13-85",s:"5 - BỔ SUNG: CẢI CÁCH TỔ CHỨC BỘ MÁY, CHẾ ĐỘ CÔNG VỤ VÀ TÀI CHÍNH CÔNG (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Mục II (điểm b khoản 4) Chương trình ban hành kèm theo Điều 1 Nghị quyền số 7® NQ-C.P.",gt:"Chương trình nêu thi tuyển cạnh tranh để bổ nhiệm các chức danh lãnh đạo, quản lý cấp vụ, sở, phòng và tương đương. Các cấp bộ, ban, ngành, tổng cục, cục không được nêu trong nhiệm vụ này.",mn:'Nhớ "vụ - sử - phòng”: ba tên gọi quen thuộc Ở các cơ quan, ghép thành một dãy đề thuộc.',t:"m",q:"Một nhiệm vụ của cải cách chế độ công vụ là tiếp tục mở rộng và triển khai có hiệu quả việc thi tuyển cạnh tranh để bổ nhiệm các chức danh lãnh đạo, quản lý. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, việc thi tuyển cạnh tranh được xác định áp dụng đối với các chức danh thuộc cấp nào?",o:["Cấp vụ, sở, phòng và tương đương","Cấp phòng, ban và tổ chuyên môn","Cấp tổng cục, cục và tương đương","Cấp bộ, ban, ngành và tương đương"],c:0},{id:"vb13-86",s:"5 - BỔ SUNG: CẢI CÁCH TỔ CHỨC BỘ MÁY, CHẾ ĐỘ CÔNG VỤ VÀ TÀI CHÍNH CÔNG (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Mục II (điểm b khoản 4) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 76/NQ-CP.",gt:"Chương trình yêu cầu xây dựng, ban hành quy định thực hiện thống nhất việc kiểm định chất lượng đầu vào công chức, làm cơ sở cho các bộ, ngành, địa phương lựa chọn, tuyển dụng; đồng thời tăng cường phân cấp kiểm định theo lĩnh vực đặc thù và vùng, khu vực. Phương án tự xây dựng riêng trái yêu cầu thống nhất.",mn:'Nhớ "một thước đo đầu vào chung”: cùng một thước đó thì các nơi tuyển chọn mới công bằng.',t:"m",q:"Trường hợp một bộ muốn bảo đảm tuyến được công chức thực sự có năng lực ngay từ khâu đầu vào và cán một cơ sở chung để các bộ, ngành, địa phương lựa chọn, tuyển dụng theo yêu cầu, nhiệm vụ. Theo Nghị quyết số 76/NQ- CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, giải pháp nào được Chương trình đề ra?",o:["Ban hành tiêu chuẩn chức danh công chức lãnh đạo, quản lý","Giao từng bộ, ngành, địa phương tự xây dựng tiêu chí kiểm định riêng cho mỗi đợt tuyển dụng, không có quy định thống nhất làm cơ sở lựa chọn và phân cấp theo lĩnh vực đặc thù, theo vùng, khu vực","Giảm tỷ lệ người phục vụ trong từng cơ quan, nhất là khối văn phòng","Thống nhất kiểm định chất lượng đầu vào công chức AQ.ở XQg-C.PCCIHUC 021-2030 rang 42"],c:3},{id:"vb13-87",s:"5 - BỔ SUNG: CẢI CÁCH TỔ CHỨC BỘ MÁY, CHẾ ĐỘ CÔNG VỤ VÀ TÀI CHÍNH CÔNG (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Mục 7Ï (điểm b khoản 4) Chương trình ban hành kèm theo tiêu 1 Nghị quyết số 76/NQ-C.P.",gt:"Chương trình yêu cầu xây dựng, ban hành văn bản về chế độ tiền lương mới đối với cán bộ, công chức, viên chức và lực lượng vũ trang theo lộ trình cải cách chính sách tiền lương. Phương án áp dụng ngày không phù thuộc lộ trình là sai.",mn:'Nhớ "lương mới đi theo lộ trình”: tăng lương như leo cầu tháng, từng bậc một theo kế hoạch.',t:"m",q:"Cải cách chế độ công vụ gồm nhiệm vụ xây dựng, hoàn thiện văn bản pháp luật về tiền lương đối với cán bộ, công chức, viên chức và lực lượng vũ trang. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, các văn bản này được xây dựng, hoàn thiện theo hướng nào?",o:["Chế độ tiền lương mới áp dụng đồng thời cho cán bộ, công chức, viên chức và lực lượng vũ trang ngay từ năm 2021, không phù thuộc vào lộ trình cải cách chính sách tiền lương đã được xác định","Cơ chế khoán kinh phí quản lý hành chính tại các cơ quan nhà nước","Chế độ tiền lương mới chỉ áp dụng cho cán bộ, công chức, viên chức","Chế độ tiền lương mới theo lộ trình cải cách chính sách tiền lương"],c:3},{id:"vb13-88",s:"5 - BỔ SUNG: CẢI CÁCH TỔ CHỨC BỘ MÁY, CHẾ ĐỘ CÔNG VỤ VÀ TÀI CHÍNH CÔNG (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Mục 1Ï (điểm b khoản 4) Chương trình ban hành kèm theo Điều 1 Nghị quyết số Z67/NQ-CP.",gt:"Nội dung bồi dưỡng được rà soát để không trùng lắp, tiết kiệm, hiệu quả và cắt giảm các chứng chỉ bồi dưỡng không cần thiết. Phương án tăng chứng chỉ hoặc chuyển toàn bộ rà ngoài công lập không có trong Chương trình.",mn:'Nhớ "gọn - tiết kiệm - bớt chứng chỉ": từ hồ sơ chứng chỉ chỉ giữ những gì thật sự cần.',t:"m",q:"Chương trình yêu cầu rà soát, sửa đổi, bổ sung nội dung chương trình bồi dưỡng kiến thức quản lý nhà nước theo tiêu chuẩn ngạch công chức, hạng chức danh nghề nghiệp viên chức và yêu cầu của vị trí việc làm. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, mục đích được nêu của việc này là gì?",o:["Bảo đảm không trùng lắp, tiết kiệm, hiệu quả và cắt giảm các chứng chỉ bồi dưỡng không cần thiết","Bảo đảm tăng thời lượng, mở rộng nội dung và bố sung thêm các chứng chỉ bồi dưỡng theo từng ngạch công chức","Bảo đảm thống nhất chương trình và duy trì toàn bộ các chứng chỉ bồi dưỡng đã có theo từng hạng chức danh VQ zop'NQO-CP CCHC 2021-2030 Irang d3","Bảo đảm không trùng lặp, tiết kiệm, hiệu quả và chuyển toàn bộ việc bồi dưỡng sang các cơ sở ngoài công lập"],c:0},{id:"vb13-89",s:"5 - BỔ SUNG: CẢI CÁCH TỔ CHỨC BỘ MÁY, CHẾ ĐỘ CÔNG VỤ VÀ TÀI CHÍNH CÔNG (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Mục JII (điểm a khoản 5) Chủ 'ng trình ban hành kèm theo Điều 1 Nghị quyết số 70/NQ-C.P.",gt:"Mục tiêu đến năm 2025 là 100% đơn vị sự nghiệp kinh tế và sự nghiệp khác có đủ điều kiện hoàn thành chuyển đổi thành công ty cổ phần hoặc chuyển sang tự bảo đảm chi thường xuyên và chỉ đầu tư. Chỉ tiêu 20% là của đơn vị sự nghiệp công lập tự bảo đảm chi thường xuyên.",mn:'Nhớ "kinh tế và khác: 100%": đơn vị sự nghiệp kinh tế đủ điều kiện thì phải ra tự chủ hết.',t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030: Về cải cách tài chính công, đến năm 2025, [......... | đơn vị sự nghiệp kinh tế và sự nghiệp khác, có đủ điều kiện, hoàn thành việc chuyển đổi thành công ty cổ phần hoặc chuyển sang tự bảo đảm chi thường xuyên và chỉ đầu tư.",o:["50%","100%","90%","80%"],c:1},{id:"vb13-90",s:"5 - BỔ SUNG: CẢI CÁCH TỔ CHỨC BỘ MÁY, CHẾ ĐỘ CÔNG VỤ VÀ TÀI CHÍNH CÔNG (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Mục HÍ (điểm b khoản 5) Chương trình ban hành kèm theo Điều 1 Nghị quyết số Z0 NQ-CB,",gt:"Chương trình nêu nhiệm vụ đẩy mạnh tái cơ cấu doanh nghiệp nhà nước và đối mới cơ chế quản lý vốn nhà nước đầu tư tại doanh nghiệp, kèm cơ chế, chính sách nâng cao hiệu quả quản trị. Phương án tập trung quyền quyết định về cấp trên không có trong văn bản.",mn:'Nhớ "tái cơ cấu + đổi mới quản lý vốn": sắp xếp lại doanh nghiệp rồi mới quản lý đồng vốn cho chất.',t:"m",q:"Trong nội dung cải cách tài chính công, Chương trình có nhiệm vụ liên quan trực tiếp đến doanh nghiệp nhà nước. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, nhiệm vụ đó là:",o:["Tăng vốn nhà nước đầu tư tại mọi doanh nghiệp, đồng thời ban hành cơ chế, chính sách thúc đẩy, đổi mới quản trị doanh nghiệp theo hướng tập trung toàn bộ quyền quyết định về cơ quan quản lý cấp trên","Hoàn thiện thị trường chứng khoán, bảo hiểm, trái phiếu","Chuyến đơn vị sự nghiệp công lập đủ điều kiện sang công ty cổ phần","Tái cơ cấu doanh nghiệp nhà nước, đổi mới quản lý vốn nhà nước"],c:3},{id:"vb13-91",s:"5 - BỔ SUNG: CẢI CÁCH TỔ CHỨC BỘ MÁY, CHẾ ĐỘ CÔNG VỤ VÀ TÀI CHÍNH CÔNG (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Mục II (điểm a khoản 3) Chương trình ban hành kèm theo Điều 1 Nghị quyết số Z6b..NQ9-CP.",gt:"Mức hài lòng về dịch vụ y tế, giáo dục công lập là tối thiểu 85% vào năm 2025 và 90% vào năm 2030, không phải 95%. Các nhận định về giảm 10% đơn vị sự nghiệp và biên chế sự nghiệp đều đúng.",mn:'Nhớ "y tế, giáo dục: 85% rồi 90%": hai mốc tăng dân, không có mốc 95%6.',t:"m",q:"Cải cách tổ chức bộ máy hành chính nhà nước có các chỉ tiêu về giảm đơn vị sự nghiệp công lập, giảm biên chế sự nghiệp và mức độ hài lòng của người dân. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, nhận định nào dưới đây là KHÔNG đúng?",o:["Đến năm 2025, giảm tối thiểu bình quân cả nước 10% số lượng đơn vị sự nghiệp công lập so với năm 2021","Đến năm 2025, giảm tối thiểu bình quân cả nước 10% biên chế sự nghiệp hưởng lương từ ngân sách nhà nước so với năm 2021","Đến năm 2025, mức độ hài lòng của người dân về cung cấp dịch vụ y tế, giáo dục công lập đạt tối thiểu 95%","Đến năm 2030, tiếp tục giảm bình quân 10% biên chế sự nghiệp hưởng lương từ ngân sách nhà nước so với năm 2025"],c:2},{id:"vb13-92",s:"5 - BỔ SUNG: CẢI CÁCH TỔ CHỨC BỘ MÁY, CHẾ ĐỘ CÔNG VỤ VÀ TÀI CHÍNH CÔNG (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Mục HÍ (điểm b khoản 5) Chương trình ban hành kèm theo Điều 1 Nghị quyết số Z0 NQ-CB,",gt:"Cơ chế tự chủ tài chính gồm các quy định về nguồn thu, nhiệm vụ chi, phân phối thu nhập bổ sung; thẩm quyền, trách nhiệm của người đứng đầu. Tiêu chí phân loại, điều kiện thành lập, sáp nhập, giải thể thuộc nhiệm vụ cải cách tổ chức bộ máy.",mn:'Nhớ "tự chủ tài chính = thu - chi - phân phối - người đứng đầu": chuyển tiền bạc năm trong tự chủ, chuyên thành lập hay giải thể thì không.',t:"m",q:"Hoàn thiện cơ chế tài chính tại các đơn vị sự nghiệp công lập là nhiệm vụ của cải cách tài chính công, trong đó có hoàn thiện pháp luật về cơ chế tự chủ tài chính. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, nội dung nào dưới đây KHÔNG thuộc các quy định về cơ chế tự chủ tài chính của đơn vị sự nghiệp công lập?",o:["Tiêu chí phân loại, điều kiện thành lập, sáp nhập, hợp nhất, giải thể đơn vị sự nghiệp công lập","Thẩm quyền, trách nhiệm của người đứng đầu đơn vị sự nghiệp công lập","Phân phối thu nhập bổ sung của đơn vị sự nghiệp công lập","Nguồn thu và nhiệm vụ chỉ của đơn vị sự nghiệp công lập"],c:0},{id:"vb13-93",s:"5 - BỔ SUNG: CẢI CÁCH TỔ CHỨC BỘ MÁY, CHẾ ĐỘ CÔNG VỤ VÀ TÀI CHÍNH CÔNG (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Mục II (điểm b khoản 4) Chương trình ban hành kèm theo Điều 1 Nghị quyết số Zb..NQ9-CP.",gt:"Chương trình vêu câu đổi mới cơ chế quản lý, chế độ, chính sách đối với cán bộ, công chức ở xã, phường, thị trấn và người hoạt động không chuyên trách, bảo đảm giảm dần số lượng, nâng cao hiệu quả, thực hiện khoán kinh phí.",mn:'Nhớ "giảm dần + khoán kinh phí": bớt người, giao gọn một khoản chi để chủ động.',t:"m",q:"Trường hợp xã Ý có nhiều người hoạt động không chuyên trách ở cấp xã; chính quyền căn đổi mới cơ chế quản lý, nâng cao hiệu quả hoạt động và thực hiện khoán kinh phí. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, định hướng phù hợp đối với đội ngũ này là gì?",o:["Giảm dần số lượng người hoạt động không chuyên trách, thực hiện khoán kinh phí","Duy trì số lượng người hoạt động không chuyên trách ở cấp xã, tăng định mức chi từ ngân sách nhà nước và giao đơn vị cấp trên quyết định phương thức cấp kinh phí cho từng chức danh","Sắp xếp, sáp nhập thôn, tổ dân phố phù hợp yêu cầu quản lý","Giảm tỷ lệ người phục vụ trong từng cơ quan, nhất là khối văn phòng"],c:0},{id:"vb13-94",s:"5 - BỔ SUNG: CẢI CÁCH TỔ CHỨC BỘ MÁY, CHẾ ĐỘ CÔNG VỤ VÀ TÀI CHÍNH CÔNG (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Mục (II (điểm a khoản 4) Chương trình ban hành kèm theo Điều Ì Nghị quyết số Z6: NQ-C.P. XQ 7o XQ-CP CCHIU “021-7030 Trung d5",gt:'Mục tiêu đến năm 2025 là đội ngũ có cơ cấu hợp lý, đáp ứng tiêu chuẩn chức danh, vị trí việc làm, khung năng lực. Cụm "chuyên nghiệp, chất lượng cao" thuộc mục tiêu đến năm 2030.',mn:"Nhớ ”2025: cơ cấu hợp lý; 2030: chất lượng cao”: trước hết sắp xếp cho đúng, sau đó mới nâng chất lượng.",t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030: Về cải cách chế độ công vụ, đến năm 2025, xây dựng được đội ngũ cán bộ, công chức, viên chức có [........ ], đáp ứng tiêu chuẩn chức danh, vị trí việc làm và khung năng lực theo quy định.",o:["uy tín cấp chiến lược","trình độ ngang tầm nhiệm vụ","cơ cấu hợp lý","chuyên nghiệp, chất lượng cao"],c:2},{id:"vb13-95",s:"5 - BỔ SUNG: CẢI CÁCH TỔ CHỨC BỘ MÁY, CHẾ ĐỘ CÔNG VỤ VÀ TÀI CHÍNH CÔNG (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Mục III (điểm a khoản 3) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 76/NQ-CP.",gt:"Mục tiêu gồm: rà soát chức năng, nhiệm vụ các cấp; phân định rõ mõô hình chính quyền nông thôn, đô thị, hải đảo, đơn vị hành chính - kinh tế đặc biệt; sắp xếp, tinh gọn; đẩy mạnh phân cấp; sắp xếp lại đơn vị sự nghiệp công lập theo hướng tinh gọn. Các phương án khác đối hoặc thêm nội dung sai.",mn:'Nhớ "rà - phân định - tinh gọn - phân cấp - sự nghiệp”: nam bước như dọn một căn nhà tự kiểm kê đến sắp xếp lại. Phũn bổ sung cho nội dung 6: tũng cường dạng điền khuyết số liệu chỉ tiêu đến năm 2025 và 2030, phân biệt các mộc, các nhiệm vụ về hạ tổng số, dữ liệu số, ứng dụng và tình huống vận dụng.',t:"m",q:"Cải cách tổ chức bộ máy hành chính nhà nước đặt ra mục tiêu chung gồm nhiều nhiệm vụ gắn với chức năng, mô hình tổ chức và phân cấp. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, phương án nào dưới đây nêu ĐÚNG và ĐẦY ĐỦ nhất các nội dung của mục tiêu này?",o:["Rà soát chức năng, nhiệm vụ của cơ quan hành chính trung ương; phân định rõ mô hình chính quyền nông thôn, đô thị, hải đảo và đơn vị hành chính - kinh tế đặc biệt; sắp xếp, tinh gọn tổ chức; đẩy mạnh phân cấp; tăng số lượng đơn vị sự nghiệp","Rà soát chức năng, nhiệm vụ của cơ quan hành chính các cấp; hợp nhất mô hình chính quyền nông thôn với đô thị; sắp xếp, tinh gọn tổ chức; đẩy mạnh phân cấp; sắp xếp lại đơn vị sự nghiệp công lập theo hướng tinh gọn","Rà soát chức năng, nhiệm vụ của cơ quan hành chính các cấp; phân định rõ mô hình chính quyền nông thôn, đô thị, hải đảo và đơn vị hành chính - kinh tế đặc biệt; sắp xếp, tinh gọn tổ chức; đẩy mạnh phân cấp; sắp xếp lại đơn vị sự nghiệp công lập theo hướng tinh gọn","Rà soát chức năng, nhiệm vụ của cơ quan hành chính các cấp; phân định rõ mô hình chính quyền nông thôn, đô thị, hải đảo và đơn vị hành chính - kinh tế đặc biệt; sắp xếp, tinh gọn tổ chức; thu hẹp phân cấp; giữ nguyên đơn vị sự nghiệp công lập"],c:2},{id:"vb13-96",s:"PHẦN 6 - BỔ SUNG: XÂY DỰNG VÀ PHÁT TRIỂN CHÍNH PHỦ ĐIỆN TỬ, CHÍNH PHỦ SỐ (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Mục JII (điểm a khoản 6) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 76/NQ-CP.",gt:"Mục tiêu đến năm 2025 là 100% Cổng Dịch vụ công, Hệ thống thông tin một cửa điện tử cấp bộ, cấp tỉnh được kết nối, chia sẻ dữ liệu với Công Dịch vụ công quốc gia.",mn:'Nhớ "cấp bộ, cấp tỉnh: kết nối đủ 100%": mọi công đều phải nối về công quốc gia.',t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030: Về xây dựng và phát triển Chính phủ điện tử, Chính phủ số, đến năm 2025, [........ | Cổng Dịch vụ công, Hệ thống thông tin một cửa điện tử cấp bộ, cấp tỉnh được kết nối, chia sẻ dữ liệu với Cổng Dịch vụ công quốc gia.",o:["100%","70%","90%","80%"],c:0},{id:"vb13-97",s:"PHẦN 6 - BỔ SUNG: XÂY DỰNG VÀ PHÁT TRIỂN CHÍNH PHỦ ĐIỆN TỬ, CHÍNH PHỦ SỐ (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Mục III (điểm a khoản 6) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 76/NQ-CP.",gt:"Mục tiêu đến năm 2025 là 100% người dân, doanh nghiệp sử dụng dịch vụ công trực tuyến được cấp định danh và xác thực điện tử thông suốt, hợp nhất. Tỷ lệ 90% là chi tiêu của năm 2030 đối với người dân, doanh nghiệp tham gia hệ thống Chính phủ điện tử.",mn:'Nhớ "ai dụng dịch vụ công trực tuyến đều có định danh”: dụng dịch vụ là có tài khoản, không bỏ sót ai.',t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030: Đến năm 2025, [........ ] người dân, doanh nghiệp sử dụng dịch vụ công trực tuyến được cấp định danh và xác thực điện tử thông suốt và hợp nhất trên tất cả các hệ thống thông tin của các cấp chính quyền từ Trung ương đến địa phương.",o:["100%","70%","80%","90%"],c:0},{id:"vb13-98",s:"PHẦN 6 - BỔ SUNG: XÂY DỰNG VÀ PHÁT TRIỂN CHÍNH PHỦ ĐIỆN TỬ, CHÍNH PHỦ SỐ (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Mục (0 (điểm a khoản 6) Chương trình ban hành kèm theo Điều ‡ Nghị quyền số z6 NQ-C.P.",gt:"Mục tiêu đến năm 2025 là 80% hệ thống thông tin của bộ, ngành, địa phương liên quan đến người dân, doanh nghiệp được kết nối, liên thông qua Trục liên",t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030: Đến năm 2025, [........ ] các hệ thống thông tin của bộ, ngành, địa phương có liên quan đến người dân, doanh nghiệp đã đưa vào vận hành, khai thác được kết nối, liên thông qua Trục liên thông văn bản quốc gia và nền tảng tích hợp, chia sẻ dữ liệu.",o:["60%","90%","100%","80%"],c:3},{id:"vb13-99",s:"PHẦN 6 - BỔ SUNG: XÂY DỰNG VÀ PHÁT TRIỂN CHÍNH PHỦ ĐIỆN TỬ, CHÍNH PHỦ SỐ (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Vục J (điểm ú khoản 6®) Chương trình ban hành kèm theo Điều Ì Nghị quyết số 7D. NQ-CP.",gt:"Mục tiêu đến năm 2025 là 100% hệ thống báo cáo của các bộ, ngành, địa phương được kết nối liên thông, chia sẻ dữ liệu với Hệ thống thông tin báo cáo quốc gia.",mn:'Nhớ "báo cáo thì nội đủ 100%”: mọi động báo cáo đều độ về một đầu mối quốc gia. thông văn bản quốc gia và nền tảng tích hợp, chia sẻ dữ liệu; thông tin đa số hóa không phải cung cấp lại. Nhớ "hệ thống thông tin liên thông: 80%”: phân lớn nơi được, còn lại tiếp tục hoàn thiện.',t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030: Đến năm 2025, [......... ] hệ thống báo cáo của các bộ, ngành, địa phương được kết nối liên thông, chia sẻ dữ liệu với Hệ thống thông tin báo cáo quốc gia.",o:["100%","80%","90%","70%"],c:0},{id:"vb13-100",s:"PHẦN 6 - BỔ SUNG: XÂY DỰNG VÀ PHÁT TRIỂN CHÍNH PHỦ ĐIỆN TỬ, CHÍNH PHỦ SỐ (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Mục II (điểm a khoản 6) Chương trình ban hành kèm theo Điều 1 Nghị quyết Số 7O0/NQ-CP.",gt:'Mục tiêu đến năm 2025 là 100% Ủy ban nhân dân cấp tỉnh thực hiện họp thông qua Hệ thống thông tin phục vụ họp và xử lý công việc của Chính phủ đối với các cuộc họp của Ủy ban nhân dân. $® Miẹo nhớ: Nhớ "cấp tỉnh hợp trên hệ thống: đủ 100%”: tính nào cũng họp qua hệ thống chung của Chính phủ.',t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030: Triển khai nhân rộng Hệ thống thông tin phục vụ họp và xử lý công việc của Chính phủ đến Ủy ban nhân dân các cấp, đến AQ.ở XQg-C.PCCIHUC 021-2030 rang 49 năm 2025 có......... | cấp tỉnh thực hiện họp thông qua Hệ thống này đối với các cuộc họp của Ủy ban nhân dân.",o:["100%","80%","90%","60%"],c:0},{id:"vb13-101",s:"PHẦN 6 - BỔ SUNG: XÂY DỰNG VÀ PHÁT TRIỂN CHÍNH PHỦ ĐIỆN TỬ, CHÍNH PHỦ SỐ (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Mục JII (điểm a khoản 6) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 7o6/NQ-C.P.",gt:"Đến năm 2030, 100% hồ sơ công việc tại cấp bộ, cấp tỉnh và 70% tại cấp xã được xử lý trên môi trường mạng. Mức 90% (cấp bộ, cấp tỉnh năm 2025) và 60% (cấp xã năm 2025) là các giá trị của mốc trước đó.",mn:"Nhớ “2030: bộ - tính 100%, xã 70%”: cấp càng gần dân càng chậm hơn một nhịp.",t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030: Đến năm 2030, [......... | hồ sơ công việc tại cấp bộ, cấp tỉnh và [......... ] hồ sơ công việc tại cấp xã được xử lý trên môi trường mạng (không bao gồm hồ sơ xử lý công việc có nội dung mật).",o:["100%.... 60%","100%... 70%","90%... 60%","90%... 70%"],c:1},{id:"vb13-102",s:"PHẦN 6 - BỔ SUNG: XÂY DỰNG VÀ PHÁT TRIỂN CHÍNH PHỦ ĐIỆN TỬ, CHÍNH PHỦ SỐ (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Mục II (điểm a khoản 6) Chương trình ban hành kèm theo Điều 1 Nghị quyết SỐ 7o/NQ-CP.",gt:"Chỉ tiêu là 50% vào năm 2025 và 70% vào năm 2030 đối với hoạt động kiểm tra thực hiện qua môi trường số. Các phương án khác dùng giá trị của chỉ tiêu khác trong cùng nội dung.",mn:'Nhớ "kiểm tra số: 50 rồi 70": mỗi mốc tăng thêm hai mươi diểm phần trăm.',t:"m",q:"Chương trình đạt chỉ tiêu về tỷ lệ hoạt động kiểm tra của cơ quan quản lý nhà nước được thực hiện thông qua môi trường số và hệ thống thông tin của cơ quan quản lý. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, phương án nào dưới đây ghép ĐÚNG hai mốc 2025 và 2030?",o:["Năm 2025 đạt 70%; năm 2030 đạt 90% hoạt động kiểm tra","Năm 2025 đạt 80%; năm 2030 đạt 100% hoạt động kiểm tra","Năm 2025 đạt 30%; năm 2030 đạt 50% hoạt động kiểm tra","Năm 2025 đạt 50%; năm 2030 đạt 70% hoạt động kiểm tra"],c:3},{id:"vb13-103",s:"PHẦN 6 - BỔ SUNG: XÂY DỰNG VÀ PHÁT TRIỂN CHÍNH PHỦ ĐIỆN TỬ, CHÍNH PHỦ SỐ (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Mục J!I (điểm b khoản 6) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 76/NQ-CP.",gt:'Nhiệm vụ tái cấu trúc hạ tầng công nghệ thông tin, chuyển đổi thành hạ tầng số ứng dụng điện toán đám mây nhằm kết nối, quản lý nguồn lực, dữ liệu an toàn, linh hoạt, ổn định, hiệu quả. Các phương án còn lại là nhiệm vụ riêng khác của hạ tầng số. ® Miẹo nhớ: Nhớ "hạ tầng số = đám mây": đưa dữ liệu lên mây đế dụng chung, an toàn và linh hoạt.',t:"m",q:"Trong nhóm nhiệm vụ phát triển hạ tầng số quốc gia, Chương trình yêu cầu chuyển đổi hạ tầng công nghệ thông tin để kết nối, quản lý các nguồn lực, dữ liệu của cơ quan nhà nước một cách an toàn, linh hoạt, ổn định và hiệu quả. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, nội dung cụ thể là:",o:["Phát triển hạ tầng Internet vạn vật (IoT) phục vụ các ứng dụng nghiệp vụ, chuyên ngành, gắn kết với phát triển đô thị thông minh","Tái cấu trúc hạ tầng công nghệ thông tin, chuyển đổi thành hạ tầng số ứng dụng công nghệ điện toán đám mây","Phát triển hệ thống dữ liệu phục vụ triển khai Chính phủ điện tử hướng tới Chính phủ số tại bộ, ngành, địa phương","Phát triển hạ tầng truyền dẫn đáp ứng nhu cầu triển khai Chính phủ điện tử hướng tới Chính phủ số tại bộ, ngành, địa phương"],c:1},{id:"vb13-104",s:"PHẦN 6 - BỔ SUNG: XÂY DỰNG VÀ PHÁT TRIỂN CHÍNH PHỦ ĐIỆN TỬ, CHÍNH PHỦ SỐ (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Mục HÍ (điểm b khoản 6) Chương trình ban hành kèm theo Điều 1 Nghị quyết số Z0 NQ-CB,",gt:"Nền tảng tích hợp, chia sẻ dữ liệu cấp bộ/tỉnh viết tắt là LGSP; nền tảng cấp quốc gia việt tắt là NGSP. SOC là an toàn, an ninh mạng: EG DI là chỉ số Chính phủ điện tử.",mn:"Nhớ ”L là Local (cấp bộ/tỉnh), N là National (quốc gia)”: chủ cái dầu cho biết cấp của nền tảng.",t:"m",q:"Trong nhiệm vụ phát triển nền tảng và hệ thống số quy mô quốc gia, Nền tảng tích hợp, chia sẻ dữ liệu cấp bộ/tỉnh kết nối với Nền tảng tích hợp, chia sẻ dữ liệu quốc gia để trao đổi dữ liệu với cơ quan bên ngoài. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, hai nền tảng này được viết tắt lần lượt là:",o:["NGSP và LGSP","LGSP và EGDI","SÓC và LGSP","LGSP và NGSP"],c:3},{id:"vb13-105",s:"PHẦN 6 - BỔ SUNG: XÂY DỰNG VÀ PHÁT TRIỂN CHÍNH PHỦ ĐIỆN TỬ, CHÍNH PHỦ SỐ (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Mục Ji cdièm b khoản 6) Chương trình ban hành kèm theo Điều 1 Nghị quyết số “G NQ-C.P.",gt:"Nhiệm vụ phù hợp là xây dựng kho dữ liệu để lưu trữ dữ liệu điện tử của công dân khi thực hiện giao dịch trực tuyến trên Cổng Dịch vụ công quốc gia và hệ thống thông tin giải quyết thủ tục hành chính cấp bộ, cấp tỉnh. Hệ thống phân tích, xử lý dữ liệu tổng hợp phục vụ tạo thông tin, dịch vụ dữ liệu mới.",mn:'Nhớ "giao dịch xong, dữ liệu vào kho": lần sau lấy từ kho ra, khởi khai lại.',t:"m",q:"Bà B là người dân muốn có nơi lưu trữ tập trung dữ liệu điện tử phát sinh khi giao dịch trực tuyến với cơ quan nhà nước trên Cổng Dịch vụ công quốc gia đế không phải kê khai lại thông tin nhiều lần. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, nhiệm vụ nào của Chương trình đáp ứng yêu cầu này?",o:["Xây dựng Hệ thống phân tích, xử lý dữ liệu tổng hợp cấp bộ, cấp tỉnh nhằm lưu trữ tập trung, tổng hợp, phân tích dữ liệu số từ các nguồn khác nhau để tạo ra thông tin mới, dịch vụ dữ liệu mới","Xây dựng kho dữ liệu điện tử của công dân khi giao dịch trực tuyến","Phát triển hệ thống làm việc từ xa của cơ quan nhà nước","Xây dựng Nền tảng ứng dụng trên thiết bị di động"],c:1},{id:"vb13-106",s:"PHẦN 6 - BỔ SUNG: XÂY DỰNG VÀ PHÁT TRIỂN CHÍNH PHỦ ĐIỆN TỬ, CHÍNH PHỦ SỐ (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"VMuc Jl (điểm E khoản 6} Chương trình ban hành kèm theo Điều 1 Nghị quyết số 7b“NQ-CP.",gt:"Mục tiêu đến năm 2025 là 100% bộ, ngành, địa phương hoàn thành xây dựng và vận hành Phân hệ theo dõi nhiệm vụ do người đứng đầu giao, bảo đảm hiển thị theo thời gian thực.",mn:'Nhớ "theo dõi nhiệm vụ thời gian thực: đủ 100% ": giao việc xong là màn hình hiện tiến độ ngày.',t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030: Đến năm 2025, [........ ] bộ, ngành, địa phương hoàn thành việc xây dựng và đưa vào vận hành Phân hệ theo dõi nhiệm vụ do Bộ trưởng, Thủ trưởng cơ quan ngang bộ, Thủ trưởng cơ quan thuộc Chính phủ, Ủy ban nhân dân và Chủ tịch Ủy ban nhân dân cấp tỉnh giao, bảo đảm hiển thị theo thời gian thực.",o:["90%","70%","100%","80%"],c:2},{id:"vb13-107",s:"PHẦN 6 - BỔ SUNG: XÂY DỰNG VÀ PHÁT TRIỂN CHÍNH PHỦ ĐIỆN TỬ, CHÍNH PHỦ SỐ (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Mục JHI (điểm b khoản 6) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 70/NQ-CP.",gt:"Việc phát triển, hoàn thiện thực hiện trên cơ sở hợp nhất Cổng Dịch vụ công và Hệ thống thông tin một cửa điện tử của các bộ, ngành, địa phương, tích hợp toàn bộ dịch vụ công trực tuyến mức độ 3, 4 lên Cổng Dịch vụ công quốc gia. Mức độ 2, 3 là chi tiết sai.",mn:'Nhớ "hợp nhất công + một cửa, tích hợp mục 3, 4": gom hai của thành một, đưa dịch vụ cao cấp lên công quốc gia.',t:"m",q:"Nhằm cung cấp dịch vụ công trực tuyến thuận tiến cho người dân, doanh nghiệp, Chương trình có nhiệm vụ phát triển, hoàn thiện Cổng Dịch vụ công quốc gia và hệ thống thông tin giải quyết thủ tục hành chính cấp bộ, cấp tỉnh. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, nhiệm vụ này được thực hiện trên cơ sở nào?",o:["Hợp nhất Cổng Dịch vụ công và Hệ thống thông tin một cửa điện tử của các bộ, ngành, địa phương, đồng thời hoàn thành việc tích hợp toàn bộ dịch vụ công trực tuyến mức độ 2, 3 lên Cổng Dịch vụ công quốc gia","Hợp nhất Cổng Dịch vụ công và Hệ thống thông tin một cửa điện tử","Hợp nhất Cổng Dịch vụ công quốc gia với Cổng Thông tin điện tử Chính phủ","Tách riêng Cổng Dịch vụ công với Hệ thống thông tin một cửa điện tử"],c:1},{id:"vb13-108",s:"PHẦN 6 - BỔ SUNG: XÂY DỰNG VÀ PHÁT TRIỂN CHÍNH PHỦ ĐIỆN TỬ, CHÍNH PHỦ SỐ (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Mục III (điểm ø khoản 6) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 76/NQ-CP.",gt:"Mục tiêu là đổi mới phương thức làm việc, nâng cao năng suất, hiệu quả của cơ quan hành chính nhà nước các cấp, nâng cao chất lượng cung cấp dịch vụ công cho người dân, tổ chức. Các phương án khác thu hẹp phạm vi hoặc thêm nội dung không có.",mn:'Nhớ "đối cách làm - tăng năng suất - dịch vụ công tốt hơn”: ba ý nồi nhau như đối máy mới để làm nhanh và phục vụ khách tốt hơn.',t:"m",q:"Xây dựng và phát triển Chính phủ điện tử, Chính phủ số là nội dung thứ sáu của Chương trình, gắn với chuyên đổi số và ứng dụng các tiến bộ khoa học, công nghệ. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, mục tiêu của nội dung này là gì?",o:["Đổi mới phương thức làm việc, nâng cao năng suất, hiệu quả hoạt động của cơ quan hành chính nhà nước các cấp, nâng cao chất lượng cung cấp dịch vụ công cho người dân, tổ chức","Đổi mới phương thức làm việc, nâng cao năng suất, hiệu quả hoạt động của cơ quan hành chính nhà nước các cấp, bảo đảm mọi dịch vụ công đều được cung cấp trực tuyến toàn trình","Đổi mới phương thức làm việc, giảm chi phí đầu tư hạ tầng, nâng cao chất lượng cung cấp dịch vụ công cho người dân, tổ chức","Đổi mới phương thức làm việc, nâng cao năng suất, hiệu quả hoạt động của cơ quan hành chính nhà nước cấp Trung ương, nâng cao chất lượng cung cấp dịch vụ công cho người dân, tổ chức VQ 7b'NO-CP CCHC 2021-2030 Irang 5ì"],c:0},{id:"vb13-109",s:"PHẦN 6 - BỔ SUNG: XÂY DỰNG VÀ PHÁT TRIỂN CHÍNH PHỦ ĐIỆN TỬ, CHÍNH PHỦ SỐ (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Mục II (điểm a khoản 6) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 706/NQ-CP.",gt:"Mục tiêu 100% dịch vụ công trực tuyến mức độ 4 được cung cấp trên nhiều phương tiện, kể cả thiết bị di động, đặt ra cho năm 2030, không phải năm 2025. Các nhận định còn lại dụng.",mn:'Nhớ "mức độ 4 đủ 100% vào 2030”: dịch vụ cao nhất cần thêm thời gian, đến cuối giai đoạn mới dự.',t:"m",q:"Chương trình đặt các chỉ tiêu cho Chính phủ điện tử, Chính phủ số ở hai mốc 2025 và 2030, gồm xếp hạng EGDI, tỷ lệ hồ sơ xử lý trên môi trường mạng và dịch vụ công trực tuyến mức độ 4. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, nhận định nào dưới đây là KHÔNG đúng?",o:["Đến năm 2025, Việt Nam thuộc nhóm 70 nước dẫn đầu về Chính phủ điện tử (EGDI)","Đến năm 2025, 100% dịch vụ công trực tuyến mức độ 4 được cung cấp trên nhiều phương tiện truy cập, kể cả thiết bị di động","Đến năm 2025, 90% hồ sơ công việc tại cấp bộ, cấp tỉnh được xử lý trên môi trường mạng, trừ hồ sơ thuộc phạm vi bí mật nhà nước","Đến năm 2030, Việt Nam thuộc nhóm 50 nước dẫn đầu về Chính phủ điện tử (EGDI) theo chỉ tiêu của Chương trình"],c:1},{id:"vb13-110",s:"PHẦN 6 - BỔ SUNG: XÂY DỰNG VÀ PHÁT TRIỂN CHÍNH PHỦ ĐIỆN TỬ, CHÍNH PHỦ SỐ (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Mục HIÏ (diện b khoản 6} Chương trình ban hành kèm theo Điều 1 Nghị quyết SỐ Z9 NQ-CVP.",gt:"Chương trình yêu cầu tiếp tục phát triển, hoàn thiện Trục liên thông văn bản quốc gia thành nền tảng kết nối, chia sẻ dữ liệu số phục vụ chỉ đạo, điều hành. Các hệ thống còn lại có chức năng và nhiệm vụ riêng.",mn:'Nhớ "trục liên thông văn bản = đường trục nối dữ liệu”: như trục dường chính nội mọi ngà của bộ, ngành, địa phương.',t:"m",q:"Trong nhóm nhiệm vụ phát triển ứng dụng, dịch vụ nội bộ phục vụ chỉ đạo, điều hành của Chính phủ, Thủ tướng Chính phù, Chương trình yêu cầu tiếp tục phát triển, hoàn thiện một hệ thống thành nền tảng kết nối, chia sẻ dữ liệu số giữa các hệ thống thông tin, cơ sở dữ liệu của bộ, ngành, địa phương. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, đó là hệ thống nào?",o:["Hệ thống thông tin báo cáo quốc gia","Cổng Dịch vụ công quốc gia","Trục liên thông văn bản quốc gia","Cơ sở dữ liệu hộ tịch điện tử"],c:2},{id:"vb13-111",s:"PHẦN 6 - BỔ SUNG: XÂY DỰNG VÀ PHÁT TRIỂN CHÍNH PHỦ ĐIỆN TỬ, CHÍNH PHỦ SỐ (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Mục II (điểm b khoản 6) Chương trình ban hành kèm theo Điều 1 Nghị quyền sở ZbNQ-C P.",gt:"Chương trình yêu cầu phát triển dịch vụ phù hợp điều kiện, đặc thù, nhu cầu thực tế, ưu tiên trước dịch vụ giải quyết vấn đề bức thiết như tắc nghẽn giao thông, ô nhiễm môi trường, dồông thời bảo đảm hiệu quả, tránh hình thức, lãng phí. Việc triển khai thử nghiệm ở đô thị điển hình rồi nhân rộng.",mn:'Nhớ "việc bức thiết làm trước, tránh hình thức, lãng phí”: sửa mái dột trước khi sơn lại tường.',t:"m",q:"Trường hợp một đô thị của tỉnh Z đang gặp các vấn đề bức thiết như tắc nghẽn giao thông, ô nhiễm môi trường và muốn triển khai dịch vụ đô thị thông minh. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, hướng triển khai phù hợp với Chương trình là gì?",o:["Phát triển dịch vụ đô thị thông minh phù hợp điều kiện, đặc thù, nhu cầu thực tế, ưu tiên trước các dịch vụ giải quyết vấn đề bức thiết của xã hội, chấp nhận chi phí lớn đế đạt tiến độ nhanh","Phát triển dịch vụ đô thị thông minh đồng loạt trên tất cả các đô thị trong cùng một thời điểm, ưu tiên trước các dịch vụ giải quyết vấn đề bức thiết của xã hội, bảo đảm hiệu quả","Phát triển dịch vụ đô thị thông minh phù hợp điều kiện, đặc thù, nhu cầu thực tế, ưu tiên trước các dịch vụ giải quyết vấn đề bức thiết của xã hội, bảo đảm hiệu quả, tránh hình thức, lãng phí","Phát triển dịch vụ đô thị thông minh phù hợp điều kiện, đặc thù, nhu cầu thực tế, ưu tiên trước các dịch vụ phục vụ hoạt động nội bộ của cơ quan hành chính, bảo đảm hiệu quả, tránh hình thức, lãng phí"],c:2},{id:"vb13-112",s:"PHẦN 6 - BỔ SUNG: XÂY DỰNG VÀ PHÁT TRIỂN CHÍNH PHỦ ĐIỆN TỬ, CHÍNH PHỦ SỐ (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Mục II (điểm b khoản ©) Chương trình ban hành kèm theo Điều 1 Nghị quyền số 76 NGQ-C D,",gt:"Nghiên cứu, xây dựng Luật Chính phủ số thuộc nhóm hoàn thiện môi trường pháp lý. Nhóm phát triển dữ liệu số quốc gia gồm cơ sở dữ liệu chuyên ngành, kho dữ liệu công dân và hệ thống phân tích, xử lý dữ liệu tổng hợp.",mn:'Nhớ "luật thuộc môi trường pháp lý, kho và hệ thống thuộc dữ liệu": văn bản luật xếp vào nhóm pháp lý.',t:"m",q:"Phát triển dữ liệu số quốc gia là một nhóm nhiệm vụ của xây dựng, phát triển Chính phủ điện tử, Chính phủ số. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, nội dung nào dưới đây KHÔNG thuộc nhóm nhiệm vụ phát triển dữ liệu số quốc gia mà thuộc nhóm nhiệm vụ hoàn thiện môi trường pháp lý?",o:["Xây dựng Hệ thống phân tích, xử lý dữ liệu tổng hợp cấp bộ, cấp tỉnh đề tạo ra thông tin mới, dịch vụ dữ liệu mới XQ 7b XG-.PCCHHC.ƯU21-2Ụ020 Trang 5a","Nghiên cứu, xây dựng Luật Chính phủ số và các văn bản hướng dẫn thi hành để triển khai thực hiện","Xây dựng kho dữ liệu để lưu trữ dữ liệu điện tử của công dân khi thực hiện các giao dịch trực tuyến với cơ quan nhà nước","Phát triển các cơ sở dữ liệu chuyên ngành phục vụ ứng dụng, dịch vụ Chính phủ số trong nội bộ của bộ, ngành, địa phương"],c:1},{id:"vb13-113",s:"PHẦN 6 - BỔ SUNG: XÂY DỰNG VÀ PHÁT TRIỂN CHÍNH PHỦ ĐIỆN TỬ, CHÍNH PHỦ SỐ (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"VMục | (điểm b khoản 6) Chương trình ban hành kèm theo Điều 1 Nghị quyết xà ZNQ-(,P.",gt:"Chương trình yêu cầu xây dựng các kênh tương tác trực tuyến để người dân tham gia, giám sát hoạt động xây dựng, thực thi chính sách, pháp luật, ra quyết định của cơ quan nhà nước, không chỉ lấy ý kiến sau khi quyết định đã ban hành.",mn:'Nhớ "kênh trực tuyến cho dân tham gia và giám sát”: như dường dầy hai chiều giữa dân và cơ quan nhà nước.',t:"m",q:"Ông C là người dân muốn tham gia, giám sát hoạt động xây dựng, thực thi chính sách, pháp luật và ra quyết định của cơ quan nhà nước thông qua môi trường mạng. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, nhiệm vụ nào của Chương trình đáp ứng nhu cầu này?",o:["Xây dựng kênh tương tác trực tuyến để người dân tham gia, giám sát","Phát triển ứng dụng thanh toán điện tử không dùng tiền mặt","Hoàn thiện Cổng tham vấn điện tử về quy định kinh doanh","Xây dựng kênh tương tác trực tuyến để cơ quan nhà nước thu thập ý kiến của người dân sau khi quyết định đã được ban hành, phục vụ đánh giá kết quả thực hiện chính sách, pháp luật"],c:0},{id:"vb13-114",s:"PHẦN 6 - BỔ SUNG: XÂY DỰNG VÀ PHÁT TRIỂN CHÍNH PHỦ ĐIỆN TỬ, CHÍNH PHỦ SỐ (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Mục 1II (điểm b khoản 6) Chương trình ban hành kèm theo Điều 1 Nghị quyết SỐ ZoNQ-CP.",gt:"Chương trình đẩy mạnh sử dụng chữ ký số, định danh số, chuyển đổi số và niêm phong điện tử trong xử lý văn bản hành chính nhằm cắt giảm giấy tờ, nâng cao hiệu quả quản lý, đơn giản hóa quy trình. Việc duy trì song sống văn bản giấy trái mục tiêu này.",mn:'Nhớ "ký số - định danh - niêm phong điện tử thay giấy: văn bản đi bằng chữ ký điện tử, không cần giấy.',t:"m",q:"Đế cắt giảm giấy tờ, nâng cao hiệu quả quản lý nhà nước và đơn giản hóa quy trình nghiệp vụ trong xử lý văn bản hành chính, Chương trình đề ra nhiệm vụ gì liên quan đến công cụ sở? Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, nhiệm vụ đó là:",o:["Phát triển hệ thống làm việc từ xa của cơ quan nhà nước XQ 7b XG-.PCCHHC.ƯU21-2Ụ020 Trang ¬b","Sử dụng chữ ký số, định danh số và niêm phong điện tử song song với văn bản giấy tại mọi khâu xử lý, nhằm bảo đảm tính pháp lý trước khi chuyển dân sang môi trường điện tử","Xây dựng Cơ sở dữ liệu hộ tịch điện tử","Đẩy mạnh sử dụng chữ ký số, định danh số, niêm phong điện tử"],c:3},{id:"vb13-115",s:"PHẦN 6 - BỔ SUNG: XÂY DỰNG VÀ PHÁT TRIỂN CHÍNH PHỦ ĐIỆN TỬ, CHÍNH PHỦ SỐ (ĐIỀN KHUYẾT - PHÂN BIỆT - VẬN DỤNG)",cc:"Mục 1II (điểm b khoản 6) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 76/NQ-C.P.",gt:"Các nhóm nhiệm vụ gồm hoàn thiện môi trường pháp lý; phát triển hạ tầng số quốc gia; nền tảng và hệ thống số; dữ liệu số; ứng dụng, dịch vụ nội bộ; ứng dụng, dịch vụ phục vụ người dân, doanh nghiệp; đô thị thông minh. Phát triển hạ tầng giao thông đô thị không phải nhóm nhiệm vụ riêng.",mn:'Nhớ "pháp lý - hạ tầng số - nền tảng - dữ liệu - ứng dụng - đô thị thông minh": toàn là việc về số, không có việc xây dưỡng. Phân nông cáo tổng hợp: phân biệt các mốc chỉ tiêu đến năm 2025 và 2030 giữa các lĩnh vực; tình huống vận dụng thực tế gắn với 6 nội dung cải cách hành chính; liên hệ vai trò các cơ quan và tinh thần chung của Chương trình.',t:"m",q:"Xây dựng, phát triển Chính phủ điện tử, Chính phủ số có nhiều nhóm nhiệm vụ như hoàn thiện môi trường pháp lý, hạ tầng số, nền tảng và hệ thống số, dữ liệu số. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, nhóm nhiệm vụ nào dưới đây KHÔNG được nêu trong nội dung này?",o:["Phát triển hạ tầng giao thông đô thị","Hoàn thiện môi trường pháp lý","Phát triển dữ liệu số quốc gia","Phát triển hạ tổng số quốc gia"],c:0},{id:"vb13-116",s:"PHẦN 7 - VẬN DỤNG TỔNG HỢP, PHẦÂN BIỆT MỐC 2025/2030 VÀ TÌNH HUỐNG THỰC TIỄN",cc:"Mục III (điểm a khoản 2) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 76/NQ-CP.",gt:'Đến năm 2025, mức hài lòng tối thiểu là 90% với thủ tục hành chính nội chứng và 85% với lĩnh vực đất đai, xây dựng, đầu tư. Mức 95% và 90% là của năm 2030. ® Miẹo nhớ: Nhớ "2025: 90 và 85; 2030: 95 và 90”: lĩnh vực khó luôn thấp hơn mức chung năm điểm.',t:"m",q:"Chương trình đặt mục tiêu về mức độ hài lòng của người dân, doanh nghiệp đối với giải quyết thủ tục hành chính, có phân biệt giữa thủ tục nói chứng và các lĩnh vực đất đai, xây dựng, đầu tư. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, phương án nào ghép ĐÚNG mức tối thiểu đến năm 2025?",o:["Thủ tục hành chính nội chung đạt 95%; lĩnh vực đất đai, xây dựng, đầu tư đạt 90%","Thủ tục hành chính nội chung đạt 90%; lĩnh vực đất đai, xây dựng, đầu tư đạt 90%","Thủ tục hành chính nội chung đạt 85%; lĩnh vực đất đai, xây dựng, đầu tư đạt 90%","Thủ tục hành chính nội chung đạt 90%; lĩnh vực đất đai, xây dựng, đầu tư đạt 85%"],c:3},{id:"vb13-117",s:"PHẦN 7 - VẬN DỤNG TỔNG HỢP, PHẦÂN BIỆT MỐC 2025/2030 VÀ TÌNH HUỐNG THỰC TIỄN",cc:"Mục JI (điểm a khoản 35) Chương trình ban hành kèm theo Điều 1 Nghị quyết SỐ Z9 NQ-CVP.",gt:"Đến năm 2030: sự phục vụ của cơ quan hành chính nhà nước tối thiểu 95%, dịch vụ y tế, giáo dục công lập tối thiểu 90%. Mốc 90% và 85% là của năm 2025.",mn:'Nhớ "2030: 95 và 90; 2025: 90 và 85”: mỗi mốc cách nhau năm điểm phần trăm.',t:"m",q:"Chương trình nêu mức độ hài lòng tối thiểu đến năm 2030 của người dân, tổ chức đối với sự phục vụ của cơ quan hành chính nhà nước và đối với dịch vụ y tế, giáo dục công lập. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, phương án nào dưới đây ghép ĐÚNG?",o:["Sự phục vụ của cơ quan hành chính nhà nước: 90%; dịch vụ y tế, giáo dục công lập: 95%","Sự phục vụ của cơ quan hành chính nhà nước: 95%; dịch vụ y tế, giáo dục công lập: 90%","Sự phục vụ của cơ quan hành chính nhà nước: 95%; dịch vụ y tế, giáo dục công lập: 85%","Sự phục vụ của cơ quan hành chính nhà nước: 90%; dịch vụ y tế, giáo dục công lập: 85%"],c:1},{id:"vb13-118",s:"PHẦN 7 - VẬN DỤNG TỔNG HỢP, PHẦÂN BIỆT MỐC 2025/2030 VÀ TÌNH HUỐNG THỰC TIỄN",cc:"Điều 2 (khoản 3.4. 5. 8) Chương trình ban hành kèm theo Điều } Nghị quyền số ~©. NG-€",gt:"Bộ Nội vụ chủ trì cải cách tổ chức bộ máy hành chính, cải cách chế độ công vụ; Văn phòng Chính phủ chủ trì cải cách thủ tục hành chính; Bộ Thông tin và Truyền thông chủ trì phát triển Chính phủ điện tử, Chính phủ số. Bộ Tư pháp theo dõi, tổng hợp cải cách thể chế.",mn:'Nhớ "Nội vụ - Văn phòng Chính phủ - Thông tin và Truyền thông”: ba cơ quan đầu mối cho ba máng việc khác nhau.',t:"m",q:"Chương trình giáo các cơ quan chủ trì khác nhau cho từng nội dung cải cách, trong đó có cải cách tổ chức bộ máy, chế độ công vụ, thủ tục hành chính và Chính phủ điện tử, Chính phủ số. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, phương án nào dưới đây phân biệt DUNG cơ quan chủ trì?",o:["Bộ Nội vụ chủ trì cải cách tổ chức bộ máy, chế độ công vụ; Văn phòng Chính phủ chủ trì cải cách thủ tục hành chính; Bộ Tư pháp chủ trì phát triển Chính phủ điện tử, Chính phủ số","Bộ Nội vụ chủ trì cải cách tổ chức bộ máy, chế độ công vụ; Bộ Tư pháp chủ trì cải cách thủ tục hành chính; Bộ Thông tin và Truyền thông chủ trì phát triển Chính phủ điện tử, Chính phủ số","Bộ Nội vụ chủ trì cải cách tổ chức bộ máy, chế độ công vụ; Văn phòng Chính phủ chủ trì cải cách thủ tục hành chính; Bộ Thông tin và Truyền thông chủ trì phát triển Chính phủ điện tử, Chính phủ số","Bộ Nội vụ chủ trì cải cách thủ tục hành chính; Văn phòng Chính phủ chủ trì cải cách chế độ công vụ; Bộ Thông tin và Truyền thông chủ trì phát triển Chính phủ điện tử, Chính phủ số"],c:2},{id:"vb13-119",s:"PHẦN 7 - VẬN DỤNG TỔNG HỢP, PHẦÂN BIỆT MỐC 2025/2030 VÀ TÌNH HUỐNG THỰC TIỄN",cc:"Mục (II (phân mở đầu) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 76/NQ-CP.",gt:"Trọng tâm cải cách hành chính 10 năm tới gồm cải cách thể chế: xây dựng đội ngũ cán bộ, công chức, viên chức (chú trọng cải cách chính sách tiền lương): xây dựng và phát triển Chính phủ điện tử, Chính phủ số. Ba nội dung còn lại không năm trong bộ ba trọng tâm.",mn:'Nhớ "thể chế - con người - số hóa”: luật lệ, đội ngũ và công nghệ là ba trụ chính của 10 năm tới.',t:"m",q:"Trường hợp một cơ quan thường trực cải cách hành chính đáng lập kế hoạch ưu tiên nguồn lực cho giai đoạn 10 năm tới của Chương trình. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, bà nội dung được xác định là trọng tâm cải cách hành chính là:",o:["Cải cách tổ chức bộ máy hành chính nhà nước; xây dựng đội ngũ cán bộ, công chức, viên chức, chú trọng cải cách chính sách tiền lương; xây dựng, phát triển Chính phủ điện tử, Chính phủ số","Cải cách thể chế; cải cách tài chính công, chú trọng cải cách tự chủ đơn vị sự nghiệp; xây dựng, phát triển Chính phủ điện tử, Chính phủ số","Cải cách thể chế; xây dựng đội ngũ cán bộ, công chức, viên chức, chú trọng cải cách chính sách tiền lương: xây dựng, phát triển Chính phủ điện tử, Chính phủ số","Cải cách thể chế; xây dựng đội ngũ cán bộ, công chức, viên chức, chú trọng cải cách chính sách tiền lương; cải cách thủ tục hành chính"],c:2},{id:"vb13-120",s:"PHẦN 7 - VẬN DỤNG TỔNG HỢP, PHẦÂN BIỆT MỐC 2025/2030 VÀ TÌNH HUỐNG THỰC TIỄN",cc:"Mục 1II (điểm a khoản 6) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 76/NQ)-CP.",gt:"Đến năm 2025 Việt Nam thuộc nhóm 70 nước dẫn đầu về Chính phủ điện tử (EGDI); đến năm 2030 thuộc nhóm 50 nước dẫn đầu. Nhóm 30 là chỉ tiêu vệ môi trường kinh doanh.",mn:'Nhớ "EGDI: 70 rồi 50": mỗi mốc leo lên hai mươi bậc xếp hàng.',t:"m",q:"Chương trình đặt mục tiêu xếp hạng của Việt Nam về Chính phủ điện tử (EGDI) ở hai mốc 2025 và 2030. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, phương án nào dưới đây ghép ĐÚNG hai mốc này?",o:["Năm 2025 thuộc nhóm 70 nước dẫn đầu; năm 2030 thuộc nhóm 30 nước dẫn đầu","Năm 2025 thuộc nhóm 70 nước dẫn đầu; năm 2030 thuộc nhóm 50 nước dẫn đầu","Năm 2025 thuộc nhóm 50 nước dẫn đầu; năm 2030 thuộc nhóm 30 nước dẫn đầu","Năm 2025 thuộc nhóm 30 nước dẫn đầu; năm 2030 thuộc nhóm 50 nước dẫn đầu"],c:1},{id:"vb13-121",s:"PHẦN 7 - VẬN DỤNG TỔNG HỢP, PHẦÂN BIỆT MỐC 2025/2030 VÀ TÌNH HUỐNG THỰC TIỄN",cc:"Mục II (điểm a khoản 6) (.hướng trình ban hành kèm theo Điều 1 Nghị quyết số 76/NQ-CP.",gt:"Tại cấp bộ, cấp tỉnh: 90% vào năm 2025 và 100% vào năm 2030. Mức 60% - 70% là của cấp xã; các phương án còn lại không đúng mốc của cấp bộ, cấp tỉnh.",mn:"Nhớ “bộ - tỉnh: 90 rồi 100”: cấp càng cao càng đi trước.",t:"m",q:"Chương trình đạt tỷ lệ hồ sơ công việc tại cấp bộ, cấp tỉnh được xử lý trên môi trường mạng, trừ hồ sơ thuộc phạm vi bí mật nhà nước, ở hai mốc 2025 và 2030. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, phương án nào dưới đây ghép ĐÚNG?",o:["Năm 2025 đạt 60% hồ sơ; năm 2030 đạt 70% hồ sơ","Năm 2025 đạt 90% hồ sơ; năm 2030 đạt 90% hồ sơ","Năm 2025 đạt 90% hồ sơ; năm 2030 đạt 100% hồ sơ","Năm 2025 đạt 100% hồ sơ; năm 2030 đạt 100% hồ sơ"],c:2},{id:"vb13-122",s:"PHẦN 7 - VẬN DỤNG TỔNG HỢP, PHẦÂN BIỆT MỐC 2025/2030 VÀ TÌNH HUỐNG THỰC TIỄN",cc:"Mục!II (điểm a khoản 6) Chương trình ban hành kèm theo Điều 1 Nghị quyết số Z6/NQ-CP.",gt:"Tại cấp xã: 60% vào năm 2025 và 70% vào năm 2030. Mức 90% - 100% là của cấp bộ, cấp tỉnh.",mn:'Nhớ "xã: 60 rồi 70": cấp cơ sở tăng từng bước nhỏ nhưng chắc.',t:"m",q:"Chương trình có chỉ tiêu riêng cho hồ sơ công việc tại cấp xã được xử lý trên môi trường mạng, khác với cấp bộ, cấp tỉnh. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, phương án nào dưới đây ghép ĐÚNG chỉ tiêu cấp xã ở hai mốc 2025 và 2030?",o:["Năm 2025 đạt 80% hồ sơ; năm 2030 đạt 90% hồ sơ","Năm 2025 đạt 60% hồ sơ; năm 2030 đạt 70% hồ sơ","Năm 2025 đạt 50% hồ sơ; năm 2030 đạt 60% hồ sơ","Năm 2025 đạt 90% hồ sơ; năm 2030 đạt 100% hồ sơ"],c:1},{id:"vb13-123",s:"PHẦN 7 - VẬN DỤNG TỔNG HỢP, PHẦÂN BIỆT MỐC 2025/2030 VÀ TÌNH HUỐNG THỰC TIỄN",cc:"Mục III (điểm a khoản 4) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 76/NQ-CP.",gt:"Mục tiêu đến năm 2030 là 100% cán bộ, công chức cấp xã có trình độ cao đẳng, đại học và được chuẩn hóa về lý luận chính trị, chuyên môn, nghiệp vụ, kỹ năng làm việc.",mn:'Nhớ "cấp xã: 100% từ cao đẳng trở lên”: đội ngũ gần dân nhất phải đạt chuẩn trọn vẹn. VXỎQ 76:NO-CP CCHC 2021-2030 Irang b1',t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030: Về cải cách chế độ công vụ, đến năm 2030,[......... ] cán bộ, công chức cấp xã có trình độ cao đẳng, đại học và được chuẩn hóa về lý luận chính trị, chuyên môn, nghiệp vụ, kỹ năng làm việc.",o:["90%","80%","70%","100%"],c:3},{id:"vb13-124",s:"PHẦN 7 - VẬN DỤNG TỔNG HỢP, PHẦÂN BIỆT MỐC 2025/2030 VÀ TÌNH HUỐNG THỰC TIỄN",cc:"Mục HI (điểm ö khoản 3) Chương trình ban hành kèm theo Điều Ì Nghị quyết số 7b NQ-CP.",gt:"Biên chế sự nghiệp giảm tối thiểu bình quân 10% sø với năm 2021 vào năm 2025 và tiếp tục giảm bình quân 10% so với năm 2025 vào năm 2030. Mức 15% là chi trực tiếp từ ngân sách cho đơn vị sự nghiệp công lập giai đoạn 2030.",mn:'Nhớ "19% so với 2021, rồi 10% so với 2025”: mỗi lần so với mộc ngày trước.',t:"m",q:"Chỉ tiêu giảm biên chế sự nghiệp hưởng lương từ ngân sách nhà nước được đặt ra ở hai mốc 2025 và 2030 với mốc so sánh khác nhau. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, phương án nào dưới đây phân biệt ĐÚNG mức giảm và mốc so sánh?",o:["Đến năm 2025 giảm tối thiểu bình quân 10% so với năm 2021; đến năm 2030 tiếp tục giảm bình quân 10% so với năm 2021","Đến năm 2025 giảm tối thiểu bình quân 10% so với năm 2021; đến năm 2030 tiếp tục giảm bình quân 15% so với năm 2025","Đến năm 2025 giảm tối thiểu bình quân 10% so với năm 2020; đến năm 2030 tiếp tục giảm bình quân 10% so với năm 2025","Đến năm 2025 giảm tối thiểu bình quân 10% so với năm 2021; đến năm 2030 tiếp tục giảm bình quân 10% so với năm 2025"],c:3},{id:"vb13-125",s:"PHẦN 7 - VẬN DỤNG TỔNG HỢP, PHẦÂN BIỆT MỐC 2025/2030 VÀ TÌNH HUỐNG THỰC TIỄN",gt:"Đến năm 2025, có tối thiểu 20% đơn vị sự nghiệp công lập tự bảo đảm chi thường xuyên. Mức 100% áp dụng riêng cho đơn vị sự nghiệp kinh tế và sự nghiệp khác có đủ điều kiện.",mn:'Nhớ "tự bảo đảm chi thường xuyên: 20%": mỗi một phần năm đơn vị tự lo được chi thường xuyên.',t:"m",q:"Trường hợp Bộ Y tế rà soát cơ chế tài chính của các đơn vị sự nghiệp công lập thuộc ngành để nâng cao tính tự chủ, giảm gánh năng ngân sách. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, chỉ tiêu đến năm 2025 về tự chủ tài chính của đơn vị sự nghiệp công lập là gì?",o:["Tối thiểu 80% đơn vị sự nghiệp công lập tự bảo đảm chi thường xuyên","Tối thiểu 20% đơn vị sự nghiệp công lập tự bảo đảm chi thường xuyên","100% đơn vị sự nghiệp công lập tự bảo đảm chi thường xuyên","Tối thiểu 50% đơn vị sự nghiệp công lập tự bảo đảm chi thường xuyên"],c:1},{id:"vb13-126",s:"PHẦN 7 - VẬN DỤNG TỔNG HỢP, PHẦÂN BIỆT MỐC 2025/2030 VÀ TÌNH HUỐNG THỰC TIỄN",cc:"Mục III (điểm b khoản 2) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 76/NQ-CP.",gt:"Chương trình vêu cầu rà soát, đánh giá thủ tục hành chính, loại bỏ thủ tục rườm rà, chồng chéo dễ bị lợi dụng để tham nhũng, loại bỏ thành phần hồ sơ không cần thiết. Bổ sung thành phần hồ sơ đi ngược yêu cầu này.",mn:'Nhớ "rà soát rồi loại bỏ thủ tục chồng chéo”: đơn bớt công gác thì đương mới thông.',t:"m",q:"Trường hợp qua rà soát, nhiều thủ tục hành chính được xác định là rườm rà, chồng chéo, dễ bị lợi dụng để tham nhũng, gây khó khăn cho người dân, tố XQ 7b XG-.PCCHHC.ƯU21-2Ụ020 Trang b2 chức. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, hướng xử lý phù hợp là gì?",o:["Rà soát, đánh giá thủ tục hành chính trong quá trình thực hiện; loại bỏ các thủ tục rườm rà, chồng chéo dễ bị lợi dụng để tham nhũng","Kiểm soát chặt chẽ việc ban hành quy định thủ tục hành chính mới liên quan đến người dân, doanh nghiệp, giữ nguyên các thủ tục đang áp dụng","Rà soát, đánh giá thủ tục hành chính trong quá trình thực hiện; bổ sung thêm thành phần hồ sơ đề hạn chế tham nhũng","Rà soát, thống kê và đơn giản hóa các thủ tục hành chính nội bộ giữa các cơ quan hành chính nhà nước, giữ nguyên thủ tục với người dân"],c:0},{id:"vb13-127",s:"PHẦN 7 - VẬN DỤNG TỔNG HỢP, PHẦÂN BIỆT MỐC 2025/2030 VÀ TÌNH HUỐNG THỰC TIỄN",cc:"Mụuc JIÏ (điểm a khoản 2 và điểm a khoản 6) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 70/NQ- C.P.",gt:'Đến năm 2030, môi trường kinh doanh của Việt Nam thuộc nhóm 30 quốc gia hàng đầu; Chính phủ điện tử (EGDI) thuộc nhóm 50 nước dẫn đầu. Nhóm 70 là mốc EGDI của năm 2025. ® Miẹo nhớ: Nhớ "kinh doanh 30, EGDI 50": môi trường kinh doanh đặt mục tiêu cao hơn xếp hạng Chính phủ điện tử.',t:"m",q:"Chương trình đặt các chi tiêu xếp hạng đến năm 2030 cho môi trường kinh doanh của Việt Nam và Chính phủ điện tử (EGDI). Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, phương án nào dưới đây phân biệt ĐÚNG hai chỉ tiêu này?",o:["Môi trường kinh doanh thuộc nhóm 30 quốc gia hàng đầu; Chính phủ điện tử (EGDI) thuộc nhóm 70 nước dẫn đầu","Môi trường kinh doanh thuộc nhóm 30 quốc gia hàng đầu; Chính phủ điện tử (EGDI) thuộc nhóm 50 nước dẫn đầu","Môi trường kinh doanh thuộc nhóm 70 quốc gia hàng đầu; Chính phủ điện tử (EGDI) thuộc nhóm 50 nước dẫn đầu","Môi trường kinh doanh thuộc nhóm 50 quốc gia hàng đầu; Chính phủ điện tử (EGDI) thuộc nhóm 30 nước dẫn đầu"],c:1},{id:"vb13-128",s:"PHẦN 7 - VẬN DỤNG TỔNG HỢP, PHẦÂN BIỆT MỐC 2025/2030 VÀ TÌNH HUỐNG THỰC TIỄN",cc:"Mục III (điểm b khoản 3) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 76/NQ-CP.",gt:"Chương trình nêu ban hành cơ chế, chính sách kiểm soát quyền lực chặt chẽ, bảo đảm dân chủ, công khai, minh bạch và đề cao trách nhiệm giải trình trong phân cấp, kèm theo dõi, kiểm tra, giám sát việc thực hiện nhiệm vụ đã phân cấp.",mn:'Nhớ "phân cấp đi đôi với kiểm soát và giải trình”: giao quyền nhưng vẫn giữ sợi dây kiểm tra.',t:"m",q:"Khi đẩy mạnh phân cấp, phân quyền giữa Trung ương và địa phương, giữa cấp trên và cấp dưới, cần có cơ chế bảo đảm trách nhiệm giải trình và VQ zop'NQO-CP CCHC 2021-2030 rang bị kiểm soát quyền lực. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, Chương trình đề ra nhiệm vụ nào?",o:["Giao toàn quyền cho địa phương, hạn chế theo dõi, kiểm tra","Rà soát, sửa đổi, bổ sung quy định về phân cấp quản lý giữa Trung ương và địa phương, giữa các cấp ở địa phương, trước khi ban hành cơ chế kiểm soát và triển khai việc theo dõi, kiểm tra","Tập trung quyết định về cấp Trung ương để để theo dõi","Kiểm soát quyền lực chặt chẽ, đề cao trách nhiệm giải trình"],c:3},{id:"vb13-129",s:"PHẦN 7 - VẬN DỤNG TỔNG HỢP, PHẦÂN BIỆT MỐC 2025/2030 VÀ TÌNH HUỐNG THỰC TIỄN",cc:"Điều 2 (khoản 3, 4. 6) Chương trình ban hành kèm theo Điều 1 Nghị quyết SỐ 76/NQ-CP.",gt:"Bộ Nội vụ là cơ quan thường trực tổ chức triển khai thực hiện Chương trình. Bộ Tài chính chủ trì tổng hợp bố trí kinh phí và hoàn thiện cơ chế tự chủ tài chính của đơn vị sự nghiệp công lập, không phải cơ quan thường trực.",mn:'Nhớ "thường trực là Bộ Nội vụ”: một đầu mối thường trực cho cá chương trình lớn.',t:"m",q:"Nghị quyết giao trách nhiệm tổ chức thực hiện Chương trình cho các bộ, cơ quan khác nhau, trong đó có cơ quan thường trực, cơ quan theo dõi cải cách thể chế và cơ quan bố trí kinh phí. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, nhận định nào dưới đây về cơ quan chủ trì là KHÔNG đúng?",o:["Bộ Nội vụ là cơ quan thường trực tổ chức triển khai thực hiện Chương trình","Bộ Tư pháp theo dõi, tổng hợp việc triển khai nội dung cải cách thể chế","Bộ Tài chính là cơ quan thường trực tổ chức triển khai thực hiện toàn bộ Chương trình","Bộ Nội vụ chủ trì xây dựng phương pháp xác định Chỉ số cải cách hành chính hàng năm của các bộ và Ủy ban nhân dân cấp tỉnh"],c:2},{id:"vb13-130",s:"PHẦN 7 - VẬN DỤNG TỔNG HỢP, PHẦÂN BIỆT MỐC 2025/2030 VÀ TÌNH HUỐNG THỰC TIỄN",cc:"Điều 2 (khoản 3) Chương trình ban hành kèm theo Địcu 1 Nghị quyết số TNQ-CP.",gt:"Bộ Nội vụ chủ trì xây dựng, triển khai phương pháp theo dõi, đánh giá, xác định Chỉ số cải cách hành chính hàng năm và phương pháp đo lường sự hài lòng của người dân đối với sự phục vụ của cơ quan hành chính nhà nước.",mn:'Nhớ "chỉ số CCHƠG và đo hài lòng: Bộ Nội vụ”: cơ quan thường trực vừa chẩm diểm vừa do cầm nhận của dân.',t:"m",q:"Trường hợp tình Z cần công cụ để đánh giá kết quả cải cách hành chính hằng năm của các cơ quan hành chính và đo lường sự hài lòng của người dân đối với sự phục vụ. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải VQ76oNQ-CP CCHC 2021-7030 Irang b4 cách hành chính nhà nước giai đoạn 2021 - 2030, cơ quan nào chủ trì xây dựng, triển khai các phương pháp này?",o:["Văn phòng Chính phủ chủ trì xây dựng, triển khai phương pháp xác định Chỉ số cải cách hành chính và phương pháp đo lường sự hài lòng của người dân","Bộ Tài chính chủ trì xây dựng, triển khai phương pháp xác định Chỉ số cải cách hành chính và phương pháp đo lường sự hài lòng của người dân","Bộ Nội vụ chủ trì xây dựng, triển khai phương pháp xác định Chỉ số cải cách hành chính và phương pháp do lường sự hài lòng của người dân","Bộ Tư pháp chủ trì xây dựng, triển khai phương pháp xác định Chỉ số cải cách hành chính và phương pháp đo lường sự hài lòng của người dân"],c:2},{id:"vb13-131",s:"PHẦN 7 - VẬN DỤNG TỔNG HỢP, PHẦÂN BIỆT MỐC 2025/2030 VÀ TÌNH HUỐNG THỰC TIỄN",cc:"Điều 2 (khoản 1) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 7G NQ-CP.",gt:"Bộ Nội vụ tiến hành sơ kết đến năm 2025 và tổng kết, đánh giá đến năm 2029 kết quả thực hiện Chương trình tổng thể. Năm 2030 là mốc kết thúc giai đoạn, không phải mốc tổng kết.",mn:'Nhớ "sơ kết 2025, tổng kết 2029": tổng kết trước một năm để kịp chuẩn bị giai đoạn tiếp theo.',t:"m",q:"Nghị quyết quy định thời điểm tiến hành sơ kết, tổng kết và đánh giá kết quả thực hiện Chương trình tổng thể do cơ quan thường trực thực hiện. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, phương án nào dưới đây phân biệt ĐÚNG thời điểm sơ kết và tổng kết?",o:["Sơ kết vào năm 2025; tổng kết, đánh giá kết quả vào năm 2030","Sơ kết vào năm 2024; tổng kết, đánh giá kết quả vào năm 2030","Sơ kết vào năm 2026; tổng kết, đánh giá kết quả vào năm 2029","Sơ kết vào năm 2025; tổng kết, đánh giá kết quả vào năm 2029"],c:3},{id:"vb13-132",s:"PHẦN 7 - VẬN DỤNG TỔNG HỢP, PHẦÂN BIỆT MỐC 2025/2030 VÀ TÌNH HUỐNG THỰC TIỄN",cc:"Mục III (điểm a khoản 6) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 76/NQ-C.P.",gt:"Mục tiêu đến năm 2030 là tối thiểu 80% người trưởng thành có tài khoản giao dịch tại ngân hàng.",mn:'Nhớ "tài khoản ngân hàng: tối thiểu 80% ": bồn trên năm người lớn có tài khoán.',t:"m",q:"Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030: Về xây dựng và phát triển Chính phủ điện tử, Chính phủ số, đến năm 2030, tối thiểu [......... | người trưởng thành có tài khoản giao dịch tại ngân hàng.",o:["80% X9 765'NO-CP CC HIC. 2021-2030 Irang b5","90%","100%","50%"],c:0},{id:"vb13-133",s:"PHẦN 7 - VẬN DỤNG TỔNG HỢP, PHẦÂN BIỆT MỐC 2025/2030 VÀ TÌNH HUỐNG THỰC TIỄN",cc:"AMuc Ji (điểm b khoản 5} Chương trình ban hành kèm theo Điều Ì Nghị quyết s9 Z6 NQ-C.P.",gt:"Chương trình chuyển từ cấp phát bình quân sang cơ chế Nhà nước đặt hàng, giao nhiệm vụ căn cứ chất lượng đầu ra hoặc đấu thầu cung cấp dịch vụ sự nghiệp công. Các phương án khác đối căn cứ hoặc đáo chiều chuyển đổi.",mn:'Nhớ "từ chia đều sang đặt hàng theo chất lượng”: trả tiền theo sản phẩm tốt, không chia đều cho mọi nơi.',t:"m",q:"Để tạo cạnh tranh bình đẳng, nâng cao chất lượng và đa dạng hóa dịch vụ sự nghiệp công, Chương trình định hướng thay đổi cách hỗ trợ ngân sách cho dịch vụ sự nghiệp công. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, nội dung của định hướng đó là gì?",o:["Chuyển từ hỗ trợ theo cơ chế đặt hàng sang cơ chế cấp phát bình quân, giao nhiệm vụ cung cấp dịch vụ căn cứ vào chất lượng đầu ra hoặc đấu thầu","Chuyển từ hỗ trợ theo cơ chế cấp phát bình quân sang cơ chế Nhà nước đặt hàng, giao nhiệm vụ cung cấp dịch vụ căn cứ vào số lượng biên chế hoặc đấu thầu","Chuyển từ hỗ trợ theo cơ chế cấp phát bình quân sang cơ chế Nhà nước đặt hàng, giao nhiệm vụ cung cấp dịch vụ căn cứ vào chất lượng đầu ra hoặc giao chỉ tiêu tự chủ","Chuyển từ hỗ trợ theo cơ chế cấp phát bình quân sang cơ chế Nhà nước đặt hàng, giao nhiệm vụ cung cấp dịch vụ căn cứ vào chất lượng đầu ra hoặc đấu thầu"],c:3},{id:"vb13-134",s:"PHẦN 7 - VẬN DỤNG TỔNG HỢP, PHẦÂN BIỆT MỐC 2025/2030 VÀ TÌNH HUỐNG THỰC TIỄN",cc:"Mục II (điểm a khoản 2) (.hướng trình ban hành kèm theo Điều 1 Nghị quyết số 76/NQ-CP.",gt:"Năm 2021, tỷ lệ tối thiểu là 40% (Trung ương), 30% (cấp tỉnh), 15% (cấp xã). Các phương án khác hoán đổi hoặc dùng sai tỷ lệ của cấp khác.",mn:"Nhớ “40 - 30 - 15”: Trung ương, tỉnh, xã; cấp càng gần cơ sở thì xuất phát càng thấp.",t:"m",q:"Năm 2021, Chương trình đạt tỷ lệ tối thiểu số hóa kết quả giải quyết thủ tục hành chính đang còn hiệu lực và có giá trị sử dụng, tính riêng cho tùng cấp hành chính. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, phương án nào dưới đây ghép ĐÚNG tỷ lệ ở các cấp Trung ương, tỉnh và xã?",o:["Trung ương đạt 30%, cấp tỉnh đạt 20%, cấp xã đạt 159%","Trung ương đạt 40%, cấp tỉnh đạt 20%, cấp xã đạt 15%",'Trung ương đạt 40%, cấp tỉnh đạt 30%, cấp xã đạt 15% VOQ "6b YXQe-C.P CCHUC “021-2ỤU)0 Trang b5',"Trung ương đạt 40%, cấp tỉnh đạt 30%, cấp xã đạt 20%"],c:2},{id:"vb13-135",s:"PHẦN 7 - VẬN DỤNG TỔNG HỢP, PHẦÂN BIỆT MỐC 2025/2030 VÀ TÌNH HUỐNG THỰC TIỄN",cc:"Mục III (điểm a khoản 2) Chương trình ban hành kèm theo Điều 1 Nghị quyết số 76/NQ-CP.",gt:"Đến năm 2030, 90% người dân, doanh nghiệp tham gia hệ thống Chính phủ điện tử được xác thực định danh điện tử thông suốt và hợp nhất trên các hệ thống thông tin từ Trung ương đến địa phương. Mức 100% là chỉ tiêu năm 2025 đối với người đứng dịch vụ công trực tuyến.",mn:'Nhớ "2030: 90% xác thực hợp nhất”: gần như toàn dân dụng một danh tính sở cho mọi hệ thống.',t:"m",q:"Bà D đã được cấp định danh điện tử và sử dụng dịch vụ công trực tuyến. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, chỉ tiêu đến năm 2030 về việc xác thực định danh điện tử của người dân, doanh nghiệp tham gia hệ thống Chính phủ điện tử là gì?",o:["90% người dân, doanh nghiệp được xác thực định danh điện tử, nhưng xác thực riêng trên từng hệ thống thông tin của mỗi cấp chính quyền","100% người dân, doanh nghiệp được xác thực định danh điện tử thông suốt và hợp nhất trên tất cả các hệ thống thông tin của các cấp chính quyền","80% người dân, doanh nghiệp được xác thực định danh điện tử thông suốt và hợp nhất trên tất cả các hệ thống thông tin của các cấp chính quyền","90% người dân, doanh nghiệp được xác thực định danh điện tử thông suốt và hợp nhất trên tất cả các hệ thống thông tin của các cấp chính quyền"],c:3},{id:"vb13-136",s:"PHẦN 7 - VẬN DỤNG TỔNG HỢP, PHẦÂN BIỆT MỐC 2025/2030 VÀ TÌNH HUỐNG THỰC TIỄN",cc:"Mục II (phần mở dùu) Chương trình ban hành kèm theo Điều 1 Nghị quyết SỐ 76/NQ-CP.",gt:"Sáu nội dung gồm: thể chế; thủ tục hành chính; tổ chức bộ máy hành chính nhà nước; chế độ công vụ; tài chính công; Chính phủ điện tử, Chính phủ số. Cải cách lập pháp, tư pháp và đối mới phương thức lãnh đạo của Đảng được nhắc ở phần quan điểm, không phải nội dung cải cách.",mn:'Nhớ "thể chế - thủ tục - bộ máy - công vụ - tài chính - số": sáu mảng xếp theo thứ tự quen thuộc.',t:"m",q:"Chương trình xác định cải cách hành chính nhà nước giai đoạn 2021 - 2030 tập trung vào sau nội dung. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, phương án nào dưới đây liệt kê ĐÚNG và ĐẦY ĐỦ sáu nội dung đó?",o:["Cải cách thể chế; thủ tục hành chính; tổ chức bộ máy hành chính nhà nước; chế độ công vụ; tài chính công: đổi mới phương thức lãnh đạo của Đảng","Cải cách lập pháp; thủ tục hành chính; tổ chức bộ máy hành chính nhà nước; chế độ công vụ; tài chính công: xây dựng, phát triển Chính phủ điện tử, Chính phủ số","Cải cách thể chế; thủ tục hành chính; tổ chức bộ máy hành chính nhà nước; chế độ công vụ; tài chính công: xây dựng, phát triển Chính phủ điện tử, Chính phủ số VQ76oNQ-CP CCHC 2021-7030 Irang b7","Cải cách thể chế; tư pháp; tổ chức bộ máy hành chính nhà nước; chế độ công vụ; tài chính công: xây dựng, phát triển Chính phủ điện tử, Chính phủ số"],c:2},{id:"vb13-137",s:"PHẦN 7 - VẬN DỤNG TỔNG HỢP, PHẦÂN BIỆT MỐC 2025/2030 VÀ TÌNH HUỐNG THỰC TIỄN",cc:"Mục II Chuưt;ng trình ban hành kèm theo Điều 1 Nghị quyết số 76/NQ- cP.",gt:"Mục tiêu chung là xây dựng nền hành chính dân chủ, chuyên nghiệp, hiện đại, tinh gọn, hiệu lực, hiệu quả, có năng lực kiến tạo phát triển, liêm chính, phục vụ nhân dân. Các phương án khác thay đổi một cụm từ (điều tiết thị trường, kỷ cương, phục vụ doanh nghiệp, đồng bộ).",mn:'Nhớ "dân chủ - chuyên nghiệp - hiện đại - tinh gọn - kiến tạo - liêm chính - phục vụ nhân dân”: chuỗi tính từ kết thúc băng phục vụ nhân dân.',t:"m",q:"Mục tiêu chung của Chương trình đặt ra định hướng tống quát cho nền hành chính trong giai đoạn 2021 - 2030, trên cơ sở quan điểm, chủ trương, đường lối của Đảng. Theo Nghị quyết số 76/NQ-CP về Chương trình tổng thể cải cách hành chính nhà nước giai đoạn 2021 - 2030, phương án nào dưới đây nêu ĐÚNG mục tiêu chung?",o:["Xây dựng nền hành chính dân chủ, chuyên nghiệp, hiện đại, tinh gọn, hiệu lực, hiệu quả, có năng lực điều tiết thị trường, liêm chính, phục vụ nhân dân","Xây dựng nền hành chính dân chủ, chuyên nghiệp, hiện đại, tinh gọn, hiệu lực, hiệu quả, có năng lực kiến tạo phát triển, liêm chính, phục vụ nhân dân","Xây dựng nền hành chính dân chủ, chuyên nghiệp, hiện đại, đồng bộ, hiệu lực, hiệu quả, có năng lực kiến tạo phát triển, liêm chính, phục vụ nhân dân","Xây dựng nền hành chính dân chủ, chuyên nghiệp, hiện đại, tinh gọn, hiệu lực, hiệu quả, có năng lực kiến tạo phát triển, kỷ cương, phục vụ doanh nghiệp"],c:1}];export{n as default};
